// Instrucciones del catálogo (free-exercise-db, inglés) traducidas a portugués de Brasil.
// Clave = `exercises.name` original; valor = pasos unidos con "\n", igual que
// la columna `instructions` de la DB. Ver `localizedInstructions` en
// `exerciseLabels.ts` para el fallback al inglés.
export const exerciseInstructionsPt: Record<string, string> = {
  '3/4 Sit-Up':
    'Deite-se no chão, prenda os pés e flexione os joelhos.\nColoque as mãos atrás ou ao lado da cabeça, com as costas apoiadas no chão.\nFlexione o quadril e a coluna para elevar o tronco em direção aos joelhos.\nSuba até o tronco ficar perpendicular ao chão, depois desça apenas ¾ do caminho.\nRepita o número de repetições recomendado.',
  '90/90 Hamstring':
    'Deite-se de costas, com uma perna estendida para a frente.\nFlexione o quadril e o joelho da outra perna a 90 graus; apoie-a com as mãos se precisar.\nEstenda a perna para o alto, pause brevemente e volte à posição inicial.\nRepita de 10 a 20 repetições e depois troque de perna.',
  'Ab Crunch Machine':
    'Sente-se com pouca carga, pés sob os apoios e alças seguras; braços a 90° com os tríceps apoiados.\nEleve as pernas e faça o crunch com o tronco enquanto expira; vá devagar e use só os abdominais.\nApós uma pausa de um segundo, volte lentamente à posição inicial enquanto inspira.\nRepita o movimento pelo número de repetições prescrito.',
  'Ab Roller':
    'Segure a roda abdominal com as duas mãos e ajoelhe-se no chão.\nApoie a roda no chão à sua frente e sustente-se nas mãos e joelhos, como em uma flexão de joelhos.\nRole a roda para a frente em linha reta, alongando o corpo sem tocar o chão, enquanto inspira.\nVolte à posição inicial expirando, bem devagar e com os abdominais contraídos o tempo todo.',
  Adductor:
    'Deite-se de bruços com uma perna sobre um rolo de espuma.\nGire a perna para o rolo pressionar a parte interna da coxa, com todo o peso que tolerar.\nRelaxe a coxa e role entre o quadril e o joelho; mantenha cada ponto de tensão por 10-30 segundos e troque de perna.',
  'Adductor/Groin':
    'Deite-se de costas com os pés elevados em direção ao teto.\nPeça ao seu parceiro para segurar seus pés ou tornozelos e abra as pernas o máximo que puder.\nTente juntar as pernas com força por 10 segundos ou mais enquanto seu parceiro impede o movimento.\nRelaxe as pernas enquanto seu parceiro as afasta até um alongamento confortável; avise-o para não forçar demais.',
  'Advanced Kettlebell Windmill':
    'Faça um clean e press de um kettlebell acima da cabeça com um braço.\nCom o braço estendido, empurre o quadril para trás; braço livre atrás e pés a 45° do braço com o kettlebell.\nDesça o máximo que puder.\nFaça uma pausa de um segundo e inverta o movimento até a posição inicial.',
  'Air Bike':
    'Deite-se de costas com a lombar pressionada no chão, mãos ao lado da cabeça, e eleve os ombros em um crunch.\nLeve os joelhos para cima até ficarem perpendiculares ao chão, com as canelas paralelas ao solo.\nPedale devagar, estenda a perna direita e leve o cotovelo direito ao joelho esquerdo, expirando.\nVolte à posição inicial enquanto inspira.\nFaça o abdominal para o lado oposto pedalando, levando o cotovelo esquerdo ao joelho direito, e expire.\nContinue alternando até completar todas as repetições recomendadas para cada lado.',
  'All Fours Quad Stretch':
    'Fique de quatro apoios sobre mãos e joelhos, levante uma perna e segure o pé com a mão.\nSegure o pé ou o tornozelo mantendo o joelho flexionado, alongando quadríceps e flexores do quadril.\nEmpurre o quadril em direção ao chão e mantenha por 10-20 segundos; depois troque de lado.',
  'Alternate Hammer Curl':
    'Fique em pé com o tronco ereto, um halter em cada mão e os braços estendidos junto ao tronco.\nGire as palmas das mãos para o tronco.\nSuba o halter direito contraindo o bíceps até a altura do ombro, expirando; pause 1 s, movendo só o antebraço.\nBaixe lentamente o halter até a posição inicial enquanto inspira.\nRepita o movimento com a mão esquerda; isso equivale a uma repetição.\nContinue alternando pelo número de repetições recomendado.',
  'Alternate Heel Touchers':
    'Deite-se com os joelhos flexionados, pés afastados 45-60 cm e braços estendidos ao lado do corpo.\nFaça um abdominal 8-10 cm para o lado direito e toque o calcanhar direito, mantendo 1 segundo enquanto expira.\nVolte lentamente à posição inicial enquanto inspira.\nFaça o abdominal para o lado esquerdo, toque o calcanhar esquerdo por 1 segundo e volte; tocar os dois calcanhares é 1 repetição.\nContinue alternando os lados até concluir todas as repetições prescritas.',
  'Alternate Incline Dumbbell Curl':
    'Sente-se em um banco inclinado com um halter em cada mão, braços estendidos e cotovelos junto ao tronco.\nSuba o halter direito girando a palma para cima até o ombro, expirando; pause 1 s movendo só o antebraço.\nBaixe lentamente o halter até a posição inicial enquanto inspira.\nRepita o movimento com a mão esquerda; isso equivale a uma repetição.\nContinue alternando pelo número de repetições recomendado.',
  'Alternate Leg Diagonal Bound':
    'Assuma uma postura confortável com um pé ligeiramente à frente do outro.\nImpulsione-se com a perna da frente, levando o joelho oposto para a frente e o mais alto possível antes de aterrissar.\nUse uma linha no chão como referência para medir a distância de lado a lado.\nRepita a sequência com a outra perna.',
  'Alternating Cable Shoulder Press':
    'Coloque os cabos na parte inferior da torre e selecione uma carga adequada.\nSegure os cabos na altura dos ombros, com as palmas voltadas para a frente.\nCom a cabeça e o peito erguidos, estenda o cotovelo para empurrar um lado diretamente acima da cabeça.\nApós uma pausa no topo, volte à posição inicial e repita com o lado oposto.',
  'Alternating Deltoid Raise':
    'Em pé, segure um par de halteres ao lado do corpo.\nCom os cotovelos ligeiramente flexionados, eleve os halteres à frente até a altura dos ombros, sem balançar.\nVolte os halteres para o lado do corpo.\nNa repetição seguinte, eleve os halteres para os lados até a altura dos ombros.\nVolte à posição inicial e continue alternando entre a elevação frontal e lateral.',
  'Alternating Floor Press':
    'Deite-se no chão com dois kettlebells ao lado dos ombros.\nEleve os dois kettlebells sobre o peito, segurando-os pela alça com as palmas voltadas para a frente.\nEstenda os dois braços sobre o peito; baixe um kettlebell ao peito girando o punho em direção ao que fica estendido.\nEleve o kettlebell e repita com o lado oposto.',
  'Alternating Hang Clean':
    'Coloque dois kettlebells entre os pés; empurre o quadril para trás e olhe para a frente na posição inicial.\nFaça clean de um kettlebell ao ombro estendendo pernas e quadril e girando o punho, com o outro pendurado.\nBaixe o kettlebell à posição pendurada e faça o clean com o outro; repita.',
  'Alternating Kettlebell Press':
    'Faça clean de dois kettlebells aos ombros estendendo pernas e quadril, girando os punhos.\nEmpurre um kettlebell acima da cabeça estendendo o cotovelo e girando a palma para a frente, com o outro parado.\nBaixe o kettlebell à posição inicial e empurre imediatamente com o outro braço.',
  'Alternating Kettlebell Row':
    'Coloque dois kettlebells à frente dos pés, flexione os joelhos, empurre o quadril para trás e segure as alças.\nLevante um kettlebell do chão segurando o outro; retraia a escápula e flexione o cotovelo levando-o ao abdômen ou costelas.\nBaixe o kettlebell do braço que trabalha e repita com o outro braço.',
  'Alternating Renegade Row':
    'Coloque dois kettlebells no chão na largura dos ombros e apoie-se nas alças com o corpo reto, como em uma flexão.\nEmpurre um kettlebell contra o chão e reme com o outro, retraindo a escápula e levando-o em direção ao seu lado.\nBaixe o kettlebell ao chão e repita com a mão oposta por várias repetições.',
  'Ankle Circles':
    'Use um objeto firme, como um rack de agachamento, para se apoiar.\nLevante a perna direita cerca de 5 cm e desenhe círculos grandes com o dedão; cada círculo é 1 repetição.\nQuando terminar com o pé direito, repita com a perna esquerda.',
  'Ankle On The Knee':
    'Deitado, flexione os joelhos e mantenha os pés no chão.\nColoque o tornozelo de um pé sobre o joelho oposto.\nSegure a coxa ou o joelho da perna de baixo e puxe as duas pernas ao peito; mantenha 10-20 s e troque de lado.',
  'Anterior Tibialis-SMR':
    'Sente-se no chão com as pernas flexionadas e os pés apoiados.\nPressione a canela externa com um rolo, do joelho ao tornozelo, pausando 10-30 s por ponto; troque de perna.',
  'Anti-Gravity Press':
    'Coloque uma barra no chão atrás da cabeceira de um banco inclinado.\nDe bruços no banco, levante a barra com pegada pronada e, flexionando os cotovelos, leve-a perto do peito.\nEmpurre a barra para a frente estendendo os cotovelos, mantendo os braços paralelos ao chão.\nVolte à posição inicial e repita até completar a série.',
  'Arm Circles':
    'Fique em pé e estenda os braços retos para os lados, paralelos ao chão e perpendiculares ao tronco.\nFaça círculos de cerca de 30 cm de diâmetro com cada braço estendido, respirando normalmente.\nContinue por cerca de dez segundos e depois inverta a direção dos círculos.',
  'Arnold Dumbbell Press':
    'Sente-se com apoio para as costas e segure dois halteres à frente do peito, palmas para você e cotovelos junto ao tronco.\nEleve os halteres girando as palmas até ficarem voltadas para a frente.\nContinue subindo até estender os braços acima da cabeça, expirando.\nApós uma pausa de 1 segundo, baixe girando as palmas para você (esquerda anti-horário, direita horário) enquanto inspira.\nRepita o número de repetições recomendado.',
  'Around The Worlds':
    'Deite-se em um banco reto, halteres em cada mão, palmas para o teto, braços junto às coxas e cotovelos pouco flexionados.\nMova os halteres em semicírculo das coxas até acima da cabeça, braços paralelos ao chão, inspirando.\nInverta o movimento para voltar o peso à posição inicial enquanto expira.',
  'Atlas Stone Trainer':
    'Este equipamento substitui a pedra Atlas quando não há acesso a uma, usando pontas de barra ou tubo pesado.\nCarregue o peso desejado na barra, posicione-se sobre ele, abrace-o com os braços e flexione o quadril.\nPuxe o peso passando os joelhos; ao passá-los, apoie-o nas coxas sentando-se para trás e abrace-o contra o peito.\nEstenda o quadril e os joelhos para elevar o peso o mais alto possível; volte-o às coxas ou ao chão para repetir.',
  'Atlas Stones':
    'Com a pedra entre os pés, flexione o quadril e envolva-a com os braços, colocando os dedos sob a base plana.\nPuxe a pedra em direção ao tronco e empurre com a parte de trás dos pés para tirá-la do chão.\nQuando a pedra passar dos joelhos, apoie-a sentando-se para trás e subindo-a sobre as coxas.\nSuba a pedra ao peito trocando a pegada, levante-se e estenda o quadril na plataforma para elevá-la ao máximo.',
  'Axle Deadlift':
    'Aproxime-se da barra centrada sobre os pés, na largura do quadril, e segure-a na largura dos ombros com pegada mista.\nRespire fundo, abaixe o quadril e flexione os joelhos até as canelas tocarem a barra; empurre com os calcanhares.\nQuando a barra passar dos joelhos, puxe-a para trás juntando as escápulas e empurrando o quadril para a frente.\nBaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Back Flyes - With Bands':
    'Passe uma faixa elástica ao redor de um poste fixo, como o de um rack de agachamento.\nSegure a faixa pelas alças e afaste-se até tensioná-la.\nEstenda os braços retos à frente, paralelos ao chão e perpendiculares ao tronco; pés na largura dos ombros (posição inicial).\nAo expirar, leve os braços para os lados e para trás, estendidos e paralelos ao chão, até abri-los totalmente.\nFaça uma pausa e volte à posição inicial inspirando.\nRepita o número de repetições recomendado.',
  'Backward Drag':
    'Carregue um trenó com o peso desejado e prenda uma corda ou alças para arrastá-lo.\nIncline-se para trás e avance com passos curtos, movendo-se para trás pela distância indicada o mais rápido possível.',
  'Backward Medicine Ball Throw':
    'Faça com um parceiro; sem um, arremesse a bola contra uma parede e busque-a de volta.\nFique em pé a alguns metros do seu parceiro, ambos na mesma direção, com a bola entre as pernas.\nAgache e depois estenda o corpo com força, arremessando a bola por cima da cabeça para o parceiro.\nReceba a bola que o parceiro rola de volta e repita pelo número de repetições desejado.',
  'Balance Board':
    'Coloque uma prancha de equilíbrio à sua frente.\nSuba nela e tente manter o equilíbrio.\nMantenha o equilíbrio pelo tempo que desejar.',
  'Ball Leg Curl':
    'Deite-se de costas no chão com os pés sobre a bola.\nPosicione a bola sob os tornozelos com as pernas estendidas (posição inicial).\nEleve o quadril do chão, apoiando o peso nas escápulas e nos pés.\nFlexione os joelhos e puxe a bola o mais perto possível, contraindo os posteriores de coxa.\nFaça uma breve pausa e volte à posição inicial.',
  'Band Assisted Pull-Up':
    'Passe a faixa pelo centro da barra fixa e ajuste-a com um laço; use faixas diferentes para variar a assistência.\nPuxe a faixa para baixo, coloque um joelho no laço sem deixar escorregar e segure a barra com pegada média a ampla (posição inicial).\nPuxe-se para cima contraindo os dorsais e flexionando o cotovelo em direção ao lado, até o queixo passar a barra, sem balançar.\nFaça uma breve pausa e volte à posição inicial.',
  'Band Good Morning':
    'Pise em uma ponta de uma faixa de 41 polegadas com os pés um pouco afastados e passe a outra ponta por trás do pescoço (posição inicial).\nCom as pernas retas, estenda o quadril até ficar quase na vertical.\nDesça de volta à posição inicial sem arredondar as costas.',
  'Band Good Morning (Pull Through)':
    'Passe a faixa ao redor de um poste, afaste-se e passe a outra ponta por trás do pescoço, segurando-a com as mãos.\nFlexione o quadril levando-o para trás, costas retas, inclinando-se cerca de 90 graus com os joelhos pouco flexionados.\nVolte à posição inicial empurrando com o quadril até ficar em pé.',
  'Band Hip Adductions':
    'Prenda uma faixa elástica ao redor de um poste sólido ou outro objeto fixo.\nFique com o lado esquerdo voltado ao poste e passe o pé direito pela faixa, ajustando-a ao tornozelo.\nFique em pé, segurando o poste se precisar (posição inicial).\nCom o joelho reto, eleve a perna direita para o lado o máximo que puder.\nVolte à posição inicial e repita pelo número de repetições desejado.\nTroque de lado.',
  'Band Pull Apart':
    'Estenda os braços retos à sua frente, segurando a faixa com as duas mãos.\nAbra os braços para fora, para os lados, em um movimento de abertura inversa.\nMantenha os cotovelos estendidos e leve a faixa ao peito, com os ombros para trás.\nFaça uma pausa ao completar o movimento e volte à posição inicial de forma controlada.',
  'Band Skull Crusher':
    'Prenda uma faixa na base de um rack ou do banco e deite-se alinhando a faixa com a cabeça.\nSegure a faixa com os cotovelos elevados, braço superior perpendicular ao chão e cotovelo flexionado sobre a cabeça (posição inicial).\nEstenda o cotovelo para esticar o braço sem mover o braço superior; pause no topo e volte à posição inicial.',
  'Barbell Ab Rollout':
    'Assuma a posição de flexão de braço segurando uma barra olímpica carregada com 5-10 lbs de cada lado, em vez de apoiar as mãos (posição inicial).\nCom um leve arco nas costas, eleve o quadril e expire enquanto rola a barra em direção aos pés, abdômen contraído e braços perpendiculares ao chão.\nContraia por um segundo no topo e, inspirando, role a barra lentamente de volta para a frente até a posição inicial.\nRepita o número de repetições recomendado.',
  'Barbell Ab Rollout - On Knees':
    'Ajoelhe-se no chão segurando uma barra olímpica carregada com 5-10 lbs de cada lado.\nColoque a barra no chão à sua frente, apoiado nas mãos e nos joelhos, como em uma flexão com joelhos no chão (posição inicial).\nInspire e role a barra para a frente em linha reta, baixando o corpo o máximo possível sem tocar o chão.\nPause um segundo alongado e, expirando, volte devagar à posição inicial com os abdominais contraídos.',
  'Barbell Bench Press - Medium Grip':
    'Retire a barra do rack com pegada média, braços estendidos acima de você, deitado em um banco reto (posição inicial).\nInspire e desça a barra lentamente até tocar a parte média do peito.\nPause um segundo contraindo o peito, expire e empurre a barra; descer deve levar o dobro de subir.\nRepita o movimento pelo número de repetições prescrito.\nColoque a barra de volta no rack ao terminar.',
  'Barbell Curl':
    'Fique em pé com o tronco ereto, barra com pegada na largura dos ombros, palmas para a frente e cotovelos perto do tronco (posição inicial).\nExpire e suba a barra contraindo o bíceps, movendo apenas os antebraços.\nSuba até contrair o bíceps por completo com a barra na altura dos ombros; aperte por um segundo.\nInspire e baixe a barra lentamente até a posição inicial.\nRepita o número de repetições recomendado.',
  'Barbell Curls Lying Against An Incline':
    'Deite-se contra um banco inclinado com os braços pendurados na vertical segurando uma barra (posição inicial).\nExpire e suba o peso o mais alto possível apertando o bíceps, movendo apenas os antebraços sem balançar.\nContraia por um segundo no topo e inspire enquanto volta lentamente à posição inicial, descendo por completo.\nRepita o número de repetições recomendado.',
  'Barbell Deadlift':
    'Fique em pé diante de uma barra carregada.\nFlexione os joelhos, incline-se com as costas retas e segure a barra com pegada pronada na largura dos ombros (posição inicial); use straps.\nExpire e empurre com as pernas levando o tronco à posição ereta, peito estufado e escápulas para trás.\nFlexione os joelhos e incline o tronco à frente a partir da cintura, costas retas, até os pesos tocarem o chão (posição inicial).\nRealize o número de repetições prescrito no programa.',
  'Barbell Full Squat':
    'Em um rack de agachamento, coloque a barra acima da altura dos ombros e apoie-a na parte de trás deles.\nSegure a barra dos dois lados e retire-a do rack empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack com os pés na largura dos ombros, pontas para fora, cabeça erguida e costas retas (posição inicial).\nInspire e desça flexionando joelhos e quadril para trás, até os posteriores de coxa chegarem às panturrilhas.\nExpire e suba empurrando o calcanhar ou o meio do pé, endireitando pernas e quadril até a posição inicial.\nRepita o número de repetições recomendado.',
  'Barbell Glute Bridge':
    'Sente-se com uma barra carregada sobre as pernas, role-a sobre o quadril e deite-se de costas (use almofada se incomodar).\nEmpurre com os calcanhares e estenda o quadril verticalmente através da barra, apoiando o peso na parte superior das costas e nos calcanhares.\nEstenda o máximo possível e depois volte à posição inicial.',
  'Barbell Guillotine Bench Press':
    'Retire a barra do rack com pegada média, braços estendidos acima do pescoço (posição inicial).\nInspire e desça a barra lentamente até ficar a cerca de 2,5 cm do pescoço.\nPause um segundo, expire e empurre a barra com o peito; descer deve levar ao menos o dobro de subir.\nRepita o movimento pelo número de repetições prescrito.\nColoque a barra de volta no rack ao terminar.',
  'Barbell Hack Squat':
    'Fique em pé segurando uma barra atrás de você com os braços estendidos e os pés na largura dos ombros, palmas para trás (posição inicial).\nCom a cabeça e o olhar erguidos e as costas retas, inspire e agache até as coxas ficarem paralelas ao chão.\nExpire e suba empurrando principalmente com o calcanhar e apertando as coxas.\nRepita o número de repetições recomendado.',
  'Barbell Hip Thrust':
    'Sente-se no chão com um banco logo atrás de você e uma barra carregada sobre as pernas (use barra grossa ou almofada para mais conforto).\nRole a barra sobre o quadril e recline-se contra o banco com as escápulas perto da parte superior dele.\nEmpurre com os pés, estenda o quadril através da barra com o peso nas escápulas e nos pés, e volte à posição inicial.',
  'Barbell Incline Bench Press - Medium Grip':
    'Deite-se em banco inclinado, retire a barra com pegada média, braços estendidos acima de você (posição inicial).\nInspire e desça lentamente até sentir a barra na parte superior do peito.\nPause um segundo, expire, empurre a barra com o peito e estenda os braços; descer leva o dobro de subir.\nRepita o movimento pelo número de repetições prescrito.\nColoque a barra de volta no rack ao terminar.',
  'Barbell Incline Shoulder Raise':
    'Deite-se em banco inclinado, segure a barra com pegada um pouco mais larga que os ombros, braços estendidos (posição inicial).\nExpire e levante a barra protraindo as escápulas e elevando os ombros do banco, com os braços retos.\nInspire e volte a barra à posição inicial.\nRepita o número de repetições recomendado.',
  'Barbell Lunge':
    'Em um rack de agachamento, posicione a barra um pouco abaixo da altura dos ombros e apoie-a na parte de trás deles.\nSegure a barra dos dois lados e retire-a do rack empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack, dê um passo à frente com a perna direita e desça em afundo, tronco ereto; o joelho não deve passar a ponta do pé.\nExpire e empurre com o calcanhar para subir e voltar à posição inicial.\nRepita o movimento pelo número de repetições recomendado e depois troque para a perna esquerda.',
  'Barbell Rear Delt Row':
    "Fique em pé, com a coluna reta, segurando uma barra com pegada larga e pronada (palmas voltadas para o corpo).\nFlexione os joelhos e incline-se com a coluna em arco natural, paralelo ao chão e cotovelos em 'T' (posição inicial).\nExpire e puxe a barra até o peito alto, contraindo os deltoides posteriores, braços perpendiculares ao tronco, sem usar o bíceps.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.",
  'Barbell Rollout from Bench':
    'Coloque uma barra no chão junto a um banco, ajoelhe-se sobre o banco e segure-a com pegada média a estreita (posição inicial).\nEstenda os quadris para rolar a barra lentamente para a frente, flexionando o ombro para levá-la acima da cabeça com os braços estendidos.\nQuando a barra chegar o mais longe possível, volte à posição inicial.',
  'Barbell Seated Calf Raise':
    'Coloque um bloco a cerca de 30 cm à frente de um banco reto.\nSente-se no banco e apoie a parte da frente dos pés sobre o bloco.\nPeça a alguém que coloque uma barra sobre suas coxas, cerca de 3 polegadas acima dos joelhos, e a mantenha ali (posição inicial).\nExpire e suba na ponta dos pés o mais alto possível, contraindo as panturrilhas.\nContraia por um segundo e volte lentamente, alongando as panturrilhas o máximo que puder.\nRepita pelo número de repetições recomendado.',
  'Barbell Shoulder Press':
    'Sente-se com encosto dentro de um rack de agachamento e segure a barra, posicionada um pouco acima da cabeça, com pegada pronada.\nLevante a barra acima da cabeça estendendo os braços, na altura dos ombros e um pouco à frente da cabeça (posição inicial).\nInspire e abaixe a barra lentamente até os ombros.\nExpire e levante a barra de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Barbell Shrug':
    'Em pé, coluna reta e pés na largura dos ombros, segure a barra à frente com pegada pronada, um pouco mais larga (posição inicial).\nExpire e eleve os ombros o máximo possível, sem usar os bíceps; mantenha a contração por um segundo.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Barbell Shrug Behind The Back':
    'Em pé, coluna reta, pés na largura dos ombros; segure a barra atrás do corpo com pegada pronada, mãos um pouco mais afastadas que os ombros (use munhequeiras ou straps se precisar).\nEleve os ombros o máximo possível expirando e segure a contração por 1 segundo; não use os bíceps, braços sempre estendidos.\nVolte lentamente à posição inicial inspirando.\nRepita pelo número de repetições recomendado.',
  'Barbell Side Bend':
    'Em pé, coluna reta, barra apoiada atrás dos ombros (abaixo do pescoço), pés na largura dos ombros.\nCom as costas retas e cabeça erguida, incline-se para a direita a partir da cintura inspirando; segure 1 segundo e volte expirando, sem mover o resto do corpo.\nRepita inclinando-se para a esquerda; segure 1 segundo e volte à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Barbell Side Split Squat':
    'Em pé, coluna reta, barra apoiada atrás dos ombros (abaixo do pescoço); afaste bem os pés com o pé guia apontado para o lado.\nAbaixe em direção ao pé girado flexionando joelho e quadril da perna guia, com a outra perna levemente flexionada, inspirando.\nVolte estendendo quadril e joelho da perna guia, expirando.\nComplete as repetições recomendadas e repita com a perna oposta.',
  'Barbell Squat':
    'Use um rack de agachamento por segurança; posicione a barra logo abaixo da altura dos ombros, carregue-a e apoie-a na parte de trás dos ombros (abaixo do pescoço).\nSegure a barra com os dois braços e retire-a do rack empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack com base média, pés na largura dos ombros e pontas levemente para fora; cabeça erguida, coluna reta (pode usar outra base de pés se preferir).\nAbaixe flexionando joelhos e quadris, coluna reta e cabeça erguida, até ângulo coxa-panturrilha pouco menor que 90°, inspirando; os joelhos não devem passar da ponta dos pés.\nSuba empurrando o chão com os calcanhares e estendendo as pernas até a posição inicial, expirando.\nRepita pelo número de repetições recomendado.',
  'Barbell Squat To A Bench':
    'Use um rack de agachamento por segurança; coloque um banco reto ou caixa atrás de você para guiar a profundidade e o quadril para trás.\nPosicione a barra no rack na sua altura, carregue-a e apoie-a na parte de trás dos ombros (abaixo do pescoço).\nSegure a barra com os dois braços e retire-a do rack empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack com base média, pés na largura dos ombros e pontas para fora; cabeça erguida (olhar para baixo desequilibra) e coluna reta.\nAbaixe flexionando os joelhos e levando o quadril para trás, coluna reta e cabeça erguida, até tocar levemente o banco, inspirando; os joelhos não devem passar da ponta dos pés.\nSuba empurrando o chão com os calcanhares e estendendo pernas e quadris até a posição inicial, expirando.\nRepita pelo número de repetições recomendado.',
  'Barbell Step Ups':
    'Em pé, coluna reta, barra apoiada atrás dos ombros (abaixo do pescoço), diante de uma plataforma elevada.\nColoque o pé direito na plataforma e suba estendendo quadril e joelho, apoiando-se no calcanhar; leve também o pé esquerdo, expirando.\nDesça com a perna esquerda flexionando quadril e joelho da direita, inspirando, e coloque o pé direito ao lado do esquerdo.\nComplete as repetições com a perna direita e repita com a esquerda.',
  'Barbell Walking Lunge':
    'Em pé, pés na largura dos ombros, barra apoiada na parte superior das costas.\nDê um passo à frente flexionando os joelhos até o joelho de trás quase tocar o chão; mantenha a postura ereta e o joelho da frente sobre o pé da frente.\nEmpurre com o calcanhar do pé da frente e estenda os dois joelhos para subir.\nDê um passo à frente com o pé de trás e repita o avanço com a perna oposta.',
  'Battling Ropes':
    'Use uma corda pesada ancorada pelo centro a 5-6 m de distância; de frente para ela, segure uma ponta em cada mão, braços estendidos ao lado do corpo.\nEleve rapidamente um braço até a altura do ombro, o mais rápido possível.\nEnquanto deixa esse braço voltar à posição inicial, eleve o do lado oposto.\nAlterne os braços esquerdo e direito, chicoteando as cordas para cima e para baixo o mais rápido possível.',
  'Bear Crawl Sled Drags':
    'Com um arnês ou cinto de peso, prenda a corrente atrás para ficar de costas para o trenó; agache-se com as mãos no chão, costas retas e joelhos flexionados.\nImpulsione-se com as pernas alternando esquerda e direita, usando as mãos para o equilíbrio, e avance mantendo as costas retas.',
  'Behind Head Chest Stretch':
    'Sente-se ereto no chão com seu parceiro atrás de você.\nColoque as mãos atrás da cabeça e leve os cotovelos para trás ao máximo; seu parceiro segura seus cotovelos.\nPuxe suavemente os cotovelos para a frente (mãos atrás da cabeça) por 10 segundos ou mais, enquanto seu parceiro impede que se movam.\nRelaxe e peça ao parceiro que puxe suavemente os cotovelos para trás até onde for confortável; avise-o para evitar alongamento excessivo ou lesão.',
  'Bench Dips':
    'Posicione um banco atrás de você, perpendicular ao corpo; segure a borda com as mãos estendidas na largura dos ombros e pernas estendidas à frente.\nAbaixe lentamente inspirando, flexionando os cotovelos até um ângulo pouco menor que 90°; mantenha os cotovelos próximos ao corpo e os antebraços para baixo.\nUse os tríceps para empurrar o tronco de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Bench Jump':
    'Coloque uma caixa ou banco a 30-60 cm à sua frente; fique em pé com os pés na largura dos ombros.\nFaça um agachamento curto como preparação para o salto; balance os braços para trás.\nReaja estendendo quadris, joelhos e tornozelos para saltar o mais alto possível, balançando os braços para frente e para cima.\nSalte sobre o banco, aterrissando com os joelhos flexionados e absorvendo o impacto com as pernas.\nVire-se para o lado oposto e depois salte de volta sobre o banco.',
  'Bench Press - Powerlifting':
    'Deite-se com a cabeça além da barra, pés embaixo de você e costas arqueadas; retraia os ombros juntando as escápulas e crave o trapézio no banco com os pés.\nSegure a barra cobrindo a marcação em anel e retire-a do rack sem protrair os ombros, apertando-a como se fosse parti-la ao meio.\nAbaixe a barra até a parte inferior do peito ou superior do abdômen, mantendo barra, punho e cotovelo alinhados.\nPause ao tocar o tronco e empurre a barra para cima com a maior força possível, cotovelos junto ao corpo até a extensão completa.',
  'Bench Press - With Bands':
    'Usando um banco reto, prenda uma faixa elástica embaixo da perna do banco mais próxima da sua cabeça.\nSegure a faixa pelas duas alças e deite-se no banco.\nEstenda os braços segurando as alças à sua frente, na largura dos ombros.\nGire os punhos para a frente com as palmas voltadas para longe de você; esta é sua posição inicial.\nAbaixe as alças lentamente até o cotovelo formar 90°, com controle total.\nSuba as alças com os peitorais expirando, trave os braços em cima, aperte o peito por 1 segundo e desça lentamente (o dobro do tempo da subida).\nRepita pelo número de repetições prescrito no seu programa de treino.',
  'Bench Press with Chains':
    'Ajuste a corrente guia no comprimento desejado e coloque as correntes nas extremidades da barra.\nDeite-se com a cabeça além da barra, pés embaixo de você e costas arqueadas; retraia os ombros juntando as escápulas, crave o trapézio com os pés e segure a barra cobrindo a marcação em anel.\nRetire a barra do rack sem protrair os ombros, apertando-a como se fosse parti-la ao meio, e abaixe até a parte inferior do peito ou superior do abdômen, com barra, punho e cotovelo alinhados.\nPause ao tocar o tronco e empurre a barra para cima com a maior força possível, cotovelos junto ao corpo até a extensão completa.',
  'Bench Sprint':
    'Fique em pé no chão com um pé apoiado em um banco ou caixa, com o calcanhar próximo à borda.\nImpulsione-se com o pé que está em cima do banco, estendendo o quadril e o joelho.\nAterrisse com o pé oposto em cima da caixa, retornando o outro pé à posição inicial.\nContinue alternando um pé com o outro até completar a série.',
  'Bent Over Barbell Row':
    'Com a barra em pegada pronada, flexione levemente os joelhos e incline o tronco a partir da cintura com costas retas, quase paralelo ao chão e cabeça erguida; a barra fica pendurada à sua frente com os braços perpendiculares ao chão.\nSem mover o tronco, expire e puxe a barra em direção ao corpo com os cotovelos junto ao corpo; aperte as costas no topo e faça uma breve pausa.\nDepois inspire e abaixe lentamente a barra de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Bent Over Dumbbell Rear Delt Raise With Head On Bench':
    'Fique em pé, com a coluna reta, segurando um halter em cada mão, com um banco inclinado à sua frente.\nCom as costas retas, incline-se até a testa tocar o banco; deixe os braços pendurados perpendiculares ao chão, palmas uma para a outra, tronco paralelo ao chão.\nSem mover o tronco e com os braços retos (leve flexão nos cotovelos), levante os halteres para os lados até ficarem paralelos ao chão, expirando; não balance o tronco nem leve os braços para trás.\nApós uma contração de um segundo no topo, abaixe lentamente os halteres de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Bent Over Low-Pulley Side Lateral':
    'Selecione uma carga e segure o pegador da polia baixa com a mão direita.\nIncline-se a partir da cintura até quase paralelo ao chão, pernas levemente flexionadas, mão esquerda apoiada na coxa esquerda; o braço direito pendura com leve flexão no cotovelo.\nEleve o braço direito para o lado (cotovelo levemente flexionado) até paralelo ao chão e alinhado com a orelha direita, expirando.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado e depois repita o movimento com o outro braço.',
  'Bent Over One-Arm Long Bar Row':
    'Coloque peso em uma extremidade de uma barra olímpica e fixe a outra em um canto de paredes ou sob um objeto pesado para que não deslize.\nIncline-se para a frente até que o tronco fique o mais paralelo possível ao chão e mantenha os joelhos levemente flexionados.\nSegure a barra com um braço logo atrás das anilhas e apoie a outra mão no joelho.\nPuxe a barra para cima com o cotovelo junto ao corpo até as anilhas tocarem a parte inferior do peito, apertando as costas e segurando 1 segundo no topo, expirando; não balance o tronco, só o braço se move.\nAbaixe lentamente a barra sentindo um bom alongamento nos dorsais, sem deixar as anilhas tocarem o chão; use anilhas pequenas (25 lb) para maior amplitude.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Bent Over Two-Arm Long Bar Row':
    'Coloque peso em uma extremidade de uma barra olímpica e fixe a outra em um canto de paredes ou sob um objeto pesado para que não deslize.\nIncline-se para a frente até que o tronco fique o mais paralelo possível ao chão e mantenha os joelhos levemente flexionados.\nSegure a barra com os dois braços logo atrás das anilhas e apoie a outra mão no joelho.\nPuxe a barra para cima com os cotovelos junto ao corpo até as anilhas tocarem a parte inferior do peito, apertando as costas e segurando 1 segundo no topo, expirando; use um estribo ou pegada dupla encaixado sob a barra.\nAbaixe lentamente a barra sentindo um bom alongamento nos dorsais, sem deixar as anilhas tocarem o chão; use anilhas pequenas (25 lb) para maior amplitude.\nRepita pelo número de repetições recomendado.',
  'Bent Over Two-Dumbbell Row':
    'Com um halter em cada mão (palmas voltadas para o tronco), flexione levemente os joelhos e incline o tronco a partir da cintura, costas retas quase paralelas ao chão e cabeça erguida; os pesos ficam pendurados à frente com os braços perpendiculares ao chão.\nSem mover o tronco, levante os halteres para as laterais do corpo expirando, cotovelos junto ao corpo (o antebraço só sustenta o peso); aperte as costas no topo e segure 1 segundo.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Bent Over Two-Dumbbell Row With Palms In':
    'Com um halter em cada mão (palmas uma para a outra), flexione levemente os joelhos e incline o tronco a partir da cintura, costas retas quase paralelas ao chão e cabeça erguida; os pesos ficam pendurados à frente com os braços perpendiculares ao chão.\nSem mover o tronco, levante os halteres para as laterais do corpo expirando, juntando as escápulas; aperte as costas no topo e segure 1 segundo.\nAbaixe lentamente o peso de volta à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Bent Press':
    'Leve o kettlebell ao ombro com um clean, estendendo pernas e quadris enquanto gira o punho.\nIncline-se para o lado oposto ao kettlebell até tocar o chão com a mão livre, sem tirar os olhos dele, e empurre o peso na vertical estendendo o cotovelo, braço perpendicular ao chão.\nVolte à posição ereta com o kettlebell acima da cabeça, leve-o de volta ao ombro e repita pelo número de repetições desejado.',
  'Bent-Arm Barbell Pullover':
    'Deite-se em um banco reto com uma barra, usando uma pegada na largura dos ombros.\nSegure a barra reta sobre o peito com os braços flexionados. Esta será sua posição inicial.\nCom os braços flexionados, abaixe o peso lentamente em arco atrás da cabeça inspirando, até sentir um alongamento no peito.\nTraga a barra de volta à posição inicial pelo mesmo arco, expirando.\nMantenha 1 segundo na posição inicial e repita pelo número de repetições prescrito.',
  'Bent-Arm Dumbbell Pullover':
    'Coloque um halter em pé sobre um banco reto.\nCom o halter bem posicionado na extremidade do banco, deite-se perpendicular a ele com apenas os ombros apoiados, quadris fora do banco, pernas flexionadas com pés firmes no chão e cabeça também fora do banco.\nSegure o halter com as duas mãos sobre o peito, braços flexionados, palmas pressionando a parte inferior de um dos lados; confira que esteja bem preso para não se desmontar no seu rosto.\nCom os braços travados em flexão, abaixe o peso lentamente em arco atrás da cabeça inspirando, até sentir um alongamento no peito.\nTraga o halter de volta à posição inicial pelo mesmo arco, expirando.\nMantenha 1 segundo na posição inicial e repita pelo número de repetições prescrito.',
  'Bent-Knee Hip Raise':
    'Deite-se de costas no chão com os braços ao lado do corpo.\nFlexione os joelhos a cerca de 75° e levante os pés do chão cerca de 2 polegadas.\nCom os abdominais inferiores, traga os joelhos em direção a você mantendo o ângulo de 75°, até elevar o quadril girando a pelve para trás, expirando (os joelhos terminam sobre o peito).\nAperte os abdominais no topo por 1 segundo e volte lentamente à posição inicial inspirando, com movimento controlado.\nRepita pelo número de repetições recomendado.',
  Bicycling:
    'Para começar, sente-se na bicicleta e ajuste o selim à sua altura.',
  'Bicycling, Stationary':
    'Para começar, sente-se na bicicleta e ajuste o selim à sua altura.\nSelecione a opção no menu (talvez precise pedalar para ligá-la); use o modo manual ou um programa, informe idade e peso para estimar calorias, ajuste a resistência durante o treino e use as manoplas para monitorar a frequência cardíaca.',
  'Board Press':
    'Deite-se com a cabeça além da barra; use de uma a cinco tábuas 2x6 parafusadas juntas, seguradas por um parceiro, por faixas elásticas, ou colocadas sob a camiseta.\nColoque os pés embaixo de você, arqueie as costas, retraia os ombros juntando as escápulas e crave o trapézio no banco com os pés; mantenha essa posição firme.\nUse pegada padrão de supino ou na largura dos ombros para focar tríceps; retire a barra do rack sem protrair os ombros, mantendo barra, punho e cotovelo alinhados, apertando-a como se fosse parti-la ao meio.\nAbaixe a barra até as tábuas e empurre-a para cima com a maior força possível, cotovelos junto ao corpo até a extensão completa.',
  'Body Tricep Press':
    'Posicione uma barra em um rack na altura do peito.\nSegure a barra na largura dos ombros, pés juntos e braços estendidos, apoiado na barra: posição inicial.\nFlexione os cotovelos e abaixe o corpo em direção à barra.\nPause embaixo e estenda os cotovelos para subir novamente.\nProgrida adicionando correntes sobre os ombros, além do peso corporal.',
  'Body-Up':
    'Faça prancha sobre antebraços e pontas dos pés, na largura dos ombros, tronco reto: posição inicial.\nPressione as palmas contra o chão e estenda os cotovelos para elevar o corpo, com o tronco rígido.\nAbaixe lentamente os antebraços ao chão flexionando os cotovelos.\nRepita.',
  'Bodyweight Flyes':
    'Coloque duas barras W igualmente carregadas no chão, lado a lado, prontas para rolar.\nAssuma posição de flexão sobre as barras, apoio nos pés e nas mãos, braços estendidos, corpo reto.\nColoque as mãos sobre as barras: posição inicial.\nAfaste lentamente as mãos da linha média do corpo, rolando as barras para os lados, e inspire.\nAfaste as barras o máximo possível, depois puxe-as de volta ao centro enquanto expira.',
  'Bodyweight Mid Row':
    'Pendure-se na barra, pegada média-larga e palmas para fora; passe as pernas para um lado: posição inicial.\nFlexione os cotovelos e retraia as escápulas para subir o corpo até as pernas tocarem a barra.\nApós uma breve pausa, volte à posição inicial.',
  'Bodyweight Squat':
    'Fique em pé, pés na largura dos ombros, mãos atrás da cabeça (opcional): posição inicial.\nFlexione os joelhos e os quadris, levando o quadril para trás.\nDesça até a profundidade máxima, cabeça e peito erguidos, joelhos para fora, e suba rápido.',
  'Bodyweight Walking Lunge':
    'Comece em pé, com os pés na largura dos ombros e as mãos nos quadris.\nDê um passo à frente, desça até quase tocar o chão com o joelho de trás; joelho da frente sobre o pé.\nEmpurre com o calcanhar do pé da frente e estenda os dois joelhos para se levantar.\nDê um passo à frente com o pé de trás, repetindo o avanço com a perna oposta.',
  'Bosu Ball Cable Crunch With Side Bends':
    'Conecte um pegador padrão em cada braço de uma máquina de polia e posicione-os na posição mais baixa.\nPegue uma bola Bosu e posicione-a à frente e no centro da máquina de polia.\nDeite-se sobre a Bosu com a lombar arqueada ao redor da bola, glúteos perto do chão sem tocá-lo.\nCom as duas mãos, estenda os braços para trás e segure o pegador de cada cabo.\nPés em base ampla, estenda os braços retos entre os joelhos, mãos na altura dos joelhos.\nBraços retos e alinhados com o cabo, eleve o tronco em crunch sem flexionar os braços.\nCom os braços rígidos, desça lentamente à posição inicial, costas arqueadas e abdômen alongado.\nRepita a mesma série de movimentos até a falha.\nAo chegar à falha, contraia o abdômen e eleve o tronco até a prancha, costas fora da Bosu.\nAbaixe os braços retos e faça flexões laterais alternadas tentando tocar os calcanhares, para os oblíquos.',
  'Bottoms Up':
    'Deite-se de costas, pernas retas e braços ao lado do corpo: posição inicial.\nLeve os joelhos ao peito, estenda as pernas para cima e eleve a pelve tirando os glúteos do chão.\nApós uma breve pausa, volte à posição inicial.',
  'Bottoms-Up Clean From The Hang Position':
    'Inicie o exercício em pé, ereto, com um kettlebell em uma das mãos.\nBalance o kettlebell com força para trás, inverta o movimento, aperte a alça e eleve-o até o ombro.',
  'Box Jump (Multiple Response)':
    'Fique de frente para a caixa, a um braço de distância, braços abaixados e pernas levemente flexionadas.\nImpulsione-se com os braços e salte para cima e à frente, aterrissando com os dois pés na caixa.\nImediatamente desça ou salte de volta ao ponto de partida original; depois repita a sequência.',
  'Box Skip':
    'Você precisará de várias caixas alinhadas a cerca de 2,5 metros (8 pés) de distância umas das outras.\nComece de frente para a primeira caixa com uma perna um pouco atrás da outra.\nImpulsione-se com a perna de trás, tentando ganhar o máximo de altura possível com o quadril.\nAo aterrissar, impulsione a outra perna para cima e à frente, salte e aterrisse com essa mesma perna.\nDepois, avance para a próxima caixa e repita.',
  'Box Squat':
    'Use um power rack com uma caixa atrás, ajustada a uma altura de agachamento paralelo.\nApoie a barra na nuca, escápulas juntas e cotovelos à frente; saia do rack com arco lombar e recue. Pés afastados enfatiza costas e glúteos; juntos, quadríceps. Cabeça à frente.\nCom costas, ombros e core firmes, empurre joelhos e bumbum para fora e leve o quadril atrás até sentar na caixa, canelas perpendiculares ao chão; pause sem quicar.\nCom o peso nos calcanhares e joelhos para fora, impulsione-se saindo da caixa liderando com a cabeça, tensão da cabeça aos pés.',
  'Box Squat with Bands':
    'Fixe as faixas nas extremidades da barra (suportes, rack ou halteres pesados o bastante), ajuste a tensão pela base ou pelo comprimento da faixa; caixa atrás na altura de agachamento paralelo.\nApoie a barra na nuca, escápulas juntas e cotovelos à frente; saia do rack com arco lombar e recue. Pés afastados enfatiza costas e glúteos; juntos, quadríceps. Cabeça à frente.\nCom costas, ombros e core firmes, empurre joelhos e bumbum para fora e leve o quadril atrás até sentar na caixa, canelas perpendiculares ao chão; pause sem quicar.\nCom o peso nos calcanhares e joelhos para fora, impulsione-se saindo da caixa liderando com a cabeça; cuidado ao devolver a barra ao rack.',
  'Box Squat with Chains':
    'Use um power rack com uma caixa atrás, na altura de agachamento paralelo (ajustável).\nPasse a corrente guia sobre as extremidades da barra, conecte a corrente pesada com mosquetão e ajuste o comprimento para que alguns elos toquem o chão no topo.\nApoie a barra na nuca, escápulas juntas e cotovelos à frente; saia do rack com arco lombar e recue. Pés afastados enfatiza costas e glúteos; juntos, quadríceps. Cabeça à frente.\nCom costas, ombros e core firmes, empurre joelhos e bumbum para fora e leve o quadril atrás até sentar na caixa, canelas perpendiculares ao chão; pause sem quicar.\nCom o peso nos calcanhares e joelhos para fora, impulsione-se saindo da caixa liderando com a cabeça, tensão da cabeça aos pés.',
  'Brachialis-SMR':
    'Deite-se de lado com a parte externa do bíceps pressionada contra o rolo de espuma, braço alinhado ao corpo.\nEleve o quadril do chão apoiando o peso no braço e nos pés; mantenha 10 a 30 segundos e troque de lado.',
  'Bradford/Rocky Presses':
    'Sente-se com a barra na altura dos ombros, pegada pronada mais larga que os ombros, 90° entre antebraço e braço ao descer: posição inicial.\nLevante a barra acima da cabeça estendendo os braços.\nAgora abaixe a barra lentamente até atrás da cabeça enquanto inspira.\nLevante a barra de volta à posição inicial enquanto expira.\nAbaixe a barra lentamente até a posição inicial enquanto inspira; é uma repetição.\nAlterne dessa maneira até completar o número de repetições recomendado.',
  'Butt Lift (Bridge)':
    'Deite-se de costas, mãos ao lado do corpo, joelhos flexionados, pés na largura dos ombros: posição inicial.\nEmpurre com os calcanhares e eleve o quadril mantendo as costas retas; expire e segure um segundo no topo.\nVolte lentamente à posição inicial enquanto inspira.',
  'Butt-Ups':
    'Adote posição de prancha sobre os antebraços, cotovelos no chão flexionados a 90 graus.\nArqueie levemente as costas para cima em vez de mantê-las completamente retas.\nEleve os glúteos ao teto contraindo o abdômen para diminuir a distância entre costelas e quadril (ponte alta); expire.\nAbaixe lentamente à posição inicial enquanto inspira, sem deixar as costas cederem.\nRepita pelo número de repetições recomendado.',
  Butterfly:
    'Sente-se na máquina com as costas retas encostadas no apoio.\nSegure as manoplas com a parte superior dos braços paralela ao chão, ajustando a máquina: posição inicial.\nJunte as manoplas apertando o peito no centro, expire e segure a contração por um segundo.\nVolte lentamente à posição inicial enquanto inspira, até alongar totalmente o peito.\nRepita pelo número de repetições recomendado.',
  'Cable Chest Press':
    'Ajuste a carga, sente-se e segure as manoplas: braços a 45° do corpo, cotovelos a 90°, cabeça e peito erguidos: posição inicial.\nEstenda os cotovelos empurrando as manoplas juntas à frente, com as escápulas retraídas.\nPause na extensão completa e volte à posição inicial mantendo a tensão nos cabos.\nVocê também pode fazê-lo com as costas afastadas do apoio, em inclinação, declinação ou alternando as mãos.',
  'Cable Crossover':
    'Coloque as polias na posição alta, escolha a resistência e segure uma manopla em cada mão.\nDê um passo à frente da linha entre as polias, junte os braços à frente, tronco levemente inclinado: posição inicial.\nCom os cotovelos levemente flexionados, abra os braços em arco amplo até alongar o peitoral, inspirando; mova só o ombro, tronco parado.\nRetorne os braços à posição inicial enquanto expira, usando o mesmo arco de movimento.\nSegure por um segundo na posição inicial e repita pelo número de repetições prescrito.',
  'Cable Crunch':
    'Ajoelhe-se debaixo de uma polia alta com uma corda.\nSegure a corda e abaixe-a até que suas mãos fiquem ao lado do rosto.\nFlexione levemente os quadris deixando o peso hiperestender a lombar: posição inicial.\nCom os quadris parados, flexione a cintura contraindo o abdômen para levar os cotovelos às coxas; expire e segure um segundo.\nRetorne lentamente à posição inicial inspirando, com tensão constante no abdômen; não use carga tão pesada que a lombar trabalhe mais.\nRepita pelo número de repetições recomendado.',
  'Cable Deadlifts':
    'Mova os cabos para a parte inferior das torres, escolha a carga e fique entre os suportes verticais.\nPara começar, agache flexionando quadris e joelhos até alcançar as manoplas.\nSegure as manoplas e suba empurrando pelos calcanhares, estendendo quadris e joelhos, mãos penduradas, cabeça e peito erguidos.\nDepois de chegar à posição em pé completa, retorne à posição inicial e repita.',
  'Cable Hammer Curls - Rope Attachment':
    'Prenda uma corda em uma polia baixa e fique de frente para a máquina, a cerca de 30 cm de distância.\nSegure a corda com pegada neutra (palmas para dentro), ereto, com curvatura natural da coluna e tronco parado.\nEncoste os cotovelos ao corpo e mantenha-os parados; só os antebraços se movem: posição inicial.\nCom os bíceps, suba os braços expirando até tocarem os antebraços, cotovelos junto ao corpo e parados.\nAperte os bíceps por 1 segundo e leve a carga lentamente de volta à posição original.\nRepita pelo número de repetições recomendado.',
  'Cable Hip Adduction':
    'Fique de frente para uma polia baixa, uma perna ao lado da polia e a outra afastada.\nPrenda a tornozeleira ao cabo e também ao tornozelo da perna que está ao lado da polia.\nDê um passo para fora com base ampla e segure a barra do sistema de polias.\nApoie-se no pé sem tornozeleira e deixe a perna com tornozeleira ser puxada à polia: posição inicial.\nLeve a perna com tornozeleira à frente da outra, aduzindo o quadril com a parte interna da coxa; expire.\nRetorne lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado e depois faça o mesmo movimento com a perna oposta.',
  'Cable Incline Pushdown':
    'Deite-se em um banco inclinado de costas para uma máquina de polia alta com uma barra reta.\nSegure a barra com pegada pronada na largura dos ombros, braços estendidos à frente, a 5 cm das coxas: posição inicial.\nCom os braços parados, leve-os para trás em semicírculo até a barra ficar acima da cabeça, inspirando.\nRetorne lentamente à posição inicial usando os dorsais, expirando, e segure a contração.\nRepita pelo número de repetições recomendado.',
  'Cable Incline Triceps Extension':
    'Deite-se em um banco inclinado de costas para uma máquina de polia alta com uma barra reta.\nSegure a barra com pegada pronada fechada (menor que a largura dos ombros), cotovelos junto ao corpo, braços a cerca de 25° do chão.\nCom os braços parados, estenda-os contraindo o tríceps; expire e segure por um segundo.\nRetorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Cable Internal Rotation':
    'Sente-se de lado ao lado de uma polia baixa (pernas à frente ou cruzadas) e segure a manopla com o braço mais próximo do cabo.\nPosicione o cotovelo junto ao corpo, flexionado a 90° e apontando para a polia: posição inicial.\nPuxe a manopla rotacionando internamente o ombro até cruzar o antebraço sobre o abdômen, mantendo-o perpendicular ao tronco.\nRetorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado e depois repita o movimento com o outro braço.',
  'Cable Iron Cross':
    'Mova as polias para a posição alta, escolha a resistência e segure uma manopla em cada mão.\nFique entre as duas polias com os braços estendidos em "T", cabeça e peito erguidos: posição inicial.\nMantendo os cotovelos estendidos, puxe os braços retos para os lados.\nRetorne os braços à posição inicial após uma pausa na contração máxima.\nContinue o movimento pelo número de repetições prescrito.',
  'Cable Judo Flip':
    'Conecte uma corda a uma torre na polia mais baixa; fique de lado com base ampla e segure a corda com as duas mãos.\nGire o corpo para longe da polia levando a corda sobre o ombro, como uma projeção de judô.\nTransfira o peso entre os pés enquanto gira e faz um abdominal para a frente, puxando o cabo para baixo.\nRetorne à posição inicial e repita até a falha.\nDepois, reposicione-se e repita a mesma série de movimentos do lado oposto.',
  'Cable Lying Triceps Extension':
    'Deite-se em um banco reto e segure a barra na polia baixa com pegada pronada fechada; peça ajuda.\nEstenda os braços e posicione a barra sobre o tronco, formando 90° entre braços e tronco (posição inicial).\nFlexione os cotovelos e abaixe a barra, braços parados, até tocar de leve a testa; inspire.\nContraia o tríceps e levante a barra à posição inicial enquanto expira.\nSegure a contração por 1 segundo e repita as repetições recomendadas.',
  'Cable One Arm Tricep Extension':
    'Segure com a mão direita a manopla da polia alta com pegada supinada, em pé de frente para o peso.\nPuxe a manopla com o cotovelo fixo ao corpo até formar menos de 90° entre braço e antebraço (posição inicial).\nContraia o tríceps e estenda o braço para baixo até ficar reto, expirando; mova só o antebraço.\nAperte o tríceps e segure a contração por 1 segundo.\nRetorne lentamente a manopla à posição inicial.\nRepita as repetições recomendadas e troque de braço.',
  'Cable Preacher Curl':
    'Posicione um banco Scott a cerca de 60 cm à frente de uma máquina de polia.\nPrenda uma barra reta à polia baixa.\nSente-se no banco Scott com os braços apoiados no estofado; peça que lhe entreguem a barra.\nSegure a barra e estenda os braços por completo sobre o estofado (posição inicial).\nPuxe o peso em direção aos ombros expirando, contraia forte o bíceps e segure 1 segundo no topo.\nAgora abaixe lentamente o peso até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Cable Rear Delt Fly':
    'Ajuste as polias acima da cabeça e selecione a carga.\nCruze os cabos à sua frente: segure a polia esquerda com a mão direita e vice-versa (posição inicial).\nLeve os braços para trás e para fora, mantendo-os retos.\nFaça uma pausa no final do movimento e retorne as manoplas à posição inicial.',
  'Cable Reverse Crunch':
    'Conecte uma tornozeleira a um cabo de polia baixa e posicione um colchonete no chão à sua frente.\nSente-se com os pés voltados para a polia e prenda o cabo aos tornozelos.\nDeite-se, flexione os joelhos a 90° e alinhe as pernas com o cabo ajustando a polia.\nCom as mãos atrás da cabeça, leve os joelhos em direção ao tronco e eleve o quadril do chão.\nFaça uma pausa e abaixe o quadril com controle até 90°, mantendo tensão nos abdominais.\nRepita o mesmo movimento até a falha.',
  'Cable Rope Overhead Triceps Extension':
    'Prenda uma corda à polia inferior da máquina de polias.\nEstenda os braços acima da cabeça com pegada neutra, cotovelos próximos da cabeça e perpendiculares ao chão.\nAbaixe a corda atrás da cabeça com os braços parados, inspirando, até alongar bem o tríceps.\nRetorne à posição inicial contraindo o tríceps enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Cable Rope Rear-Delt Rows':
    'Sente-se na estação de remada com polia baixa, como na remada sentada para as costas.\nPrenda uma corda e segure com pegada pronada, braços estendidos e paralelos ao chão, cotovelos para fora.\nMantenha a lombar ereta, deslize o quadril para trás com joelhos levemente flexionados (posição inicial).\nPuxe a corda ao peito, cotovelos elevados e para fora, expirando, até passar as costas; braços na horizontal.\nRetorne à posição inicial com braços estendidos e ombros alongados à frente, inspirando.\nRepita pelo número de repetições recomendado.',
  'Cable Russian Twists':
    'Conecte uma manopla padrão e posicione o cabo em uma altura média da polia.\nDeite-se em uma bola perpendicular ao cabo, a um braço da polia, com tensão no cabo.\nSegure a manopla com as duas mãos, estenda os braços acima do peito e alinhe-os com a polia.\nCom quadril elevado e abdômen contraído, gire o tronco um quarto de volta da polia, corpo reto.\nFaça uma pausa e retorne com controle à posição inicial, mantendo tensão lateral no cabo.\nRepita o mesmo movimento até a falha.\nDepois, reposicione-se e repita a mesma série do lado oposto.',
  'Cable Seated Crunch':
    'Sente-se em um banco reto de costas para uma polia alta.\nSegure a corda com as duas mãos sobre os ombros, deixando a carga hiperestender um pouco a lombar.\nCom o quadril parado, flexione a cintura levando os cotovelos em direção ao quadril, expirando.\nAo inspirar, retorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Cable Seated Lateral Raise':
    'Fique entre duas polias baixas opostas com um banco reto perpendicular atrás de você; selecione a carga.\nAgora sente-se na beira do banco reto atrás de você, com os pés à frente dos joelhos.\nIncline-se para a frente mantendo as costas retas e apoie o tronco sobre as coxas.\nSegure as manoplas cruzadas, cabos sob os joelhos, braços estendidos com leve flexão nos cotovelos (início).\nEleve os braços para os lados até a altura dos ombros, expirando, e segure por 1 segundo.\nAbaixe lentamente os braços até a posição inicial enquanto inspira.\nRepita as repetições recomendadas, braços perpendiculares ao tronco e cotovelos fixos entre 10-30°.',
  'Cable Shoulder Press':
    'Mova os cabos para a parte inferior das torres e selecione uma carga adequada.\nFique entre os suportes, segure os cabos na altura dos ombros com as palmas para a frente (início).\nCom a cabeça e o peito erguidos, estenda os cotovelos empurrando as manoplas acima da cabeça.\nApós uma pausa no topo, retorne à posição inicial e repita.',
  'Cable Shrugs':
    'Segure a barra na polia baixa com pegada pronada, na largura dos ombros ou um pouco mais aberta.\nFique ereto perto da polia, braços estendidos à frente segurando a barra (início).\nEleve os ombros o mais alto possível, expirando, braços estendidos sem ajuda do bíceps; segure 1 seg.\nAbaixe a barra de volta à posição original.\nRepita pelo número de repetições recomendado.',
  'Cable Wrist Curl':
    'Comece posicionando um banco reto à frente de uma polia baixa com uma barra reta.\nSegure a barra com pegada supinada, antebraços sobre as coxas e punhos pendendo atrás dos joelhos.\nFlexione os punhos para cima enquanto expira. Segure a contração por um segundo.\nAbaixe lentamente os punhos de volta à posição inicial enquanto inspira.\nMantenha os antebraços parados; apenas o punho deve se mover.\nRepita pelo número de repetições recomendado.',
  'Calf Press':
    'Ajuste o assento com as pernas levemente flexionadas e a parte da frente dos pés firme na plataforma.\nSelecione uma carga adequada e segure as manoplas (posição inicial).\nEstenda os joelhos levantando apenas de leve a carga, tornozelo flexionado e dedos para cima ao máximo.\nApós uma breve pausa, inverta o movimento e repita.',
  'Calf Press On The Leg Press Machine':
    'Sente-se no leg press com os pés na plataforma, base média na largura dos ombros.\nEstenda as pernas a 90° sem travar os joelhos, apoiando só a ponta dos pés, calcanhares para fora.\nEleve os calcanhares expirando, estenda os tornozelos ao máximo, joelhos fixos sem flexão; segure 1 segundo.\nAbaixe os calcanhares com controle, inspirando, flexionando os tornozelos até alongar as panturrilhas.\nRepita pelo número de repetições recomendado.',
  'Calf Raise On A Dumbbell':
    'Segure-se em um apoio firme e fique sobre o cabo de um halter com anilhas redondas para que ele role.\nRole o pé um pouco para a frente para alongar bem a panturrilha (posição inicial).\nEleve a panturrilha rolando o pé sobre o cabo, expirando; contraia forte e segure 1 segundo no topo.\nInspire enquanto desce, rolando o halter um pouco para a frente para um melhor alongamento.\nRepita pelo número de repetições recomendado.',
  'Calf Raises - With Bands':
    'Pise em uma faixa elástica com a ponta dos pés, com o mesmo comprimento de faixa dos dois lados.\nEleve os braços junto à cabeça como em um desenvolvimento, palmas à frente, cotovelos para os lados.\nCom as mãos junto aos ombros, suba na ponta dos pés expirando e contraia forte as panturrilhas.\nApós uma contração de um segundo, desça lentamente até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Calf Stretch Elbows Against Wall':
    'Fique em pé de frente para uma parede, a cerca de meio metro de distância.\nIncline-se contra a parede, apoiando o peso nos antebraços.\nMantenha os calcanhares no chão 10-20 segundos; afaste-se ou aproxime-se para variar a dificuldade.',
  'Calf Stretch Hands Against Wall':
    'Fique de pé a um metro ou mais de uma parede, com um pé à frente (base escalonada).\nIncline-se e apoie as mãos na parede, mantendo calcanhar, quadril e cabeça em linha reta.\nMantenha o calcanhar no chão por 10-20 segundos e depois troque de lado.',
  'Calf-Machine Shoulder Shrug':
    'Posicione-se na máquina com as almofadas sobre os ombros, tronco reto e braços relaxados (início).\nEleve os ombros em direção às orelhas, expirando, e segure a contração por 1 segundo completo.\nRetorne lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Calves-SMR':
    'Sente-se com um rolo de espuma sob a panturrilha; cruze ou apoie a outra perna para dar suporte.\nEleve o quadril, role a panturrilha do joelho ao tornozelo, pausando 10-30 seg, e repita com a outra perna.',
  'Car Deadlift':
    'Use o aparelho com manoplas de pegada neutra ou barra reta, carregado com veículo, pneus ou barris.\nPosicione-se entre as manoplas, pés na largura do quadril; flexione quadril e joelhos e inspire fundo.\nCom peito erguido e costas arqueadas, empurre pelos calcanhares e junte as escápulas ao avançar o quadril.\nAbaixe a carga flexionando o quadril e guiando-a até o chão.',
  'Car Drivers':
    'Em pé, segure um disco com as mãos em 3 e 9 horas, palmas uma para a outra, braços estendidos à frente.\nGire o disco o máximo possível para um lado, como se girasse um volante.\nInverta o movimento, girando-o completamente para o lado oposto.\nRepita pelo número de repetições recomendado.',
  'Carioca Quick Step':
    'Comece com os pés afastados e o braço esquerdo elevado, em posição atlética e relaxada.\nCom o pé direito, dê um passo rápido por trás e eleve o joelho.\nLance os braços para cima ao elevar o joelho direito em linha reta, sem girar os pés, olhando para a frente.',
  'Cat Stretch':
    'Posicione-se no chão de quatro apoios, sobre as mãos e os joelhos.\nContraia a barriga e arredonde a coluna, a lombar, os ombros e o pescoço, deixando a cabeça cair.\nSegure por 15 segundos.',
  'Catch and Overhead Throw':
    'Comece em pé de frente para uma parede ou um parceiro.\nCom as duas mãos, leve a bola atrás da cabeça, alongue-se ao máximo e arremesse com força para a frente.\nComplete o movimento e prepare-se para o rebote; contra a parede, fique mais perto e mire mais alto.',
  'Chain Handle Extension':
    'Use duas manoplas de cabo, correntes e um banco reto; prenda as correntes às manoplas, cotovelos para cima.\nEstenda os cotovelos mantendo fixa a parte superior do braço, com os punhos em pronação.\nFaça uma pausa na extensão completa e inverta o movimento para retornar à posição inicial.',
  'Chain Press':
    'Conecte as correntes às manoplas e deite-se como em um supino com halteres, braços perpendiculares.\nAbaixe as correntes flexionando os cotovelos, deixando parte da corrente apoiada no chão.\nDesça até formar 90° no cotovelo e inverta o movimento estendendo até a extensão completa.',
  'Chair Leg Extended Stretch':
    'Sente-se ereto em uma cadeira e segure o assento pelas laterais.\nLevante uma perna, estendendo o joelho e flexionando o tornozelo.\nMova essa perna lentamente para o lado o máximo que puder, depois de volta ao centro e para baixo.\nRepita com a outra perna.',
  'Chair Lower Back Stretch':
    'Sente-se ereto em uma cadeira.\nIncline-se para um lado com o braço acima da cabeça, segurando a cadeira com a mão livre.\nSegure 10 segundos e repita para o outro lado.',
  'Chair Squat':
    'Ajuste a barra à sua altura, entre debaixo dela e posicione-a sobre a parte de trás dos ombros.\nSegure a barra com as mãos à frente, destrave-a e tire-a do rack estendendo as pernas.\nPés a ~45 cm à frente da barra, na largura dos ombros com os pés levemente para fora; olhar à frente, coluna neutra. Posição inicial.\nFlexione os joelhos e abaixe a barra mantendo as costas retas e a cabeça erguida, até passar de 90 graus de flexão do joelho.\nExpire e suba empurrando o chão com os calcanhares, estendendo os joelhos até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Chair Upper Body Stretch':
    'Sente-se na beira de uma cadeira e segure o encosto.\nEstique os braços com as costas retas e puxe o tronco para a frente até sentir o alongamento. Segure 20-30 segundos.',
  'Chest And Front Of Shoulder Stretch':
    'Fique em pé com as pernas juntas, segurando uma barra leve ou um cabo de vassoura.\nSegure o bastão com pegada um pouco mais aberta que os ombros, palmas para baixo, à frente do corpo.\nLevante o bastão com cuidado para cima e para trás da cabeça.',
  'Chest Push (multiple response)':
    'Ajoelhe-se de frente para uma parede ou um parceiro e segure a bola com as duas mãos contra o peito.\nExploda para a frente com o quadril e empurre a bola com a maior força possível.\nCaia para a frente e apoie-se com as mãos ao completar o passe.\nVolte imediatamente à posição ereta. Repita pelo número de repetições desejado.',
  'Chest Push (single response)':
    'Ajoelhe-se e segure a bola medicinal com as duas mãos contra o peito.\nExploda para a frente com o quadril e empurre a bola o mais longe possível.\nCaia para a frente e apoie-se com as mãos ao completar o passe.',
  'Chest Push from 3 point stance':
    'Agache-se com três apoios, costas retas e uma mão no chão; coloque a bola medicinal à sua frente.\nDê o primeiro passo puxando a bola até o peito e posicionando as duas mãos para o arremesso.\nNo segundo passo, solte a bola para a frente de forma explosiva com a maior força possível.',
  'Chest Push with Run Release':
    'Adote uma postura atlética: joelhos flexionados, quadril para trás, costas retas, bola medicinal perto das pernas. Posição inicial.\nNo primeiro passo, leve a bola medicinal até o peito.\nNo segundo passo, empurre a bola para a frente de forma explosiva e corra em velocidade máxima por 10 jardas após soltá-la.',
  'Chest Stretch on Stability Ball':
    'Fique de quatro apoios ao lado de uma bola de exercício.\nApoie os cotovelos sobre a bola com o braço para o lado. Posição inicial.\nAbaixe o tronco em direção ao chão mantendo o cotovelo sobre a bola. Segure 20-30 segundos e repita com o outro braço.',
  "Child's Pose":
    'Fique de quatro apoios e caminhe com as mãos para a frente.\nAbaixe o bumbum em direção aos calcanhares e deixe os braços deslizarem pelo chão para alongar toda a coluna.\nLeve as mãos para junto dos pés, relaxe e apoie a testa no chão. Evite esta posição se tiver problemas nos joelhos.',
  'Chin To Chest Stretch':
    'Sente-se no chão.\nEntrelace os dedos atrás da cabeça, polegares para baixo e cotovelos à frente; puxe a cabeça em direção ao peito. Segure 20-30 segundos.',
  'Chin-Up':
    'Segure a barra com as palmas voltadas para você e uma pegada mais fechada que a largura dos ombros.\nFique pendurado com os braços estendidos, tronco reto, leve arco lombar e peito para fora: posição inicial. Manter o tronco reto maximiza o trabalho dos bíceps.\nExpire e puxe o tronco até a cabeça chegar à altura da barra, usando os bíceps e mantendo os cotovelos perto do corpo; só os braços se movem.\nAperte os bíceps por um segundo no topo e desça lentamente inspirando até estender totalmente os braços.\nRepita pelo número de repetições prescrito.',
  'Circus Bell':
    'Com o halter gigante entre os pés, segure o cabo grosso com as duas mãos.\nFaça o clean estendendo quadris e joelhos para levar o implemento ao ombro, soltando a mão que sobra.\nMantenha uma cabeça do halter atrás do ombro para não perder o equilíbrio; flexione os joelhos e empurre para cima estendendo-o acima da cabeça, inclinando-se levemente para longe dele.\nGuie o sino de volta ao chão com controle, de preferência sobre um tapete de borracha grosso para proteger o piso.',
  Clean:
    'Com a barra perto das canelas, segure em pronada ou gancho fora das pernas; quadril abaixo, peso nos calcanhares, costas retas, peito erguido, ombros à frente da barra. Posição inicial.\nPrimeira puxada: empurre pelos calcanhares e estenda os joelhos, mantendo o ângulo das costas e os braços retos, até passar dos joelhos.\nSegunda puxada: quando a barra passar do meio da coxa, estenda quadris, joelhos e tornozelos em um salto explosivo para acelerar a barra, sem puxar com os braços, até ficar totalmente estendido e levemente inclinado para trás.\nTerceira puxada: encolha os ombros com força, flexione os braços com cotovelos para cima e para fora, puxe-se para baixo girando os cotovelos sob a barra e receba-a em agachamento frontal sobre os ombros protraídos, tocando de leve a garganta.\nRecupere-se empurrando pelos calcanhares, tronco ereto e cotovelos elevados, até ficar de pé.',
  'Clean Deadlift':
    'Em pé com a barra perto das canelas, pés sob o quadril e voltados para fora; pegada pronada dupla ou em gancho na largura dos ombros. Agache até a barra, coluna em extensão total e costas o mais verticais possível.\nEmpurre o chão pela parte da frente dos calcanhares, mantenha o ângulo das costas constante e abra os joelhos para os lados conforme a barra sobe.\nQuando a barra passar dos joelhos, complete o levantamento levando o quadril até estendê-lo junto com os joelhos.',
  'Clean Pull':
    'Com a barra perto das canelas, segure em pronada ou gancho fora das pernas; quadril abaixo, peso nos calcanhares, costas retas, peito erguido, ombros à frente da barra. Posição inicial.\nPrimeira puxada: empurre pelos calcanhares, estenda os joelhos, mantenha o ângulo das costas, braços retos e cotovelos para fora, até passar dos joelhos.\nSegunda puxada: quando a barra passar do meio da coxa, estenda quadris, joelhos e tornozelos em um salto explosivo sem puxar com os braços, até ficar totalmente estendido e levemente inclinado para trás; faça isso de forma violenta e breve.',
  'Clean Shrug':
    'Pegada pronada dupla ou em gancho na largura dos ombros, barra pendurada na altura do meio da coxa, costas retas e levemente inclinadas para a frente.\nEncolha os ombros em direção às orelhas; embora admita mais carga que um clean, evite sobrecarregar a ponto de deixar o movimento lento.',
  'Clean and Jerk':
    'Com a barra perto das canelas, segure em pronada ou gancho fora das pernas; quadril abaixo, peso nos calcanhares, costas retas, peito erguido, ombros à frente da barra. Posição inicial.\nPrimeira puxada: empurre com os calcanhares e estenda os joelhos, mantendo o ângulo das costas e os braços retos, até passar dos joelhos.\nSegunda puxada: quando a barra passar do meio da coxa, estenda quadris, joelhos e tornozelos em um salto explosivo sem puxar com os braços, até ficar totalmente estendido e levemente inclinado para trás.\nTerceira puxada: encolha os ombros com força, flexione os braços com cotovelos para cima e para fora, puxe-se para baixo girando os cotovelos sob a barra e receba-a em agachamento frontal sobre os ombros protraídos, encostando na garganta.\nRecupere-se empurrando com os calcanhares, tronco ereto e cotovelos para cima, até ficar de pé.\nArremesso (jerk), fase 2: de pé com a barra sobre os ombros, pés sob o quadril, flexione os joelhos sem levar o quadril para trás, desça pouco e inverta a direção com a maior potência possível.\nEmpurre com os calcanhares para gerar máxima velocidade e força, tirando a cabeça do caminho quando a barra sair dos ombros.\nAo sair os pés do chão, reposicione-os rápido para a recepção (um à frente, um atrás) e receba a barra com os braços estendidos acima da cabeça; volte à posição em pé.',
  'Clean and Press':
    'Pés na largura dos ombros, joelhos por dentro dos braços; com as costas retas, flexione joelhos e quadril para segurar a barra com braços estendidos e pegada pronada um pouco mais larga que os ombros, cotovelos para os lados, ombros sobre a barra. Posição inicial.\nPuxe a barra estendendo os joelhos, levando o quadril para a frente e subindo os ombros no mesmo ritmo, mantendo o ângulo das costas constante e a barra próxima ao corpo.\nQuando a barra passar dos joelhos, estenda com força tornozelos, joelhos e quadril como em um salto, guiando a barra com as mãos e encolhendo os ombros para subi-la o mais alto possível, cotovelos para fora.\nNa elevação máxima, tire os pés do chão e comece a se posicionar sob a barra, descendo para uma posição de agachamento.\nGire os cotovelos sob a barra e apoie-a na frente dos ombros, tronco ereto, flexionando quadril e joelhos para absorver o peso.\nLevante-se por completo segurando a barra na posição de clean.\nSem mover os pés, expire e empurre a barra acima da cabeça; depois abaixe-a com controle.',
  'Clean from Blocks':
    'Com a barra sobre caixas na altura desejada, segure em pronada ou gancho fora das pernas; quadril abaixo, peso nos calcanhares, costas retas, peito erguido, ombros à frente da barra. Posição inicial.\nPrimeira puxada: empurre com os calcanhares e estenda os joelhos, mantendo o ângulo das costas e os braços retos com cotovelos para fora.\nAo atingir a extensão completa, encolha os ombros com força, flexione os braços com cotovelos para cima e para fora, puxe-se para baixo girando os cotovelos sob a barra e receba-a em agachamento frontal, encostando na garganta.\nRecupere-se empurrando com os calcanhares, tronco ereto e cotovelos para cima, até ficar de pé; devolva o peso às caixas para a próxima repetição.',
  'Clock Push-Up':
    'Posição de decúbito ventral, apoiado nas mãos e na ponta dos pés.\nBraços estendidos, mãos na largura dos ombros, corpo reto. Posição inicial.\nFlexione os cotovelos e abaixe o peito em direção ao chão.\nEmpurre-se para cima estendendo os cotovelos o mais rápido possível até ficar no ar, "saltando" de 12 a 18 polegadas para um lado.\nAo subir, afaste o pé de fora da direção do salto e gire o corpo cerca de 30 graus no ar.\nVolte à posição inicial e repita, avançando em círculo até voltar ao ponto de partida.',
  'Close-Grip Barbell Bench Press':
    'Deitado em banco reto, pegada fechada na largura dos ombros; retire a barra do suporte e segure-a reta sobre você com os braços estendidos. Posição inicial.\nInspire e desça lentamente até tocar a parte média do peito, mantendo os cotovelos junto ao tronco para focar os tríceps.\nApós um segundo de pausa, expire e empurre a barra com os tríceps até estender os braços; desça pelo menos no dobro do tempo que levou para subir.\nRepita pelo número de repetições prescrito.\nAo terminar, coloque a barra de volta no suporte.',
  'Close-Grip Dumbbell Press':
    'Coloque um halter em pé na vertical sobre um banco reto.\nDeite-se perpendicular ao banco com apenas os ombros apoiados, quadril abaixo do banco e pés firmes no chão.\nSegure o halter com as duas mãos, braços estendidos sobre o peito, palmas pressionando as laterais inferiores do halter. Posição inicial.\nAbaixe o halter até o peito.\nVolte à posição inicial estendendo os cotovelos.',
  'Close-Grip EZ Bar Curl':
    'Em pé, tronco ereto, pegada interna fechada na barra W, palmas para a frente levemente inclinadas para dentro, cotovelos perto do tronco. Posição inicial.\nSem mover os braços, faça a rosca para a frente contraindo os bíceps e expirando; só os antebraços se movem.\nSuba até contrair totalmente os bíceps com a barra na altura dos ombros; aperte por um segundo.\nInspire e leve a barra lentamente de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Close-Grip EZ-Bar Curl with Band':
    'Prenda uma faixa em cada extremidade da barra e pise no meio da faixa com um pé. Em pé, pegada supinada estreita na barra W, cotovelos perto do tronco. Posição inicial.\nSem mover os braços, flexione os cotovelos para a rosca, expirando ao levantar o peso.\nSuba até contrair totalmente os bíceps com a barra na altura dos ombros; aperte por um segundo.\nInspire e leve a barra lentamente de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Close-Grip EZ-Bar Press':
    'Deite-se em um banco reto com uma barra W carregada com um peso adequado.\nPegada estreita; levante a barra e segure-a reta sobre o tronco, cotovelos para dentro, braços perpendiculares ao chão. Posição inicial.\nInspire e abaixe a barra até a parte inferior do peito mantendo os cotovelos junto ao corpo.\nExpire e empurre a barra com os tríceps de volta à posição inicial estendendo os cotovelos.\nRepita.',
  'Close-Grip Front Lat Pulldown':
    'Sente-se na máquina de puxada com barra larga na polia alta e ajuste o apoio dos joelhos à sua altura.\nSegure a barra com as palmas para a frente: aberta (mãos mais afastadas que os ombros), média (na largura dos ombros) ou fechada (mãos mais próximas que os ombros), conforme indicado.\nBraços estendidos à frente, incline o tronco cerca de 30 graus para trás, com curvatura lombar e peito para fora. Posição inicial.\nExpire e puxe a barra até tocar a parte superior do peito, levando ombros e braços para baixo e para trás; contraia as costas, só os braços se movem.\nApós um segundo na contração, aproxime as escápulas e inspire enquanto sobe lentamente a barra até estender os braços e alongar os dorsais.\nRepita este movimento pelo número de repetições prescrito.',
  'Close-Grip Push-Up off of a Dumbbell':
    'Deite-se de bruços com as mãos sobre um halter em pé na vertical, apoiado nas mãos e na ponta dos pés, tronco rígido, cotovelos junto ao corpo, braços retos. Posição inicial.\nInspire e abaixe o corpo flexionando os cotovelos, mantendo-o reto sem deixar o quadril subir ou cair.\nExpire e empurre-se de volta à posição inicial estendendo os cotovelos.\nApós uma pausa na contração, repita pelo número de repetições prescrito.',
  'Close-Grip Standing Barbell Curl':
    'Segure a barra com as duas mãos, palmas para cima, afastadas por poucos centímetros.\nEm pé, tronco reto, cabeça erguida, pés na largura dos ombros e cotovelos perto do tronco; braços e cotovelos parados durante todo o movimento. Posição inicial.\nExpire e faça a rosca em semicírculo até os antebraços tocarem os bíceps; contraia forte por um segundo no topo sem curvar as costas nem balançar o peso.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  Cocoons:
    'Deite-se de costas, pernas retas e braços estendidos atrás da cabeça. Posição inicial.\nLeve os joelhos ao peito girando a pelve para tirar os glúteos do chão, enquanto flexiona a coluna e leva os braços acima da cabeça em um abdominal simultâneo.\nApós uma breve pausa, volte à posição inicial.',
  "Conan's Wheel":
    'Faça a pegada zurcher na extremidade do implemento: barra na dobra do cotovelo, segurando o próprio pulso, peso fora dos antebraços.\nLevante o peso do chão e caminhe com passos curtos e rápidos, postura firme e ereta, olhando para cima e para longe enquanto gira em círculo, sem prender a respiração, até completar uma ou mais voltas.',
  'Concentration Curls':
    'Sente-se em um banco reto com um halter entre as pernas, afastadas, joelhos dobrados e pés no chão.\nApoie o tríceps direito na coxa interna, palma voltada para frente, braço estendido: posição inicial.\nFaça a rosca com o antebraço expirando até o ombro, mindinho mais alto que o polegar; segure a contração 1 segundo.\nLeve o halter lentamente de volta à posição inicial inspirando, sem balançar o corpo.\nRepita pelo número de repetições indicado e depois faça a série com o braço esquerdo.',
  'Cross Body Hammer Curl':
    'Fique em pé com um halter em cada mão, braços ao lado do corpo, palmas voltadas para dentro.\nSem girar o braço, faça a rosca do halter direito em direção ao ombro esquerdo expirando; encoste e segure 1 segundo.\nAbaixe o halter pelo mesmo caminho inspirando e repita com o braço esquerdo.\nAlterne dessa forma até completar as repetições recomendadas para cada braço.',
  'Cross Over - With Bands':
    'Prenda uma faixa elástica em um poste fixo.\nDe costas para o poste, segure as alças da faixa e dê um passo à frente para criar tensão.\nLevante os braços para os lados em forma de "T", paralelos ao chão, palmas à frente e leve flexão nos cotovelos: posição inicial.\nCom os braços retos, traga-os à frente do peito em semicírculo expirando e contraindo o peitoral; segure 1 segundo.\nVolte lentamente à posição inicial enquanto inspira.\nRealize as repetições recomendadas.',
  'Cross-Body Crunch':
    'Deite-se de costas e dobre os joelhos cerca de 60 graus.\nMantenha os pés no chão e as mãos de leve atrás da cabeça: posição inicial.\nLeve o cotovelo e ombro direitos em direção ao joelho esquerdo que sobe ao mesmo tempo, expirando e contraindo o abdômen.\nVolte à posição inicial inspirando e repita com o cotovelo esquerdo e o joelho direito.\nContinue alternando dessa forma até completar todas as repetições prescritas.',
  'Crossover Reverse Lunge':
    'Fique em pé com os pés na largura dos ombros: posição inicial.\nDê um passo atrás flexionando quadril e joelho da frente, girando o tronco sobre a perna da frente.\nApós uma breve pausa, volte à posição inicial e repita do outro lado, alternando.',
  Crucifix:
    'Segure pesos de forma estática com os braços estendidos para os lados; pratique com machados ou martelos, não só halteres.\nLevante os braços para os lados até ficarem paralelos ao chão; use um peso que faça você falhar em 30-60 segundos.',
  'Crunch - Hands Overhead':
    'Deite-se com as costas retas e os joelhos dobrados a cerca de 60 graus entre posteriores de coxa e panturrilhas.\nMantenha os pés no chão e os braços estendidos acima da cabeça com palmas cruzadas: posição inicial.\nEnrole o tronco para a frente e tire só um pouco as escápulas do chão, braços alinhados com cabeça e ombros; expire e segure 1 segundo.\nDesça lentamente à posição inicial enquanto inspira.\nRepita pelas repetições recomendadas.',
  'Crunch - Legs On Exercise Ball':
    'Deite-se de costas com os pés em uma bola de exercício e os joelhos a 90 graus.\nAfaste os pés de 3 a 4 polegadas e aponte os dedos para dentro até se tocarem.\nColoque as mãos de leve dos lados da cabeça, cotovelos para dentro, sem entrelaçar os dedos.\nEmpurre a lombar contra o chão para isolar o abdômen: posição inicial.\nTire os ombros cerca de 4 polegadas do chão, lombar fixa, expirando; aperte o abdômen no topo e segure 1 segundo, sem impulso.\nDesça lentamente à posição inicial enquanto inspira.\nRepita pelas repetições recomendadas.',
  Crunches:
    'Deite-se com os pés no chão ou em um banco, joelhos a 90 graus; no banco, afaste-os 3-4 polegadas com dedos para dentro.\nColoque as mãos de leve dos lados da cabeça, cotovelos para dentro, sem entrelaçar os dedos.\nEmpurre a lombar contra o chão para isolar o abdômen e tire os ombros do chão.\nSuba os ombros cerca de 4 polegadas contraindo o abdômen e expirando, lombar fixa; segure a contração 1 segundo, sem impulso.\nDesça lentamente de volta à posição inicial inspirando.\nRepita pelas repetições recomendadas.',
  'Cuban Press':
    'Em pé, pegue um halter em cada mão com pegada pronada, braços paralelos ao chão e antebraços pendurados (posição de "espantalho").\nRotacione externamente os ombros 180 graus até que os punhos fiquem acima dos cotovelos e os antebraços perpendiculares ao chão.\nEmpurre os halteres estendendo os cotovelos, esticando os braços acima da cabeça.\nVolte à posição inicial enquanto inspira, invertendo os passos.\nRepita pelas repetições recomendadas.',
  "Dancer's Stretch":
    'Sente-se no chão.\nCruze a perna direita sobre a esquerda com o joelho dobrado; deixe a esquerda reta no chão.\nColoque o braço esquerdo sobre a perna direita e a mão direita no chão.\nGire a parte superior do corpo para a direita e segure por 10 a 20 segundos. Troque de lado.',
  'Dead Bug':
    'Comece deitado de costas com as mãos estendidas acima de você em direção ao teto.\nLeve os pés, os joelhos e o quadril até 90 graus.\nExpire forte para abaixar a caixa torácica, achatar as costas, girar a pelve e contrair os glúteos: posição inicial.\nInicie o exercício estendendo uma perna, esticando o joelho e o quadril para levá-la logo acima do chão.\nMantenha fixas a lombar e a pelve durante o movimento; as costas vão querer arquear.\nMantenha-se firme e leve a perna que trabalha de volta à posição inicial.\nRepita do lado oposto, alternando até completar a série.',
  'Deadlift with Bands':
    'Com faixas curtas, passe-as pela barra e pise nelas; as longas ancore em uma base segura como halteres ou um rack.\nAbaixe o quadril e flexione os joelhos até as canelas encostarem na barra, peito erguido e costas arqueadas; empurre com os calcanhares e puxe forte ao passar os joelhos, levando o quadril para a frente.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Deadlift with Chains':
    'Prenda as correntes nas extremidades da barra, ou apoie o meio delas sobre ela para aumentar a carga ao levantar.\nCom a barra centralizada sobre os pés (largura do quadril), flexione o quadril e segure na largura dos ombros (pronada ou mista nas séries pesadas); abaixe quadril e joelhos até as canelas encostarem na barra.\nCom peito erguido e costas arqueadas, empurre com os calcanhares; ao passar os joelhos, puxe forte levando o quadril para a frente.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Decline Barbell Bench Press':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nCom pegada de largura média (90 graus entre antebraço e braço na metade do movimento), retire a barra e segure com braços travados perpendiculares ao chão: posição inicial. Peça ajuda para proteger o manguito rotador.\nAo inspirar, desça lentamente até sentir a barra na parte inferior do peito.\nApós 1 segundo, empurre a barra com o peito expirando até travar os braços; segure 1 segundo e desça o dobro mais devagar que subiu.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, coloque a barra de volta no suporte.',
  'Decline Close-Grip Bench To Skull Crusher':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nCom pegada fechada (um pouco menor que a largura dos ombros), retire a barra e segure com braços travados, cotovelos para dentro, perpendicular ao chão: posição inicial. Peça ajuda para proteger o manguito rotador.\nAbaixe a barra até a parte inferior do peito inspirando, mantendo os cotovelos junto ao corpo.\nUsando os tríceps, pressione a barra de volta à posição inicial enquanto expira.\nCom os braços parados, abaixe a barra em semicírculo em direção à testa inspirando, até encostar de leve.\nLevante a barra de volta à posição inicial contraindo os tríceps e expirando.\nRepita os passos 3-6 até completar o número de repetições recomendado.',
  'Decline Crunch':
    'Prenda as pernas na extremidade do banco declinado e deite-se.\nColoque as mãos de leve dos lados da cabeça, cotovelos para dentro, sem entrelaçar os dedos.\nEmpurre a lombar contra o banco para isolar o abdômen e tire os ombros do banco.\nSuba os ombros cerca de 4 polegadas contraindo o abdômen e expirando, lombar fixa no banco; segure a contração 1 segundo, sem impulso.\nDesça lentamente de volta à posição inicial inspirando.\nRepita pelas repetições recomendadas.',
  'Decline Dumbbell Bench Press':
    'Deite-se no banco declinado com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nDepois de deitado, leve os halteres à sua frente na largura dos ombros.\nGire os punhos para a frente até as palmas ficarem voltadas para longe de você: posição inicial.\nAbaixe os halteres para os lados expirando, com os antebraços sempre perpendiculares ao chão.\nEmpurre os halteres para cima com o peitoral expirando até estender os braços; aperte 1 segundo e desça o dobro mais devagar.\nRepita o movimento conforme seu programa de treino.',
  'Decline Dumbbell Flyes':
    'Deite-se no banco declinado com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nLeve os halteres à sua frente na largura dos ombros, palmas voltadas uma para a outra, braços estendidos e perpendiculares ao chão: posição inicial.\nCom leve flexão nos cotovelos, abaixe os braços em arco amplo até alongar o peito, inspirando; o movimento é só no ombro.\nLeve os braços de volta pela mesma trajetória, expirando e apertando o peito.\nSegure a contração 1 segundo e repita pelas repetições indicadas.',
  'Decline Dumbbell Triceps Extension':
    'Deite-se no banco declinado com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nLeve os halteres à sua frente na largura dos ombros, palmas voltadas uma para a outra, braços estendidos e perpendiculares ao chão: posição inicial.\nCom os braços parados e cotovelos para dentro, abaixe os halteres em semicírculo até as orelhas, inspirando.\nLevante os halteres de volta à posição inicial contraindo os tríceps e expirando.\nRepita pelas repetições recomendadas.',
  'Decline EZ Bar Triceps Extension':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nCom pegada fechada, retire a barra W e segure com braços travados, cotovelos para dentro, perpendicular ao chão: posição inicial. Peça ajuda para proteger o manguito rotador.\nCom os braços parados, abaixe a barra em semicírculo até a testa inspirando, encostando de leve.\nLevante a barra de volta à posição inicial contraindo os tríceps e expirando.\nRepita até completar as repetições recomendadas.',
  'Decline Oblique Crunch':
    'Prenda as pernas na extremidade do banco declinado e deite-se lentamente no banco.\nLevante a parte superior do corpo do banco até que o tronco fique a cerca de 35-45 graus em relação ao chão.\nColoque uma mão ao lado da cabeça e a outra sobre a coxa: posição inicial.\nSuba girando o tronco para a esquerda, expirando, até o cotovelo direito tocar o joelho esquerdo; segure 1 segundo.\nAbaixe lentamente o corpo de volta à posição inicial enquanto inspira.\nComplete as repetições do lado direito e troque para o esquerdo, girando bem o tronco no topo.',
  'Decline Push-Up':
    'De bruços, coloque as mãos a cerca de 36 polegadas de distância e os pés em uma caixa ou banco: posição inicial.\nEm seguida, desça o corpo até que o peito quase toque o chão enquanto inspira.\nAgora expire e empurre a parte superior do corpo de volta à posição inicial enquanto aperta o peito.\nApós uma breve pausa no topo, repita quantas vezes forem necessárias.',
  'Decline Reverse Crunch':
    'Deite-se em um banco declinado e segure sua parte superior com as duas mãos, sem escorregar para baixo.\nMantenha as pernas paralelas ao chão com os abdominais, joelhos e pés juntos, leve flexão nos joelhos: posição inicial.\nLeve as pernas em direção ao tronco expirando, girando a pelve e tirando o quadril do banco, até os joelhos tocarem o peito.\nSegure a contração por um segundo e leve as pernas de volta à posição inicial enquanto inspira.\nRepita pelas repetições recomendadas.',
  'Decline Smith Press':
    'Em um banco declinado sob a máquina Smith, com pegada pronada mais larga que os ombros, destrave a barra e segure com os braços estendidos: posição inicial.\nAo inspirar, abaixe a barra com controle permitindo que os cotovelos flexionem, encostando de leve no tronco.\nApós uma breve pausa, leve a barra de volta à posição inicial estendendo os cotovelos enquanto expira.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar a série, trave a barra de volta no suporte.',
  'Deficit Deadlift':
    'Fique sobre uma plataforma ou anilhas de 1-3 polegadas, barra centralizada sobre os pés (largura do quadril); flexione o quadril e segure na largura dos ombros (pronada ou mista nas séries pesadas).\nAbaixe quadril e joelhos até as canelas encostarem na barra, peito erguido e costas arqueadas; empurre com os calcanhares e puxe forte ao passar os joelhos, levando o quadril para a frente.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Depth Jump Leap':
    'Para este exercício você precisará de duas caixas ou bancos, um com 12 a 16 polegadas de altura e outro com 22 a 26 polegadas.\nFique na caixa mais baixa com os braços ao lado, pés juntos na borda; coloque a outra caixa a 2-3 pés à frente.\nComece se deixando cair da primeira caixa, aterrissando e decolando simultaneamente com os dois pés.\nRebata com força para cima e para a frente usando braços e extensão total do corpo para saltar a caixa alta, amortecendo com as pernas.',
  'Dip Machine':
    'Sente-se com firmeza em uma máquina de paralelas, selecione a carga e segure firmemente as alças.\nMantenha os cotovelos junto ao corpo, dobrados a 90 graus, para enfatizar o tríceps.\nEstenda os braços para baixo expirando e contraindo o tríceps, sem travar totalmente os cotovelos.\nAgora deixe os braços voltarem lentamente à posição inicial enquanto inspira.\nRepita pelas repetições recomendadas.',
  'Dips - Chest Version':
    'Em barras paralelas, sustente o corpo com os braços estendidos e travados: posição inicial.\nDesça inspirando com o tronco inclinado cerca de 30 graus e os cotovelos um pouco abertos, até sentir alongamento no peito.\nUse o peito para subir à posição inicial expirando e aperte o peito 1 segundo no topo.\nRepita o movimento pelo número de repetições prescrito.',
  'Dips - Triceps Version':
    'Sustente o corpo nas barras com os braços estendidos, quase travados: posição inicial.\nInspire e desça com o tronco ereto e os cotovelos perto do corpo, até formar 90 graus entre braço e antebraço.\nEntão, expire e empurre o tronco para cima usando os tríceps para levar o corpo de volta à posição inicial.\nRepita o movimento pelo número de repetições prescrito.',
  'Donkey Calf Raises':
    'Na máquina de panturrilha tipo burro, posicione a lombar e o quadril sob a alavanca acolchoada, com o cóccix apoiado no apoio.\nSegure as alças laterais, apoie a parte da frente dos pés no bloco com os calcanhares para fora, oriente os pés conforme a área a trabalhar e estique os joelhos sem travar.\nExpire e suba os calcanhares ao máximo estendendo os tornozelos e contraindo a panturrilha; mantenha o joelho parado e segure a contração por 1 segundo.\nInspire e desça os calcanhares lentamente, flexionando os tornozelos até alongar totalmente a panturrilha.\nRepita pelo número de repetições recomendado.',
  'Double Kettlebell Alternating Hang Clean':
    'Coloque dois kettlebells entre os pés; leve o quadril para trás e olhe para a frente na posição inicial.\nFaça um clean de um kettlebell até o ombro enquanto segura o outro kettlebell embaixo.\nEm um movimento fluido, abaixe o kettlebell de cima enquanto sobe o de baixo.',
  'Double Kettlebell Jerk':
    'Segure um kettlebell pela alça em cada mão.\nEstenda pernas e quadril para levar os kettlebells aos ombros, girando os punhos até as palmas ficarem para frente; essa é sua posição inicial.\nDesça o corpo flexionando os joelhos e mantendo o tronco ereto.\nInverta a direção imediatamente empurrando com os calcanhares, como se saltasse para gerar impulso.\nCom esse impulso, empurre os kettlebells acima da cabeça até estender os braços.\nLeve os pés ao chão em posição dividida, um à frente e outro atrás.\nCom os pesos travados no alto, junte os pés em pé e abaixe os pesos para a próxima repetição.',
  'Double Kettlebell Push Press':
    'Leve dois kettlebells até os ombros.\nAgache alguns centímetros e inverta o movimento rápido, usando o impulso das pernas para levar os kettlebells acima da cabeça.\nCom os kettlebells travados no alto, abaixe-os até os ombros e repita.',
  'Double Kettlebell Snatch':
    'Coloque dois kettlebells atrás dos pés; flexione os joelhos e leve o quadril para trás para pegá-los.\nBalance os kettlebells com força entre as pernas e inverta a direção.\nEmpurre com o quadril e trave os kettlebells acima da cabeça em um único movimento contínuo.',
  'Double Kettlebell Windmill':
    'Coloque um kettlebell à frente do pé da frente; faça o clean e desenvolvimento do outro kettlebell acima da cabeça com o braço oposto, estendendo pernas e quadril e girando o punho até a palma ficar para frente.\nCom o kettlebell travado no alto o tempo todo, empurre o quadril para esse lado e gire os pés 45 graus em relação ao braço travado.\nFlexione o quadril para esse lado, empurre o quadril para fora e incline-se devagar até pegar o kettlebell do chão, com os olhos fixos no kettlebell de cima.\nPause 1 segundo ao pegar o kettlebell do chão e inverta o movimento até a posição inicial.',
  'Double Leg Butt Kick':
    'Comece em pé com os joelhos ligeiramente flexionados.\nAgache rápido uma curta distância flexionando quadril e joelhos, e estenda-se imediatamente para saltar na máxima altura.\nAo subir, flexione os joelhos e leve os calcanhares em direção aos glúteos tentando tocá-los.\nAterrisse com os joelhos apenas parcialmente flexionados, usando as pernas para absorver o impacto.',
  'Downward Facing Balance':
    'Deite-se de bruços sobre uma bola de exercício.\nApoiado com o abdômen na bola, caminhe com as mãos para a frente pelo chão e levante as pernas, estendendo cotovelos e joelhos.',
  'Drag Curl':
    'Segure a barra com pegada supinada (palmas para frente) e leve os cotovelos para perto do tronco e para trás; essa é sua posição inicial.\nExpire e suba a barra «arrastrando-a» colada ao tronco, mantendo os cotovelos para trás (não junto ao corpo) e sem levantar os ombros.\nVolte lentamente à posição inicial mantendo a barra em contato com o tronco.\nRepita pelo número de repetições recomendado.',
  'Drop Push':
    'Posicione duas caixas baixas ou outras plataformas afastadas de 60 a 90 cm.\nPosicione-se em prancha entre elas, apoiando as mãos sobre as caixas.\nCom boa postura, empurre para cima e caia das plataformas levando as mãos à largura dos ombros; amorteça a aterrissagem com os braços.',
  'Dumbbell Alternate Bicep Curl':
    'Em pé, tronco ereto, um halter em cada mão, braços estendidos, cotovelos perto do tronco e palmas voltadas para as coxas.\nSem mover o braço, faça a rosca com o halter direito girando a palma para frente; expire e contraia o bíceps até a altura do ombro, segure 1 segundo movendo só o antebraço.\nInspire e desça lentamente o halter à posição inicial girando a palma de volta para a coxa.\nRepita o movimento com a mão esquerda; isso equivale a uma repetição.\nContinue alternando pelo número de repetições recomendado.',
  'Dumbbell Bench Press':
    'Deite-se em um banco reto com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nUse as coxas para ajudar e levante os halteres um de cada vez até segurá-los à frente na largura dos ombros.\nGire os punhos para frente com os halteres ao lado do peito, braço e antebraço em 90 graus; essa é sua posição inicial com controle total do peso.\nExpire e empurre os halteres para cima com o peito até estender os braços, aperte 1 segundo e comece a descer.\nRepita pelo número de repetições do seu programa; desça o peso no dobro da velocidade da subida.',
  'Dumbbell Bench Press with Neutral Grip':
    'Pegue um halter em cada mão e deite-se em um banco reto com os pés no chão e as escápulas retraídas.\nCom pegada neutra (palmas uma para a outra), estenda os braços acima de você, perpendiculares ao chão; essa é sua posição inicial.\nFlexione os cotovelos e abaixe os braços para os lados até os halteres chegarem à altura do tronco.\nFaça uma pausa, estenda os cotovelos e volte à posição inicial.',
  'Dumbbell Bicep Curl':
    'Em pé, coluna reta, um halter em cada mão, braços estendidos, cotovelos perto do tronco e palmas para frente; essa é sua posição inicial.\nSem mover os braços, expire e faça a rosca com os halteres contraindo o bíceps até a altura dos ombros; segure a contração um instante.\nInspire e abaixe lentamente os halteres à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Clean':
    'Em pé, um halter em cada mão, pés na largura dos ombros.\nAbaixe os halteres ao chão flexionando quadris e joelhos e empurrando o quadril para trás; essa é sua posição inicial.\nSalte com força estendendo quadris, joelhos e tornozelos para acelerar os halteres para cima, braços retos com pegada neutra até a extensão completa.\nFlexione de novo quadris e joelhos para receber o peso em agachamento, deixando os braços dobrarem e guiarem os halteres aos ombros.\nEstenda quadris e joelhos para terminar em pé com os halteres sobre os ombros.',
  'Dumbbell Floor Press':
    'Deite-se no chão com um halter em cada mão, joelhos dobrados se preferir, braços estendidos acima de você.\nAbaixe os halteres até a parte superior do braço tocar o chão; cotovelos junto ao corpo para enfatizar o tríceps ou abertos para focar no peito.\nPause embaixo e junte os halteres no topo estendendo os cotovelos.',
  'Dumbbell Flyes':
    'Deite-se em um banco reto com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nLevante os halteres um de cada vez até a largura dos ombros, como em um supino, e pare antes de estender totalmente os cotovelos; essa é sua posição inicial.\nCom os cotovelos levemente flexionados, inspire e abaixe os braços em arco amplo para os lados até sentir alongamento no peito, movendo apenas o ombro.\nExpire e retorne os braços pelo mesmo arco, apertando o peito na posição inicial.\nSegure a contração 1 segundo e repita pelo número de repetições prescrito.',
  'Dumbbell Incline Row':
    'Apoie-se de bruços em um banco inclinado com pegada neutra.\nPegue um halter em cada mão com pegada neutra e braços retos; essa é sua posição inicial.\nRetraia as escápulas e flexione os cotovelos para remar os halteres até a lateral do corpo.\nPause no topo e volte à posição inicial.',
  'Dumbbell Incline Shoulder Raise':
    'Sente-se em um banco inclinado com um halter em cada mão sobre as coxas.\nImpulsione-se com as pernas, incline-se para trás e posicione os halteres acima dos ombros com braços estendidos perpendiculares ao chão, palmas para frente e nós dos dedos para o teto; essa é sua posição inicial.\nExpire e, com os braços retos e travados, levante os halteres elevando os ombros do banco.\nInspire e traga os halteres de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Lunges':
    'Em pé, tronco ereto, dois halteres ao lado do corpo; essa é sua posição inicial.\nDê um passo à frente com a perna direita (cerca de 60 cm) e abaixe o corpo mantendo o tronco ereto e o equilíbrio, inspirando; mantenha a canela da frente perpendicular ao chão e o joelho sem ultrapassar os dedos do pé.\nEmpurre principalmente com o calcanhar e expire ao voltar à posição inicial.\nRepita pelo número de repetições recomendado e depois faça com a perna esquerda.',
  'Dumbbell Lying One-Arm Rear Lateral Raise':
    'Com um halter em uma das mãos, deite-se de bruços em um banco ajustável inclinado cerca de 15 graus; a outra mão pode segurar a perna do banco.\nPosicione a palma de forma neutra (voltada para o tronco), braço estendido com o cotovelo levemente flexionado; essa é sua posição inicial.\nExpire e levante o braço com o halter para o lado até o cotovelo ficar na altura do ombro e o braço quase paralelo ao chão; mantenha o braço perpendicular ao tronco e a contração por 1 segundo.\nInspire e abaixe lentamente o halter até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Lying Pronation':
    'Deite-se de bruços em um banco reto, um braço com halter e a outra mão dobrada sob a cabeça como apoio.\nDobre o cotovelo do braço com o halter a 90 graus entre braço e antebraço.\nLevante o braço até o antebraço ficar perpendicular ao chão e o braço perpendicular ao tronco (braço paralelo ao chão, a 90 graus do tronco); essa é sua posição inicial.\nExpire e rotacione externamente o antebraço para elevar o halter à frente mantendo os 90 graus, até o antebraço ficar paralelo ao chão; segure a contração 1 segundo.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Lying Rear Lateral Raise':
    'Com um halter em cada mão, deite-se de bruços em um banco ajustável inclinado cerca de 15 graus.\nPosicione as palmas de forma neutra (voltadas para o tronco), braços estendidos com cotovelos levemente flexionados; essa é sua posição inicial.\nExpire e levante os braços para os lados até os cotovelos ficarem na altura dos ombros e os braços quase paralelos ao chão; mantenha-os perpendiculares ao tronco e a contração por 1 segundo.\nInspire e abaixe lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado e troque para o outro braço.',
  'Dumbbell Lying Supination':
    'Deite-se de lado em um banco reto, um braço com halter e a outra mão dobrada sob a cabeça como apoio.\nDobre o cotovelo do braço com o halter a 90 graus entre braço e antebraço.\nLevante o braço até o antebraço ficar paralelo ao chão e perpendicular ao tronco, com o braço parado junto ao tronco e paralelo ao chão; essa é sua posição inicial.\nExpire e rotacione externamente o antebraço em semicírculo para elevar o halter, mantendo os 90 graus, até o antebraço ficar perpendicular ao chão apontando para o teto; segure a contração 1 segundo.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Dumbbell One-Arm Shoulder Press':
    'Pegue um halter e sente-se em um banco de desenvolvimento militar ou utilitário com encosto, com o halter na vertical sobre a coxa, ou fique em pé com a coluna reta.\nFaça um clean com o halter até o ombro; mantenha a outra mão estendida ao lado, na cintura ou segurando uma superfície fixa.\nGire o punho com a palma para frente; essa é sua posição inicial.\nExpire e empurre o halter para cima até estender o braço por completo.\nPause 1 segundo e inspire enquanto desce lentamente à posição inicial.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Dumbbell One-Arm Triceps Extension':
    'Pegue um halter e sente-se em um banco de desenvolvimento militar ou utilitário com encosto, com o halter na vertical sobre a coxa, ou fique em pé com a coluna reta.\nFaça um clean com o halter até o ombro e estenda o braço acima da cabeça, perpendicular ao chão e junto à cabeça; a outra mão pode apoiar o braço, ir à cintura ou segurar uma superfície fixa.\nGire o punho com a palma para frente e o dedo mínimo para o teto; essa é sua posição inicial.\nInspire e abaixe lentamente o halter atrás da cabeça, mantendo o braço parado, até alongar totalmente o tríceps.\nExpire e retorne à posição inicial contraindo o tríceps, movendo apenas o antebraço enquanto o braço fica fixo junto à cabeça.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Dumbbell One-Arm Upright Row':
    'Pegue um halter e fique em pé com a coluna reta, o braço estendido à frente com leve flexão no cotovelo e a palma voltada para a coxa; essa é sua posição inicial.\nMantenha a outra mão estendida ao lado, na cintura ou segurando uma superfície fixa.\nExpire e levante o halter perto do corpo com os ombros laterais até quase a altura do queixo; o cotovelo deve ficar sempre mais alto que o antebraço, o tronco parado e pause 1 segundo no topo.\nInspire e abaixe lentamente o halter até a posição inicial.\nRepita pelo número de repetições recomendado e troque de braço.',
  'Dumbbell Prone Incline Curl':
    'Pegue um halter em cada mão e deite-se de bruços em um banco inclinado com os ombros perto do encosto; apoie os joelhos no assento ou abra as pernas para os lados.\nDeixe os braços pendurarem naturalmente à frente, perpendiculares ao chão.\nJunte os cotovelos às laterais do corpo e gire as palmas para frente; essa é sua posição inicial.\nExpire e suba os halteres contraindo o bíceps até flexionar totalmente os braços, movendo apenas os antebraços.\nAbaixe os halteres até estender totalmente os braços.\nRepita o número de vezes recomendado.',
  'Dumbbell Raise':
    'Pegue um halter em cada mão, fique em pé com a coluna reta e os braços ao lado do corpo com leve flexão no cotovelo, palmas para trás; essa é sua posição inicial.\nExpire e levante os halteres ao lado do corpo com os ombros laterais até quase a altura do queixo; o cotovelo deve ficar sempre mais alto que o antebraço, tronco parado e pause 1 segundo no topo.\nInspire e abaixe lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Rear Lunge':
    'Em pé, tronco ereto, dois halteres ao lado do corpo; essa é sua posição inicial.\nDê um passo atrás com a perna direita (cerca de 60 cm do pé esquerdo) e abaixe o corpo mantendo o tronco ereto e o equilíbrio, inspirando; não deixe o joelho ultrapassar os dedos do pé nem a canela da frente perder o ângulo perpendicular. Um afundo longo enfatiza o glúteo máximo; um curto, o quadríceps.\nExpire e empurre para cima para voltar à posição inicial; empurre com a ponta do pé para enfatizar o quadríceps ou com o calcanhar para focar o glúteo.\nRepita com a perna oposta.',
  'Dumbbell Scaption':
    'Segure um peso leve em cada mão ao lado do corpo, com os polegares apontando para cima, para estabilizar a escápula.\nLevante os braços à frente, a cerca de 30 graus do centro, mantendo-os totalmente estendidos.\nSuba até os braços ficarem paralelos ao chão e volte à posição inicial.',
  'Dumbbell Seated Box Jump':
    'Posicione uma caixa a 60 cm de um banco, sente-se de frente para ela e segure um halter junto ao peito com as duas mãos.\nApoie os pés no chão, incline-se para frente e estenda quadris e joelhos para saltar para cima e para frente.\nAterrisse na caixa com os dois pés, flexionando quadris e joelhos para absorver o impacto.\nDesça da caixa e retorne à posição inicial.',
  'Dumbbell Seated One-Leg Calf Raise':
    'Coloque um bloco no chão a cerca de 30 cm de um banco reto.\nSente-se no banco e coloque um halter sobre a coxa esquerda, 8 cm acima do joelho.\nApoie a parte da frente do pé esquerdo no bloco; essa é sua posição inicial.\nSuba o mais alto possível sobre os dedos do pé, expirando e contraindo a panturrilha; segure 1 segundo.\nDesça lentamente à posição inicial, alongando a panturrilha o máximo possível.\nRepita as repetições prescritas e depois troque para a perna direita.',
  'Dumbbell Shoulder Press':
    'Sente-se em um banco com encosto segurando um halter em cada mão, apoiados na vertical sobre as coxas.\nSuba os halteres até a altura dos ombros um de cada vez, usando o impulso das coxas.\nGire os punhos com as palmas voltadas para frente; essa é sua posição inicial.\nExpire e empurre os halteres para cima até se tocarem no topo.\nFaça uma breve pausa no topo e abaixe lentamente os halteres à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Shrug':
    'Fique em pé com um halter em cada mão, palmas voltadas para o tronco e braços estendidos ao lado do corpo.\nEleve os ombros o mais alto possível expirando, com os braços sempre estendidos e sem ajuda dos bíceps; segure 1 segundo.\nAbaixe os halteres de volta à posição original.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Side Bend':
    'Fique em pé, coluna reta, pés na largura dos ombros, halter na mão esquerda (palma para o tronco) e a direita na cintura.\nIncline-se para a direita a partir da cintura, o mais longe possível, inspirando e sem mover o resto do corpo; segure 1 segundo e volte expirando.\nRepita o movimento inclinando-se para a esquerda; segure 1 segundo e volte à posição inicial.\nRepita pelo número de repetições recomendado e troque de mão.',
  'Dumbbell Squat':
    'Fique em pé, coluna reta, com um halter em cada mão e palmas voltadas para as pernas.\nSepare os pés na largura dos ombros, pontas levemente para fora, cabeça erguida e coluna reta; essa é sua posição inicial.\nDesça o tronco flexionando os joelhos até as coxas ficarem paralelas ao chão, sem deixar os joelhos ultrapassarem a ponta dos pés.\nSuba expirando, empurrando o chão com o calcanhar, até estender as pernas e voltar à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Squat To A Bench':
    'Fique em pé, coluna reta, com um banco atrás de você e um halter em cada mão, palmas voltadas para as pernas.\nSepare os pés na largura dos ombros, pontas levemente para fora, cabeça erguida e coluna reta; essa é sua posição inicial.\nDesça o tronco flexionando os joelhos, inspirando, até tocar levemente o banco, sem que os joelhos ultrapassem a ponta dos pés.\nSuba expirando, empurrando o chão com o calcanhar, até estender as pernas e voltar à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Dumbbell Step Ups':
    'Fique em pé, coluna reta, com um halter em cada mão e palmas voltadas para as pernas.\nApoie o pé direito na plataforma e suba estendendo quadril e joelho, impulsionando-se com o calcanhar; expire e leve também o pé esquerdo para cima.\nDesça primeiro com a perna esquerda flexionando quadril e joelho da direita, inspirando, até ficar em pé na posição inicial.\nRepita com a perna direita pelo número de repetições recomendado e depois troque para a esquerda.',
  'Dumbbell Tricep Extension -Pronated Grip':
    'Deite-se em um banco reto com dois halteres sobre os ombros, braços estendidos a 90 graus em relação ao chão.\nPalmas voltadas para frente e cotovelos junto ao corpo; essa é sua posição inicial.\nInspire e abaixe lentamente os halteres até perto das orelhas, com os braços parados e cotovelos junto ao corpo.\nExpire e use os tríceps para retornar o peso à posição inicial.',
  'Dynamic Back Stretch':
    'Fique em pé com os pés na largura dos ombros; essa é sua posição inicial.\nCom os braços retos, balance-os à frente de 5 a 10 vezes, aumentando a amplitude até passar da cabeça.',
  'Dynamic Chest Stretch':
    'Fique em pé com as mãos juntas e os braços estendidos à frente; essa é sua posição inicial.\nCom os braços retos, leve-os rápido para trás o mais longe possível e de volta, como uma palma exagerada; repita 5-10 vezes aumentando a velocidade.',
  'EZ-Bar Curl':
    'Fique em pé, coluna reta, com a barra W em pegada externa larga, palmas para frente e cotovelos junto ao tronco; essa é sua posição inicial.\nCom os braços parados, expire e suba a barra contraindo os bíceps, movendo apenas os antebraços.\nSuba até contrair totalmente os bíceps com a barra na altura dos ombros; segure um momento e aperte.\nInspire e abaixe lentamente a barra à posição inicial.\nRepita pelo número de repetições recomendado.',
  'EZ-Bar Skullcrusher':
    'Com pegada fechada, levante a barra W e deite-se no banco com os cotovelos para dentro e os braços perpendiculares ao chão; essa é sua posição inicial.\nCom os braços parados, inspire e abaixe a barra flexionando os cotovelos até ficar sobre a testa.\nExpire e estenda os cotovelos para subir a barra à posição inicial.\nRepita.',
  'Elbow Circles':
    'Sente-se ou fique em pé com os pés ligeiramente afastados.\nColoque as mãos sobre os ombros com os cotovelos na altura dos ombros e apontando para fora.\nFaça lentamente um círculo com os cotovelos, expirando ao iniciar e inspirando ao terminar.',
  'Elbow to Knee':
    'Deite-se com a perna direita cruzada sobre o joelho esquerdo flexionado e as mãos entrelaçadas atrás da cabeça, escápulas no chão.\nFlexione a coluna e rotacione o tronco levando o cotovelo esquerdo em direção ao joelho direito.\nRetorne à posição inicial e repita as repetições desejadas antes de trocar de lado.',
  'Elbows Back':
    'Fique em pé com a coluna reta.\nColoque as duas mãos na região lombar, com os dedos apontando para baixo e os cotovelos para fora.\nLeve suavemente os cotovelos para trás, tentando juntá-los.',
  'Elevated Back Lunge':
    'Posicione uma barra carregada em um rack na altura dos ombros e uma plataforma baixa atrás de você.\nRetire a barra e apoie-a na parte superior das costas, com as costas arqueadas; suba na plataforma com os dois pés.\nDê um passo para trás com uma perna e desça flexionando quadris e joelhos até o joelho tocar o chão.\nFaça uma pausa, estenda quadris e joelhos para subir, e retorne à posição inicial antes de alternar.',
  'Elevated Cable Rows':
    'Arranje uma plataforma de 10 a 15 cm de altura (de aeróbica ou de elevação de panturrilhas).\nColoque-a sobre o assento da máquina de remada na polia.\nSente-se e apoie os pés na plataforma ou barra transversal, com os joelhos levemente flexionados e sem travar.\nIncline-se para frente mantendo o alinhamento natural da coluna e segure as pegadas em V.\nCom os braços estendidos, incline-se para trás até formar 90 graus entre tronco e pernas, costas arqueadas e peito estufado; você sentirá alongamento nos dorsais. Essa é sua posição inicial.\nCom o tronco parado, expire e puxe as pegadas até os abdominais, contraindo as costas; mantenha 1 segundo e volte inspirando.\nRepita pelo número de repetições recomendado.',
  'Elliptical Trainer':
    'Suba no elíptico e escolha o modo manual ou um programa; insira idade e peso para estimar calorias e ajuste a inclinação conforme a intensidade.\nUse as alças para monitorar sua frequência cardíaca e manter a intensidade adequada.',
  'Exercise Ball Crunch':
    'Deite-se sobre a bola com a lombar apoiada, joelhos flexionados e pés firmes no chão; braços ao lado do corpo ou cruzados no peito para não tensionar o pescoço.\nAbaixe o tronco até se alongar, mantendo o pescoço parado; essa é sua posição inicial.\nCom o quadril parado, expire e enrole ombros e tronco para cima contraindo os abdominais, sem tirar a lombar da bola; segure 1 segundo.\nInspire e volte à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Exercise Ball Pull-In':
    'Deite-se de frente para uma bola de exercício com as mãos no chão na largura dos ombros, em posição de flexão de braço.\nColoque a parte inferior das canelas sobre a bola, pernas estendidas e braços à frente sustentando o corpo; essa é sua posição inicial.\nCom a coluna reta e o tronco parado, expire e leve os joelhos ao peito deixando a bola rolar sob os tornozelos; contraia os abdominais por 1 segundo.\nInspire e estenda lentamente as pernas, rolando a bola de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Extended Range One-Arm Kettlebell Floor Press':
    'Deite-se no chão com um kettlebell segurado pela alça para empurrar com um braço; flexione a perna do mesmo lado cruzando o joelho pela linha média do corpo.\nEmpurre o kettlebell estendendo o cotovelo e aduzindo o braço sobre o corpo, depois retorne à posição inicial.',
  'External Rotation':
    'Deite-se de lado em um banco com um halter em um braço e a outra mão dobrada sob a cabeça como apoio.\nDobre o cotovelo do braço com o halter a 90 graus, mantendo o braço paralelo ao tronco.\nCom o braço parado junto ao tronco e paralelo ao chão, o antebraço fica perpendicular ao tronco e à sua frente; essa é sua posição inicial.\nExpire e rotacione externamente o antebraço em semicírculo, mantendo 90 graus, até apontar perpendicular ao teto; segure 1 segundo.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado e troque de braço.',
  'External Rotation with Band':
    'Prenda a faixa em um poste na altura do cotovelo e fique em pé com o lado esquerdo voltado para ela, a alguns passos.\nSegure a faixa com a mão direita, cotovelo junto ao corpo; use uma almofada ou rolo de espuma para fixá-lo.\nFlexione o cotovelo a 90 graus com a mão cruzando a frente do tronco; essa é sua posição inicial.\nExecute o movimento rotacionando o braço como um backhand, mantendo o cotovelo no lugar.\nContinue o mais longe possível, faça uma pausa e retorne à posição inicial.',
  'External Rotation with Cable':
    'Ajuste o cabo na altura do cotovelo e fique em pé com o lado esquerdo voltado para ele, a alguns passos.\nSegure a pegada com a mão direita, cotovelo junto ao corpo; use uma almofada ou rolo de espuma para fixá-lo.\nFlexione o cotovelo a 90 graus com a mão cruzando a frente do tronco; essa é sua posição inicial.\nExecute o movimento rotacionando o braço como um backhand, mantendo o cotovelo no lugar.',
  'Face Pull':
    'De frente para uma polia alta com corda ou pegadas duplas, puxe em direção ao rosto separando as mãos, braços paralelos ao chão.',
  "Farmer's Walk":
    'Fique em pé entre os implementos (ou halteres pesados/barras curtas se não houver outros disponíveis).\nSegure as alças e levante-as empurrando com os calcanhares, coluna reta e cabeça erguida.\nCaminhe com passos curtos e rápidos, respirando, por 15 a 30 metros o mais rápido possível.',
  'Fast Skipping':
    'Fique em posição relaxada com uma perna levemente à frente; essa é sua posição inicial.\nSalte com o padrão direita-direita-passo, esquerda-esquerda-passo, alternando de um lado para o outro.\nSalte rápido, com contato breve no chão e pouco tempo no ar, na maior velocidade possível.',
  'Finger Curls':
    'Segure uma barra com as duas mãos e as palmas voltadas para cima; mãos afastadas aproximadamente na largura dos ombros.\nApoie os pés no chão, um pouco mais afastados que a largura dos ombros; essa é sua posição inicial.\nEstenda os dedos e abaixe a barra o máximo possível, deixando-a rolar até segurá-la com a última articulação dos dedos.\nExpire e feche as mãos para subir a barra o mais alto possível; mantenha a contração no topo.',
  'Flat Bench Cable Flyes':
    'Posicione um banco reto entre duas polias baixas, com o peito alinhado às polias ao se deitar.\nDeite-se de costas no banco com os pés apoiados no chão.\nPeça para passarem uma pegada em cada mão; segure-as com as palmas voltadas para cima.\nEstenda os braços para os lados, cotovelos com flexão leve e fixa, paralelos ao chão: posição inicial.\nPuxe os cabos em semicírculo à sua frente até unir as mãos no topo; contraia o peito, expire e segure 1 segundo com os braços perpendiculares, tocando-se sobre o peito.\nVolte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Flat Bench Leg Pull-In':
    'Deite-se em um tapete ou banco reto com as pernas para fora da extremidade.\nColoque as mãos sob os glúteos (palmas para baixo) ou segure o banco ao lado, pernas retas: posição inicial.\nFlexione os joelhos e puxe as coxas em direção ao abdômen ao expirar, até quase tocarem o peito; segure 1 segundo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Flat Bench Lying Leg Raise':
    'Deite-se com as costas apoiadas em um banco, pernas estendidas à frente, fora da extremidade.\nColoque as mãos sob os glúteos (palmas para baixo) ou segure o banco ao lado: posição inicial.\nCom as pernas o mais retas possível (joelhos levemente flexionados mas travados), suba até 90 graus com o chão; expire e segure 1 segundo.\nAo inspirar, abaixe lentamente as pernas até a posição inicial.',
  'Flexor Incline Dumbbell Curls':
    'Segure o halter mais para o lado distante de você, para ter mais peso no lado próximo (vale para toda rosca de bíceps com halteres).\nSente-se em um banco inclinado a 45 graus com um halter em cada mão.\nBraços pendurados ao lado, cotovelos para dentro, palmas para frente e polegares longe do corpo: posição fixa durante todo o movimento.\nSuba os dois halteres ao mesmo tempo até contrair totalmente o bíceps e expire; sem balanço nem impulso, segure 1 segundo no topo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Floor Glute-Ham Raise':
    'Use um parceiro ou prenda os pés sob algo estável.\nAjoelhe-se com coxas e tronco eretos; o parceiro segura firme seus pés: posição inicial.\nAbaixe-se estendendo os joelhos para a frente, sem flexionar os quadris.\nAo chegar ao chão, apoie as mãos à frente; empurre levemente com os braços para voltar (movimento difícil, pode exigir ajuda).',
  'Floor Press':
    'Ajuste os ganchos em J na altura adequada; deitado no chão com a cabeça perto do rack, retire a barra mantendo as escápulas unidas.\nAbaixe a barra ao peito baixo ou abdômen alto, apertando-a como se fosse parti-la e com os cotovelos junto ao corpo; pause quando o braço tocar o chão, sem bater nem quicar.\nEmpurre a barra para cima o mais rápido possível, com barra, punhos e cotovelos alinhados.',
  'Floor Press with Chains':
    'Ajuste os ganchos em J; coloque as correntes sobre a extremidade da barra, com as pontas longe das anilhas.\nDeitado no chão com a cabeça perto do rack, retire a barra mantendo as escápulas unidas.\nAbaixe a barra ao peito baixo ou abdômen alto, apertando-a como se fosse parti-la e com os cotovelos junto ao corpo; pause quando o braço tocar o chão, sem bater nem quicar.\nEmpurre a barra para cima o mais rápido possível, com barra, punhos e cotovelos alinhados.',
  'Flutter Kicks':
    'Em um banco reto, deite-se de bruços com os quadris na borda, pernas retas sem tocar o chão e mãos segurando a borda da frente.\nContraia glúteos e posteriores de coxa e estique as pernas na altura dos quadris: posição inicial.\nLevante a perna esquerda mais alto que a direita.\nAbaixe a esquerda enquanto levanta a direita.\nAlterne assim (como batendo pernas na água) até completar as repetições por perna, com movimento controlado e respiração normal.',
  'Foot-SMR':
    'Sentado e sem sapatos, apoie o arco do pé sobre um rolo para pés (ou um pedaço de cano de PVC): posição inicial.\nPressione com firmeza e role ao longo do arco do pé; mantenha 10 a 30 segundos e troque de pé.',
  'Forward Drag with Press':
    'Prenda ao trenó um acessório de corrente ou corda com duas alças; fique de costas para o trenó, uma alça em cada mão.\nDê um passo à frente inclinando-se e estendendo pernas e quadris; a cada passo, pause para estender os cotovelos empurrando as mãos à frente, até voltar à posição de empurrar.',
  'Frankenstein Squat':
    'Este exercício ensina a posição correta da barra e do corpo no clean e no agachamento frontal.\nColoque a barra nos ombros, solte a pegada e estenda os braços à frente; ombros para a frente formando prateleira, barra tocando a garganta; mova só as escápulas, sem arredondar a coluna torácica.\nAgache flexionando joelhos e quadris, sentando entre as pernas; tronco ereto, braços elevados, ombros para frente e a barra fixa, até os posteriores de coxa tocarem as panturrilhas.\nVolte à posição em pé empurrando com a parte da frente do calcanhar e estendendo joelhos e quadris.',
  'Freehand Jump Squat':
    'Cruze os braços sobre o peito.\nCom a cabeça erguida e as costas retas, posicione os pés na largura dos ombros.\nAgache ao inspirar, costas retas e peito elevado, até que as coxas fiquem paralelas ao chão ou mais baixo.\nEmpurrando com a parte da frente dos pés, salte o mais alto possível usando as coxas como mola; expire no salto.\nAo tocar o chão, agache imediatamente e salte de novo.\nRepita pelo número de repetições recomendado.',
  'Frog Hops':
    'Fique em pé com as mãos atrás da cabeça e agache, tronco ereto e cabeça erguida: posição inicial.\nSalte para a frente vários pés sem saltar muito alto; ao aterrissar, absorva o impacto com as pernas e salte de novo. Repita 5 a 10 vezes.',
  'Frog Sit-Ups':
    'Deite-se com as costas no chão ou tapete, pernas estendidas à sua frente.\nDobre os joelhos e aproxime a parte externa das coxas do chão enquanto une as solas dos pés.\nEmpurre as duas solas para trazê-las para perto de você mantendo as coxas quase no chão, formando um losango com as pernas.\nCruze os braços à frente tocando os ombros opostos: posição inicial.\nAo expirar, achate a lombar no chão e enrole o tronco para cima (como o primeiro quarto de um abdominal); segure 1 segundo no topo.\nAo inspirar, volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Barbell Squat':
    'Faça dentro de um rack por segurança; carregue a barra na altura adequada, leve os braços sob ela com cotovelos altos e braço superior quase paralelo ao chão, apoie-a nos deltoides e cruze os braços para segurá-la.\nRetire a barra do rack empurrando com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack, pés na largura dos ombros e pontas levemente para fora, cabeça erguida e costas retas: posição inicial (base média; há outras duas opções de pés).\nDesça flexionando os joelhos, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar pouco menor que 90 graus; inspire. Os joelhos não devem passar da linha das pontas dos pés.\nSuba a barra ao expirar, empurrando o chão com o meio do pé e esticando as pernas até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Barbell Squat To A Bench':
    'Faça dentro de um rack por segurança, com um banco reto atrás; carregue a barra na altura adequada, braços sob ela com cotovelos altos, apoie-a nos deltoides e cruze os braços para segurá-la.\nRetire a barra do rack empurrando com as pernas e endireitando o tronco ao mesmo tempo.\nAfaste-se do rack, pés na largura dos ombros e pontas levemente para fora, cabeça erguida e costas retas: posição inicial (base média; há outras duas opções de pés).\nDesça flexionando os joelhos até tocar o banco com os glúteos, costas retas e cabeça erguida; inspire. Os joelhos não devem passar da linha das pontas dos pés.\nSuba a barra ao expirar, empurrando o chão principalmente com o calcanhar e esticando as pernas até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Box Jump':
    'Coloque uma caixa a 1-2 pés à sua frente; pés na largura dos ombros: posição inicial.\nFaça um agachamento curto como preparação, levando os braços para trás.\nRebata estendendo quadris, joelhos e tornozelos para saltar o mais alto possível, braços para frente e para cima.\nAterrisse sobre a caixa com os joelhos flexionados, absorvendo o impacto; desça saltando ou, de preferência, um pé por vez.',
  'Front Cable Raise':
    'Selecione a carga em uma polia baixa e segure com a mão esquerda o acessório individual preso a ela.\nDe costas para a polia, deixe o braço estendido para baixo com o acessório à frente das coxas e a palma voltada para elas: posição inicial.\nSem balançar o tronco, suba o braço esquerdo à frente com cotovelo levemente flexionado e palma sempre para baixo, até um pouco acima da paralela ao chão; expire e segure 1 segundo.\nAo inspirar, abaixe o braço lentamente até a posição inicial.\nComplete as repetições e troque para o braço direito.',
  'Front Cone Hops (or hurdle hops)':
    'Monte uma fileira de cones ou outras barreiras pequenas, a alguns pés de distância um do outro.\nFique diante do primeiro cone com os pés na largura dos ombros: posição inicial.\nSalte com os dois pés sobre o primeiro cone, balançando os braços.\nAbsorva a aterrissagem dobrando os joelhos e rebata para saltar o próximo cone.\nContinue até saltar sobre todos os cones.',
  'Front Dumbbell Raise':
    'Pegue um par de halteres, tronco reto, halteres à frente das coxas com palmas voltadas para elas: posição inicial.\nSem balançar o tronco, suba o halter esquerdo à frente com cotovelo levemente flexionado e palma para baixo, até um pouco acima da paralela ao chão; expire, segure 1 segundo e depois inspire.\nAbaixe esse halter até a posição inicial enquanto sobe simultaneamente o direito.\nAlterne assim até completar as repetições com cada braço.',
  'Front Incline Dumbbell Raise':
    'Sente-se em um banco inclinado entre 30 e 60 graus com um halter em cada mão; mudar o ângulo varia o trabalho muscular.\nEstenda os braços à frente, palmas para baixo, halteres a 1 polegada acima das coxas: posição inicial.\nSuba lentamente os halteres até um pouco acima dos ombros com os cotovelos travados; contraia 1 segundo e expire, cabeça apoiada no banco e pés no chão.\nAbaixe os braços até a posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Front Leg Raises':
    'Fique em pé ao lado de uma cadeira ou outro apoio, segurando-se com uma mão.\nBalance a perna para a frente reta, depois para trás o quanto sua flexibilidade permitir. Repita 5 a 10 vezes e troque de perna.',
  'Front Plate Raise':
    'Em pé e com as costas retas, segure uma anilha com as duas mãos nas posições de 3 e 9 horas, palmas voltadas uma para a outra, braços estendidos e travados com flexão leve, anilha baixa perto da cintura: posição fixa.\nLevante a anilha lentamente ao expirar até um pouco acima dos ombros; mantenha 1 segundo sem balançar o peso, dobrar os cotovelos ou mover o tronco.\nAo inspirar, abaixe lentamente a anilha até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Front Raise And Pullover':
    'Deite-se em um banco reto segurando uma barra com pegada pronada, mãos a cerca de 15 polegadas de distância.\nColoque a barra sobre a parte alta das coxas com os braços estendidos e travados, flexão leve nos cotovelos: posição inicial.\nAo inspirar, suba o peso em semicírculo (braços retos, cerca de 180 graus) até a barra ficar acima da cabeça, braços paralelos ao chão e palmas para o teto.\nRetorne a barra à posição inicial invertendo o movimento ao expirar.\nRepita pelo número de repetições recomendado.',
  'Front Squat (Clean Grip)':
    'Posicione a barra em um rack um pouco abaixo do nível dos ombros; apoie-a nos deltoides, pressionando as clavículas e tocando a garganta, com pegada de clean, tocando-a só com os dedos.\nRetire a barra do rack empurrando com as pernas e endireitando o tronco; pés na largura dos ombros, pontas um pouco para fora, cabeça e cotovelos elevados: posição inicial.\nFlexione os joelhos sentando entre as pernas até os posteriores de coxa tocarem as panturrilhas, mantendo os joelhos alinhados com os pés usando os abdutores.\nSuba a barra ao expirar, empurrando o chão com o calcanhar ou o meio do pé, esticando as pernas até a posição inicial.',
  'Front Squats With Two Kettlebells':
    'Faça o clean de dois kettlebells até os ombros, estendendo pernas e quadris enquanto puxa e gira os punhos.\nOlhando sempre para a frente, agache o mais baixo possível e pause embaixo, empurrando os joelhos para fora, tronco ereto, cabeça e peito erguidos.\nSuba empurrando com os calcanhares e repita.',
  'Front Two-Dumbbell Raise':
    'Pegue um par de halteres, tronco reto, halteres à frente das coxas com palmas voltadas para elas: posição inicial.\nSem balançar o tronco, suba os dois halteres à frente com cotovelos levemente flexionados e palmas sempre para baixo, até um pouco acima da paralela ao chão; expire e segure 1 segundo.\nAo inspirar, abaixe lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Full Range-Of-Motion Lat Pulldown':
    'Em pé ou sentado em um banco alto, segure dois estribos com pegada cruzada (palmas para frente) presos às polias altas.\nCom o peito elevado e leve arco lombar, puxe as alças para baixo em arco, girando as mãos para que na posição baixa as palmas fiquem voltadas uma para a outra em vez de para a frente; retorne lentamente e repita.',
  'Gironda Sternum Chins':
    'Segure a barra fixa com pegada supinada na largura dos ombros.\nPendure-se com os braços estendidos, peito estufado e inclinado para trás (ficará assim todo o movimento): posição inicial.\nPuxe-se em direção à barra com a coluna arqueada e a cabeça inclinada para trás, o mais longe possível da barra, expirando; no topo, quadris e pernas ficam a cerca de 45 graus do chão.\nContinue puxando até a clavícula passar da barra e o esterno tocá-la; mantenha 1 segundo (a cabeça fica paralela ao chão).\nVolte lentamente à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Glute Ham Raise':
    'Ajuste o equipamento ao corpo: pés contra a plataforma entre os rolos, deitado de bruços, joelhos logo atrás do apoio.\nPela parte inferior, com as costas arqueadas, flexione os joelhos empurrando os dedos dos pés contra a plataforma; mantenha o tronco reto até ficar ereto.\nRetorne à posição inicial controlando a descida.',
  'Glute Kickback':
    'Ajoelhe-se com os braços na largura dos ombros, perpendiculares ao tronco; joelhos em ângulo de 90° entre posterior e panturrilha.\nExpire e suba a perna direita até alinhar a coxa com as costas sem perder o ângulo de 90°; contraia o glúteo por 1 segundo no topo.\nInspire e volte à posição inicial; repita com a perna esquerda.\nAlterne as pernas até completar todas as repetições.',
  'Goblet Squat':
    'Fique em pé segurando um kettlebell leve pelas alças, perto do peito.\nAgache entre as pernas até os posteriores de coxa tocarem as panturrilhas; peito e cabeça erguidos, costas retas.\nNa posição baixa, empurre os joelhos para fora com os cotovelos; suba e repita 10 a 20 vezes.',
  'Good Morning':
    'Apoie a barra na parte de trás dos ombros (não na nuca); escápulas unidas, joelhos levemente flexionados; afaste-se do rack.\nFlexione os quadris para trás e incline-se quase paralelo ao chão, mantendo as costas arqueadas e o pescoço alinhado.\nEstenda os quadris com glúteos e posteriores de coxa até voltar à posição inicial.',
  'Good Morning off Pins':
    'Apoie a barra na parte de trás dos ombros com o rack na altura do estômago; incline-se quase paralelo ao chão, costas arqueadas e joelhos semiflexionados.\nEstenda os quadris com glúteos e posteriores de coxa até ficar em pé; abaixe lentamente o peso de volta aos pinos.',
  'Gorilla Chin/Crunch':
    'Pendure-se na barra com pegada supinada um pouco mais aberta que os ombros.\nDobre os joelhos a 90°, panturrilhas paralelas ao chão e coxas perpendiculares a ele.\nExpire, suba o corpo e faça um crunch levando os joelhos ao peito, parando quando o nariz chegar à barra.\nInspire lentamente enquanto retorna à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Groin and Back Stretch':
    'Sente-se no chão com os joelhos dobrados e os pés juntos.\nEntrelace os dedos atrás da cabeça; esta é sua posição inicial.\nEnrole o tronco levando os cotovelos às coxas; pause e volte com a cabeça erguida, costas retas. Repita 10 a 20 vezes.',
  Groiners:
    'Comece na posição de flexão de braço no chão.\nSalte com os dois pés para a frente aterrissando junto às mãos, cabeça erguida.\nVolte à posição inicial e repita imediatamente, de 10 a 20 vezes.',
  'Hack Squat':
    'Apoie as costas no encosto da máquina e encaixe os ombros sob as almofadas.\nPosicione os pés na plataforma na largura dos ombros, pontas levemente para fora; costas sempre apoiadas, cabeça erguida.\nSegure as alças laterais e destrave as barras de segurança girando as alças de frontal para diagonal.\nEstique as pernas sem travar os joelhos; esta é sua posição inicial (base média dos pés).\nDesça dobrando os joelhos, cabeça erguida e costas apoiadas, até o ângulo coxa-panturrilha ficar pouco menor que 90°; inspire. Os joelhos não devem passar da ponta dos pés.\nExpire e suba empurrando principalmente com o calcanhar, esticando as pernas até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hammer Curls':
    'Fique em pé com um halter em cada mão, braços estendidos e cotovelos junto ao tronco.\nPalmas voltadas para o tronco; esta é sua posição inicial.\nExpire e suba o peso contraindo o bíceps sem mover o braço superior, até o halter chegar ao ombro; aperte por 1 segundo.\nInspire e desça lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hammer Grip Incline DB Bench Press':
    'Deite-se em um banco inclinado com um halter em cada mão sobre as coxas, palmas uma de frente para a outra.\nUse as coxas para ajudar a subir os halteres, um braço por vez, até a largura dos ombros.\nCom pegada neutra, abra os cotovelos alinhados com os ombros, formando 90° entre braço e antebraço; esta é sua posição inicial.\nInspire e abaixe os halteres lentamente para os lados do corpo, com controle total.\nExpire e empurre os halteres para cima com o peitoral; trave os braços, segure 1 segundo e desça o dobro mais lento.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, apoie os halteres nas coxas e depois no chão.',
  'Hamstring Stretch':
    'Deite-se de costas com uma perna estendida a 90° de quadril; a outra perna reta no chão.\nPasse um cinto, faixa ou corda pela frente do pé; esta é sua posição inicial.\nPuxe o cinto para tensionar panturrilha e posterior de coxa; mantenha 10 a 30 segundos e repita com a outra perna.',
  'Hamstring-SMR':
    'Sentado, apoie as pernas sobre um rolo de espuma sob as coxas; mãos ao lado ou atrás para sustentar o peso.\nLevante os quadris com as mãos e transfira o peso para uma perna sobre o rolo; relaxe o posterior de coxa dessa perna.\nRole desde abaixo do quadril até acima do joelho, pausando 10 a 30 segundos nos pontos de tensão; repita com a outra perna.',
  'Handstand Push-Ups':
    'Com as costas para a parede, incline-se e coloque as duas mãos no chão na largura dos ombros.\nImpulsione-se contra a parede com os braços retos, corpo invertido e bem estendido; peça ajuda na primeira vez e olhe para a parede.\nInspire e desça lentamente até a cabeça quase tocar o chão; vá devagar para evitar lesões.\nExpire e empurre-se para cima lentamente até os cotovelos quase travarem.\nRepita pelo número de repetições recomendado.',
  'Hang Clean':
    'Segure a barra na largura dos ombros (pronada ou em gancho), pendurada na altura do meio da coxa, costas retas e levemente inclinadas.\nEstenda com força quadris, joelhos e tornozelos para impulsionar o peso para cima, encolhendo os ombros às orelhas.\nRecupere-se empurrando com os calcanhares, tronco ereto e cotovelos elevados, até ficar em pé.',
  'Hang Clean - Below the Knees':
    'Segure a barra na largura dos ombros (pronada ou em gancho), pendurada logo abaixo dos joelhos, costas retas e levemente inclinadas.\nEstenda com força quadris, joelhos e tornozelos; na extensão completa, encolha os ombros e flexione os cotovelos para cima e para fora.\nNo pico da extensão, puxe-se com força para baixo girando os cotovelos sob a barra; receba-a em agachamento frontal sobre os ombros, tocando levemente a garganta.\nRecupere-se empurrando com os calcanhares, tronco ereto e cotovelos elevados, até ficar em pé.',
  'Hang Snatch':
    'Segure a barra com pegada aberta (pronada ou em gancho); pés sob os quadris e voltados para fora, joelhos levemente flexionados, tronco inclinado e barra na altura dos quadris.\nEstenda com força pernas e quadris; no pico, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nPuxe-se com força sob a barra enquanto a eleva acima da cabeça, movendo os pés para a recepção; receba-a baixo com os braços estendidos para cima.\nFique em pé com o peso acima da cabeça e depois devolva-o ao chão com controle.',
  'Hang Snatch - Below Knees':
    'Segure a barra com pegada aberta (pronada ou em gancho); pés sob os quadris e voltados para fora, joelhos levemente flexionados, tronco inclinado e barra logo abaixo dos joelhos.\nEstenda com força pernas e quadris; no pico, encolha os ombros e deixe os cotovelos flexionarem para os lados.\nPuxe-se com força sob a barra enquanto a eleva acima da cabeça, movendo os pés para a recepção; receba-a baixo com os braços estendidos para cima.\nFique em pé com o peso acima da cabeça e depois devolva-o ao chão com controle.',
  'Hanging Bar Good Morning':
    'Coloque uma barra em um rack na altura do estômago e suspenda-a com correntes ou tiras.\nIncline-se sob a barra e apoie-a na parte de trás dos ombros (não no trapézio); quase paralelo ao chão, costas arqueadas, escápulas unidas, joelhos levemente flexionados.\nEstenda os quadris com glúteos e posteriores de coxa até ficar em pé com o peso.\nAbaixe lentamente o peso até a posição inicial, sustentado pelas correntes.',
  'Hanging Leg Raise':
    'Pendure-se na barra com os braços estendidos acima, pegada aberta ou média, pernas retas e pelve levemente retrovertida.\nExpire e suba as pernas até formar 90° com o tronco; aperte por 1 segundo.\nInspire e volte lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hanging Pike':
    'Pendure-se na barra com pernas e pés juntos, pegada pronada um pouco mais aberta que os ombros; use munhequeiras se precisar.\nDobre os joelhos a 90° e leve as coxas para a frente: panturrilhas perpendiculares ao chão, coxas paralelas; esta é sua posição inicial.\nExpire e suba as pernas até quase tocar a barra com as canelas, esticando-as o máximo possível.\nAbaixe as pernas o mais lentamente possível até a posição inicial, sem balançar nem usar impulso.\nRepita pelo número de repetições recomendado.',
  'Heaving Snatch Balance':
    'Segure um peso leve na parte de trás dos ombros, pés um pouco mais afastados que os quadris e voltados para fora, como em um agachamento.\nFlexione levemente os joelhos, rebata para cima para descarregar a barra e impulsione-se sob ela, elevando-a acima da cabeça ao descer em agachamento completo.\nFique em pé.',
  'Heavy Bag Thrust':
    'Fique ereto junto a um saco de pancada pesado, pés alternados e afastados; mão no saco na altura do peito.\nGire pela cintura e empurre o saco para a frente com força e rapidez, afastando-o do corpo.\nReceba o saco ao voltar, invertendo esses passos.',
  'High Cable Curls':
    'Fique entre duas polias altas, uma alça em cada mão, braços superiores paralelos ao chão e palmas voltadas para você.\nExpire e flexione os braços levando as alças às orelhas, sem mover o braço superior; aperte o bíceps por 1 segundo.\nVolte lentamente os braços à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Hip Circles (prone)':
    'Fique de quatro apoios (mãos e joelhos); levante um joelho dobrado do chão mantendo boa postura.\nCom o joelho dobrado, gire o fêmur em um arco amplo, como desenhando um círculo.\nFaça lentamente por várias repetições e repita do outro lado.',
  'Hip Extension with Bands':
    'Prenda uma ponta da faixa na parte baixa de um poste e a outra em um tornozelo.\nDe frente para a fixação da faixa, segure-se em algo estável para se equilibrar.\nCom cabeça e peito erguidos, leve a perna com resistência para trás o mais longe possível, joelho reto.\nVolte a perna à posição inicial.',
  'Hip Flexion with Band':
    'Prenda uma ponta da faixa na parte baixa de um poste e a outra em um tornozelo.\nFique de costas para o ponto de fixação da faixa.\nCom cabeça e peito erguidos, suba o joelho até 90° e faça uma pausa.\nVolte a perna à posição inicial.',
  'Hip Lift with Band':
    'Escolha uma faixa, prenda-a nos dois lados do rack e deite-se no centro; use halteres pesados se o rack não tiver pinos, sem que se movam.\nAjuste sua posição com a faixa sobre os quadris, joelhos dobrados e pés totalmente no chão; mãos no chão ou segurando a faixa.\nCom os ombros no chão, empurre com os calcanhares e eleve os quadris contra a faixa o mais alto que puder.\nPause no topo e volte à posição inicial.',
  'Hug A Ball':
    'Sente-se no chão.\nPosicione uma bola de exercício entre as pernas e abaixe os quadris em direção ao chão.\nAbrace a bola com os braços para se sustentar; pés apoiados, joelhos sobre os tornozelos, boa pegada para ela não rolar.',
  'Hug Knees To Chest':
    'Deite-se de costas e leve os dois joelhos ao peito.\nSegure os joelhos com os braços por baixo, não por cima, para não pressionar a articulação.\nPuxe lentamente os joelhos em direção aos ombros; isso também alonga os glúteos.',
  'Hurdle Hops':
    'Monte uma fileira de barreiras ou obstáculos pequenos, a poucos passos de distância uma da outra.\nFique diante da primeira barreira com os pés na largura dos ombros; esta é sua posição inicial.\nSalte com os dois pés sobre a primeira barreira, balançando os braços.\nAbsorva a aterrissagem dobrando os joelhos e rebata para a próxima barreira, até saltar todas.',
  'Hyperextensions (Back Extensions)':
    'Deite-se de bruços no banco de hiperextensão com os tornozelos fixos sob os apoios.\nAjuste o apoio superior sob a parte de cima das coxas, com espaço para flexionar o quadril.\nCruze os braços à frente ou atrás da cabeça; segure uma anilha à frente para mais resistência.\nIncline-se a partir do quadril inspirando, costas retas, até alongar os posteriores sem arredondar as costas.\nSuba o tronco lentamente à posição inicial inspirando, sem arquear ou balançar as costas.\nRepita o número de repetições recomendado.',
  'Hyperextensions With No Hyperextension Bench':
    'Com alguém segurando suas pernas, deslize o quadril fora do banco reto, tronco pendurado para o chão.\nCruze os braços à frente ou atrás da cabeça; segure uma anilha à frente para mais resistência.\nIncline-se a partir do quadril inspirando, costas retas, até quase tocar o chão, sem arredondar as costas.\nSuba o tronco lentamente à posição inicial expirando, sem arquear ou balançar as costas.\nRepita o número de repetições recomendado.',
  'IT Band and Glute Stretch':
    'Deitado, passe uma faixa em um pé e cruze essa perna estendida para o lado oposto do corpo.\nPé fora do chão, puxe a faixa levando os dedos para cima; segure 10-20 seg e repita do outro lado.',
  'Iliotibial Tract-SMR':
    'De lado, apoie a perna de baixo sobre um rolo entre o quadril e o joelho; cruze a outra perna à frente.\nApoie nessa perna todo o peso que tolerar, sem que toque o chão, e relaxe o músculo que está alongando.\nRole do quadril ao joelho sobre o rolo, pausando 10-30 seg nos pontos de tensão, e troque de perna.',
  Inchworm:
    'Em pé, pés juntos, pernas retas: incline-se e apoie as mãos no chão à sua frente.\nCaminhe lentamente com as mãos para a frente, alternando, flexionando só o quadril, pernas retas.\nContinue até ficar paralelo ao chão em posição de flexão de braço.\nCom as mãos fixas, dê passos curtos e lentos com os pés, avançando poucos centímetros por vez.\nContinue andando até levar os pés junto às mãos, mantendo as pernas retas.',
  'Incline Barbell Triceps Extension':
    'Segure a barra com pegada pronada, mãos um pouco mais próximas que a largura dos ombros.\nDeite-se em um banco inclinado entre 45 e 75 graus.\nEstenda os braços acima da cabeça com a barra, cotovelos para dentro e alinhados com o tronco.\nAbaixe a barra em semicírculo atrás da cabeça inspirando até tocar os bíceps; mova só os antebraços.\nVolte à posição inicial expirando e contraindo os tríceps; segure 1 segundo.\nRepita o número de repetições recomendado.',
  'Incline Bench Pull':
    'Pegue um halter em cada mão e deite-se de bruços em um banco inclinado a 30 graus.\nDeixe os braços pendurados ao lado do corpo, totalmente estendidos, apontando para o chão.\nGire os punhos até as mãos ficarem com pegada pronada (palmas para baixo).\nAbra os cotovelos para fora; esta é a sua posição inicial.\nPuxe os halteres para cima expirando, como um supino invertido, até formar um "T"; segure 1 seg.\nVolte lentamente à posição inicial inspirando.\nRepita o número de repetições recomendado.',
  'Incline Cable Chest Press':
    'Sente-se segurando as manoplas, braços a 45 graus do corpo, peito e cabeça erguidos, cotovelos a 90 graus.\nEstenda os cotovelos empurrando as manoplas à frente, com as escápulas retraídas.\nPause com os braços estendidos e volte à posição inicial sem perder a tensão nos cabos.',
  'Incline Cable Flye':
    'Ajuste as polias no nível mais baixo, na altura do chão, abaixo do seu tronco.\nColoque um banco inclinado a 45 graus entre as polias, escolha a carga e segure uma manopla em cada mão.\nDeite-se com uma manopla em cada mão e junte as mãos com os braços estendidos à frente do rosto.\nCotovelos flexionados, abra os braços em arco inspirando até alongar o peitoral; só o ombro se move.\nVolte à posição inicial expirando e contraindo o peitoral; segure 1 seg usando o mesmo arco da descida.\nRepita o movimento pelo número de repetições prescrito.',
  'Incline Dumbbell Bench With Palms Facing In':
    'Deite-se em um banco inclinado com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nCom ajuda das coxas, suba os halteres um de cada vez até a altura dos ombros.\nNa largura dos ombros, pegada neutra, cotovelos para fora alinhados com os ombros e flexionados a 90 graus.\nAbaixe os halteres lentamente para as laterais inspirando, com controle total.\nExpirando, empurre os halteres para cima com o peito, trave os braços 1 segundo e desça o dobro mais lento.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, apoie os halteres nas coxas e depois no chão; é a forma mais segura de soltá-los.',
  'Incline Dumbbell Curl':
    'Sente-se no banco inclinado com os braços estendidos, cotovelos próximos ao tronco e palmas para a frente.\nExpirando, suba os halteres com o bíceps até a altura dos ombros, movendo só os antebraços; segure 1 seg.\nDesça os halteres lentamente à posição inicial inspirando.\nRepita o número de repetições recomendado.',
  'Incline Dumbbell Flyes':
    'Segure um halter em cada mão e deite-se em um banco inclinado a no máximo 30 graus.\nEstenda os braços acima de você com uma leve flexão nos cotovelos.\nGire os punhos com as palmas voltadas para você e os mínimos juntos; esta é a sua posição inicial.\nInspirando, abaixe os braços estendidos para os lados girando os punhos até as palmas para o teto.\nExpirando, suba os halteres invertendo o giro até juntar os mínimos, movendo só ombro e punho.\nRepita o número de repetições recomendado.',
  'Incline Dumbbell Flyes - With A Twist':
    'Segure um halter em cada mão e deite-se em um banco inclinado a no máximo 30 graus.\nEstenda os braços acima de você com uma leve flexão nos cotovelos.\nGire os punhos com as palmas voltadas para você e os mínimos juntos; esta é a sua posição inicial.\nInspirando, abaixe os braços estendidos para os lados girando os punhos até as palmas para o teto.\nExpirando, suba os halteres invertendo o giro até juntar os mínimos, movendo só ombro e punho.\nRepita o número de repetições recomendado.',
  'Incline Dumbbell Press':
    'Deite-se no banco inclinado com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nCom ajuda das coxas, suba os halteres um de cada vez até a altura dos ombros.\nNa largura dos ombros, gire os punhos com as palmas para a frente; esta é a sua posição inicial.\nCom controle total, expire e empurre os halteres para cima com o peito.\nTrave os braços no alto por 1 segundo e abaixe o peso lentamente, o dobro mais lento que a subida.\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, apoie os halteres nas coxas e depois no chão; é a forma mais segura de soltá-los.',
  'Incline Hammer Curls':
    'Sente-se apoiado no encosto do banco inclinado, pés juntos, halteres pendurados com pegada neutra.\nInicie o movimento flexionando os cotovelos, mantendo imóvel a parte superior do braço.\nContinue até o alto do movimento, pause e volte lentamente à posição inicial.',
  'Incline Inner Biceps Curl':
    'Segure um halter em cada mão e deite-se em um banco inclinado.\nDeixe os halteres pendurados com os braços estendidos e as palmas para fora; esta é a sua posição inicial.\nExpirando, suba os halteres para fora e para cima até a altura dos ombros, como uma pose de duplo bíceps.\nContraia por 1 segundo no alto, inspire e desça os halteres pelo mesmo caminho da subida.\nRepita o número de repetições recomendado.',
  'Incline Push-Up':
    'Em pé de frente para um banco firme, apoie as mãos na borda, um pouco mais afastadas que os ombros.\nPés atrás na ponta, corpo reto, braços perpendiculares; abaixe o peito até a borda flexionando os braços.\nEmpurre o corpo para cima até estender os braços. Repita.',
  'Incline Push-Up Close-Grip':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente, em altura adequada.\nColoque as mãos juntas, uma ao lado da outra, sobre a barra.\nPés atrás, afastados da barra, corpo e braços retos; esta é a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Incline Push-Up Depth Jump':
    'Você precisa de uma caixa de cerca de 30 cm de altura e dois colchonetes grossos ou steps de aeróbica.\nColoque os steps fora dos ombros, pés sobre a caixa, mãos dentro dos steps, em flexão inclinada.\nDesça flexionando os cotovelos, impulsione-se e aterrisse as mãos nos steps amortecendo com os cotovelos.\nRepita o movimento para voltar à posição inicial.',
  'Incline Push-Up Medium':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente, em altura adequada.\nColoque as mãos sobre a barra, afastadas aproximadamente na largura dos ombros.\nPés atrás, afastados da barra, corpo e braços retos; esta é a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Incline Push-Up Reverse Grip':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente, em altura adequada.\nColoque as mãos sobre a barra com as palmas para cima, na largura dos ombros.\nPés atrás, afastados da barra, corpo e braços retos; esta é a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Incline Push-Up Wide':
    'Fique em pé de frente para a barra de um Smith ou uma plataforma elevada resistente, em altura adequada.\nColoque as mãos sobre a barra, mais afastadas que a largura dos ombros.\nPés atrás, corpo e braços retos e perpendiculares ao corpo; esta é a sua posição inicial.\nMantendo o corpo reto, abaixe o peito até a barra flexionando os braços.\nVolte à posição inicial estendendo os cotovelos e empurrando-se para cima.',
  'Intermediate Groin Stretch':
    'De costas, pernas estendidas, passe uma faixa por um pé e leve essa perna ao lado o mais longe possível.\nPuxe suavemente a faixa para tensionar virilha e posteriores de coxa; segure 10-20 seg e troque de lado.',
  'Intermediate Hip Flexor and Quad Stretch':
    'Deite-se de bruços no chão, com uma corda, cinto ou faixa em volta de um dos pés.\nFlexione o joelho, estenda o quadril, puxe a faixa e tensione quadril/quadríceps 10-20 seg; troque de perna.',
  'Internal Rotation with Band':
    'Fixe a faixa em um poste na altura do cotovelo; fique com o lado direito voltado para ela, a dois passos.\nSegure a faixa com a mão direita, cotovelo junto ao corpo; pode usar uma toalha ou rolo sob o cotovelo.\nCom o braço fixo, cotovelo a 90 graus e mão estendida para longe do tronco; esta é a sua posição inicial.\nGire o braço para dentro, como uma pancada de direita, mantendo o cotovelo no lugar.\nContinue o mais longe que conseguir, pause e volte à posição inicial.',
  'Inverted Row':
    'Posicione uma barra em um rack na altura da cintura, ou use um Smith.\nPendure-se na barra com pegada larga, corpo reto, calcanhares no chão, braços estendidos.\nFlexione os cotovelos puxando o peito até a barra, retraindo as escápulas.\nFaça uma pausa no alto do movimento e volte à posição inicial.\nRepita o número de repetições desejado.',
  'Inverted Row with Straps':
    'Pendure fitas em um rack, segure-as de costas, corpo reto, calcanhares no chão, braços estendidos.\nFlexione os cotovelos puxando o peito até as mãos, retraindo as escápulas.\nFaça uma pausa no alto do movimento e volte à posição inicial.\nRepita o número de repetições desejado.',
  'Iron Crosses (stretch)':
    'De bruços, braços estendidos para os lados e palmas no chão; esta é a sua posição inicial.\nFlexione um joelho e cruze essa perna por trás do corpo, tocando o chão perto da mão oposta.\nVolte rápido à posição inicial e repita com a outra perna; alterne por 10-20 repetições.',
  'Isometric Chest Squeezes':
    'Sentado ou em pé, flexione os braços a 90 graus e junte as palmas à frente do peito, dedos para a frente.\nEmpurre as mãos uma contra a outra contraindo o peito, com tensão crescente e respiração normal.\nSegure pelo número de segundos recomendado.\nAgora solte a tensão lentamente.\nDescanse pelo tempo recomendado e repita.',
  'Isometric Neck Exercise - Front And Back':
    'Com cabeça e pescoço em posição neutra, olhando para a frente, coloque as duas mãos na frente da cabeça.\nEmpurre suave para a frente contraindo o pescoço, resistindo ao movimento, com tensão crescente.\nSegure pelo número de segundos recomendado.\nAgora solte a tensão lentamente.\nDescanse o tempo recomendado e repita com as mãos na parte de trás da cabeça.',
  'Isometric Neck Exercise - Sides':
    'Coloque a cabeça e o pescoço em posição neutra, olhando para a frente, e ponha a mão esquerda no lado esquerdo da cabeça.\nEmpurre suave para a esquerda, contraia o pescoço sem mover a cabeça; aumente a tensão gradual e respire normal.\nSegure a contração pelo número de segundos recomendado.\nSolte a tensão lentamente.\nDescanse pelo tempo recomendado e repita com a mão direita no lado direito da cabeça.',
  'Isometric Wipers':
    'Assuma a posição de flexão de braço: mãos um pouco mais largas que os ombros, pontas dos pés no chão, corpo reto.\nDesloque o peso do corpo para um lado, flexionando esse cotovelo enquanto abaixa o corpo.\nEstenda esse braço para subir e depois desça para o outro lado.\nRepita o número de repetições desejado.',
  'JM Press':
    'Deite-se em banco reto, barra com pegada fechada e braços estendidos, cotovelos para dentro, barra sobre a parte superior do peito.\nAbaixe a barra como em uma extensão de tríceps deitado, inspirando; na metade, role a barra 2,5 cm para trás até os braços ficarem perpendiculares ao tronco, sem mudar a flexão do cotovelo.\nExpire e empurre a barra para cima com os tríceps, como em um supino de pegada fechada.\nVolte à posição inicial.\nRepita o número de repetições recomendado.',
  'Jackknife Sit-Up':
    'Deite-se de costas, braços estendidos atrás acima da cabeça e pernas estendidas.\nExpire e suba pernas e braços ao mesmo tempo até a posição de canivete: pernas a 35-45 graus do chão, braços paralelos a elas, tronco fora do chão.\nInspire e abaixe braços e pernas à posição inicial.\nRepita o número de repetições recomendado.',
  'Janda Sit-Up':
    'Deite-se em posição básica de abdominal: joelhos a 90 graus, pés apoiados no chão, braços cruzados sobre o peito ou ao lado do corpo.\nContraia glúteos e posteriores de coxa, inspire e suba lento (3 a 6 segundos) expirando; contrair esses músculos inativa os flexores do quadril por inibição recíproca.\nInspire e volte lenta e controladamente à posição inicial.\nRepita o número de repetições recomendado.',
  'Jefferson Squats':
    'Coloque uma barra no chão.\nFique em pé sobre o meio da barra, alinhado com ela.\nAgache com as costas retas e segure a frente da barra com a mão direita, palma para dentro (pegada neutra) voltada para a esquerda.\nSegure a parte de trás da barra com a mão esquerda, pegada neutra voltada para a direita; mantenha o tronco centrado e a mesma distância das duas mãos.\nFique em pé com o peso, pés na largura dos ombros e pontas levemente para fora.\nInspire e agache com as costas retas e verticais até as coxas ficarem paralelas ao chão, sem deixar os joelhos passarem da ponta dos pés.\nEmpurre com os pés até a posição inicial; os braços só servem como ganchos, com leve flexão, faça o trabalho com as coxas.',
  'Jerk Balance':
    'Coloque a barra na posição de jerk sobre os ombros, ombros para a frente, tronco ereto, pés em tesoura leve (este exercício corrige o deslocamento para trás no jerk).\nFlexione os joelhos com o tronco vertical e impulsione-se com força para cima, usando o impulso das pernas, não os braços.\nMantenha o pé de trás fixo e use-o para avançar até uma tesoura completa enquanto faz o jerk; recupere-se em pé com o peso acima da cabeça.',
  'Jerk Dip Squat':
    'Coloque a barra na posição de jerk sobre os ombros, ombros para a frente formando uma prateleira, barra tocando levemente a garganta, pés sob o quadril e pontas para fora (fortalece a fase de dip do jerk).\nCom o tronco vertical, desça flexionando os joelhos para a frente sem levar o quadril para trás, sem flexionar demais; impulsione-se com força pelos pés de volta à posição inicial.',
  'Jogging, Treadmill':
    'Suba na esteira e escolha modo manual ou um programa; informe idade e peso para estimar calorias e ajuste a inclinação para mudar a intensidade.\nTrotar na esteira tem menos impacto que ao ar livre (uma pessoa de 150 lb queima quase 250 calorias em 30 minutos de trote); mantenha boa postura e segure nas barras só para descer ou checar a frequência cardíaca.',
  'Keg Load':
    'Coloque os barris a 30-50 pés da plataforma de carga.\nSegure a alça mais próxima do primeiro barril, incline-o de lado para agarrar a borda oposta da base, e levante-o até o peito.\nCom pegada firme (sem apoiar no ombro), mova-se rápido até a plataforma e carregue-o estendendo quadril, joelhos e tornozelos para levantá-lo o mais alto possível.\nVolte à posição inicial para pegar o próximo barril e repita até completar a prova.',
  'Kettlebell Arnold Press':
    'Faça um clean levando o kettlebell ao ombro, estendendo pernas e quadril, palma voltada para dentro.\nOlhando para a frente, empurre o kettlebell para cima girando o punho até a palma ficar voltada para a frente no topo.\nVolte o kettlebell à posição inicial, com a palma voltada para dentro.',
  'Kettlebell Dead Clean':
    'Coloque o kettlebell entre os pés, leve o quadril para trás e olhe para a frente.\nFaça um clean levando o kettlebell ao ombro, estendendo pernas e quadril enquanto gira o punho.\nAbaixe o kettlebell com as costas retas e quadril para trás, mantendo os posteriores de coxa carregados.',
  'Kettlebell Figure 8':
    'Coloque o kettlebell entre as pernas com base mais larga que os ombros, quadril para trás e costas retas.\nPasse o kettlebell para a outra mão entre as pernas, recebendo-o por trás; repita várias vezes nas duas direções.',
  'Kettlebell Halo':
    'Fique em pé com os pés na largura do quadril, kettlebell de cabeça para baixo pelas alças perto do peito, abdômen contraído e glúteos apertados, costelas para baixo.\nCom os cotovelos próximos à cabeça, leve o kettlebell para cima ao lado de uma orelha e contorne a parte de trás da cabeça.\nContinue o círculo pela orelha oposta e volte à frente do peito, mantendo o kettlebell perto do corpo.\nComplete o número indicado de círculos em uma direção e depois repita a mesma quantidade na direção oposta.\nMova-se devagar, sem mover cabeça, quadril ou lombar; se a lombar arquear ou o kettlebell se afastar da cabeça, use menos peso.',
  'Kettlebell Halo with Overhead Extension':
    'Fique em pé com os pés na largura do quadril, segure o kettlebell de cabeça para baixo pelas alças perto do peito, abdômen contraído e glúteos apertados para manter as costelas para baixo.\nCom os cotovelos próximos à cabeça, leve o kettlebell para cima ao lado de uma orelha e contorne a cabeça até deixá-lo atrás; faça uma pausa.\nEstenda os cotovelos para empurrar o kettlebell acima da cabeça até os braços ficarem retos, com a parte superior do braço junto à cabeça.\nFlexione os cotovelos e abaixe o kettlebell com controle até a posição de pausa atrás da cabeça.\nContinue o círculo pela orelha oposta e volte à frente do peito para completar a repetição.\nAlterne a direção a cada repetição, sem mover cabeça, quadril ou lombar; se a lombar arquear ou você se inclinar para trás ao chegar acima da cabeça, use menos peso ou separe o halo da extensão.',
  'Kettlebell Hang Clean':
    'Coloque o kettlebell entre os pés, leve o quadril para trás e olhe para a frente.\nFaça um clean levando o kettlebell ao ombro, estendendo pernas e quadril enquanto gira o punho.\nAbaixe o kettlebell até a posição pendurada entre as pernas, posteriores de coxa carregados e cabeça erguida.',
  'Kettlebell One-Legged Deadlift':
    'Segure o kettlebell com uma mão e fique apoiado na perna do mesmo lado.\nCom esse joelho levemente flexionado, faça um levantamento terra com pernas rígidas, flexionando o quadril e estendendo a perna livre atrás para o equilíbrio.\nAbaixe o kettlebell até o corpo ficar paralelo ao chão e volte à posição ereta.',
  'Kettlebell Overhead Triceps Extension':
    'Fique em pé com os pés na largura do quadril, segure o kettlebell pelas alças com as duas mãos e empurre-o acima da cabeça com os braços estendidos, corpo pendurado atrás das mãos.\nContraia os abdominais e mantenha a parte superior dos braços vertical e próxima da cabeça; esta é a sua posição inicial.\nFlexione os cotovelos e abaixe o kettlebell atrás da cabeça até onde a mobilidade do ombro permitir, sem abrir os cotovelos.\nEstenda os cotovelos para empurrar o kettlebell até a posição inicial, sem mover a parte superior dos braços.\nMantenha as costelas para baixo e evite arquear a lombar ao estender.',
  'Kettlebell Pass Between The Legs':
    'Coloque o kettlebell entre as pernas com base confortável, quadril para trás e costas retas.\nPasse o kettlebell para a outra mão entre as pernas em formato de "W"; repita várias vezes.',
  'Kettlebell Pirate Ships':
    'Com base larga, segure o kettlebell com as duas mãos pendurado na altura da cintura, braços estendidos.\nGire para um lado balançando o kettlebell até a altura da cabeça e faça uma breve pausa no alto.\nDeixe o kettlebell descer girando para o lado oposto e levante-o de novo até a altura da cabeça.\nRepita o número de repetições desejado.',
  'Kettlebell Pistol Squat':
    'Segure o kettlebell com as duas mãos pelas alças, mantenha uma perna fora do chão e agache sobre a outra.\nAgache flexionando o joelho e levando o quadril para trás, com o kettlebell à frente do corpo.\nSegure a posição baixa por um segundo e empurre pelo calcanhar, cabeça e peito erguidos.\nDesça novamente e repita.',
  'Kettlebell Seated Press':
    'Sente-se no chão e afaste as pernas de forma confortável.\nFaça um clean com um kettlebell até o ombro.\nEmpurre o kettlebell para cima e para fora até travá-lo acima da cabeça. Volte à posição inicial.',
  'Kettlebell Seesaw Press':
    'Faça um clean com dois kettlebells até os ombros.\nEmpurre um kettlebell para cima.\nAbaixe o kettlebell e empurre o outro imediatamente; faça o mesmo número de repetições nos dois lados.',
  'Kettlebell Sumo High Pull':
    'Coloque o kettlebell no chão entre os pés, base larga, quadril para trás ao máximo, joelhos flexionados, peito e cabeça erguidos.\nEstenda o quadril e os joelhos enquanto puxa o kettlebell até os ombros e eleva os cotovelos; inverta o movimento para voltar.',
  'Kettlebell Thruster':
    'Leve dois kettlebells aos ombros (clean), estendendo pernas e quadris e girando os punhos.\nAgache flexionando quadris e joelhos, quadril entre as pernas, costas retas e eretas, o mais profundo possível.\nSuba estendendo joelhos e quadris, empurrando com os calcanhares, e empurre os dois kettlebells acima da cabeça usando o impulso do agachamento.\nAo iniciar a próxima repetição, retorne os pesos aos ombros.',
  'Kettlebell Turkish Get-Up (Lunge style)':
    'Deite-se de costas, empurre o kettlebell até a posição superior estendendo o cotovelo, e flexione o joelho do mesmo lado.\nCom o braço travado, gire para o lado oposto e use o braço livre para avançar até o afundo; empurre-se com a mão livre até sentar e apoie um joelho.\nOlhando para o kettlebell, levante-se lentamente; inverta o movimento até a posição inicial e repita.',
  'Kettlebell Turkish Get-Up (Squat style)':
    'Deite-se de costas, empurre o kettlebell até a posição superior estendendo o cotovelo, e flexione o joelho do mesmo lado.\nCom o braço travado, gire para o lado oposto e use o braço livre para avançar até a posição de afundo.\nCom a mão livre, empurre-se até sentar e depois fique em pé lentamente olhando para o kettlebell; inverta o movimento até a posição inicial e repita.',
  'Kettlebell Windmill':
    'Posicione o kettlebell à frente do pé dianteiro, faça um clean ao ombro estendendo pernas e quadris e girando o punho, e empurre-o acima da cabeça estendendo o cotovelo.\nCom o braço travado, empurre o quadril na direção do kettlebell, gire os pés 45 graus, e flexione o quadril inclinando-se lentamente até tocar o chão com a mão livre, olhando para o kettlebell o tempo todo.\nFaça uma pausa de um segundo ao alcançar o chão e inverta o movimento até a posição inicial.',
  'Kipping Muscle Up':
    'Segure os anéis com pegada falsa, com a base das palmas sobre os anéis.\nComece balançando levemente as pernas para trás.\nBalance as pernas para a frente e para cima, jogue o queixo e o peito para trás e puxe-se com os dois braços; no alto, leve os anéis às axilas girando os ombros para a frente e os cotovelos para trás, pronto para a fase de paralelas.\nMantendo controle e estabilidade, estenda os cotovelos para completar o movimento.\nTenha cuidado ao descer até o chão.',
  'Knee Across The Body':
    'Deite-se com a perna direita estendida, flexione a esquerda e abaixe-a cruzando o corpo, segurando o joelho em direção ao chão com a mão direita (não precisa tocar o chão se estiver tenso).\nColoque o braço esquerdo ao seu lado e vire a cabeça para a esquerda; deixe o cóccix cair em direção ao chão enquanto o peito se estira na direção oposta para alongar a lombar. Troque de lado.',
  'Knee Circles':
    'Fique em pé com as pernas juntas e as mãos na altura da cintura.\nMova os joelhos em círculos enquanto respira normalmente.\nRepita pelo número de repetições recomendado.',
  'Knee Tuck Jump':
    'Em pé, joelhos levemente flexionados; mãos à frente, palmas para baixo e dedos juntos na altura do peito.\nDesça a quarto de agachamento e salte explosivo, levando os joelhos ao peito até tocar as palmas.\nSalte o mais alto possível subindo os joelhos; ao aterrissar, estenda as pernas e flexione os joelhos para absorver o impacto.',
  'Knee/Hip Raise On Parallel Bars':
    'No banco de elevação de pernas, apoie os antebraços nas almofadas junto ao tronco e braços a 90 graus.\nMantenha o tronco reto, lombar pressionada no encosto e pernas estendidas apontando para o chão: posição inicial.\nExpire e levante as pernas estendidas até quase a paralela ao chão; mantenha 1 segundo sem impulso ou balanço.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Kneeling Arm Drill':
    'Ajoelhado, pé esquerdo à frente; pressione o calcanhar da frente para ativar glúteos e posteriores de coxa.\nMova os braços em balanços longos tipo pêndulo; feche o ângulo como ao trotar, progredindo para corrida e sprint.\nQuando as mãos passarem pelo quadril, acelere-as para a frente o mais rápido possível no sprint.\nTroque de joelho e repita.',
  'Kneeling Cable Crunch With Alternating Oblique Twists':
    'Conecte um acessório de corda a uma polia alta e posicione um colchonete no chão à frente dela.\nSegure a corda com as duas mãos e ajoelhe-se a aproximadamente sessenta centímetros da torre.\nPosicione a corda atrás da cabeça, com as mãos junto às orelhas.\nContraia os abdominais e puxe a corda para baixo em abdominal até os cotovelos tocarem os joelhos.\nFaça uma breve pausa embaixo e suba de forma lenta e controlada até a posição inicial.\nNa metade do movimento, rotacione um dos cotovelos em direção ao joelho oposto.\nFaça uma breve pausa embaixo e suba lento e controlado até a posição inicial.\nRepita alternando: leve o outro cotovelo em direção ao joelho oposto.\nContinue essa série de movimentos até a falha.',
  'Kneeling Cable Triceps Extension':
    'Posicione um banco de lado em frente a uma polia alta.\nSegure uma barra reta acima da cabeça com as mãos afastadas cerca de 15 cm e as palmas voltadas para baixo.\nFique de costas para a máquina e ajoelhe-se.\nApoie cabeça e braços no banco, cotovelos flexionados e antebraços para a polia: posição inicial.\nCom cotovelos para dentro e perto da cabeça, empurre a barra em semicírculo até estender os braços paralelos ao chão; contraia o tríceps 1 seg.\nVolte lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Kneeling Forearm Stretch':
    'Comece ajoelhado sobre um colchonete com as palmas planas e os dedos apontando para trás, em direção aos joelhos.\nIncline-se para trás com as palmas no chão até sentir o alongamento em punhos e antebraços; mantenha 20-30 seg.',
  'Kneeling High Pulley Row':
    'Com uma corda na polia alta, ajoelhe-se a um ou dois passos e segure a corda à frente com os braços estendidos: posição inicial.\nFlexione os cotovelos e retraia os ombros, puxando a corda até o peito alto com os cotovelos para fora.\nApós uma breve pausa, volte lentamente à posição inicial.',
  'Kneeling Hip Flexor':
    'Ajoelhe-se, joelho direito à frente com a sola do pé no chão e perna esquerda atrás com o peito do pé no chão.\nDesloque o peso para a frente até sentir o alongamento no quadril; mantenha 15 seg e repita do outro lado.',
  'Kneeling Jump Squat':
    'Ajoelhado, com a barra na parte de trás dos ombros (ou só peso corporal); pode usar um rack de potência.\nSente-se para trás com o quadril até que os glúteos toquem os pés, mantendo a cabeça e o peito erguidos.\nSuba de forma explosiva com o quadril, gerando potência suficiente para aterrissar com os pés totalmente apoiados no chão.\nContinue o agachamento empurrando com os calcanhares e estendendo os joelhos até ficar em pé.',
  'Kneeling Single-Arm High Pulley Row':
    'Conecte uma manopla simples a uma polia alta e escolha a carga.\nAjoelhe-se de frente para a torre, segure o cabo com uma mão e o braço estendido: posição inicial.\nCom a palma para a frente, flexione o cotovelo e retraia a escápula puxando o peso ao tronco, girando o punho até a palma ficar voltada para você.\nApós uma breve pausa, volte à posição inicial.',
  'Kneeling Squat':
    'Ajuste a barra no rack, ajoelhe-se (use um colchonete) e apoie-a nos ombros com escápulas retraídas; retire o peso do suporte.\nCom o olhar para a frente, sente-se para trás com os glúteos até tocar as panturrilhas.\nInverta o movimento, retornando o tronco a uma posição ereta.',
  "Landmine 180's":
    'Posicione uma barra em um landmine ou fixe-a com segurança em um canto. Carregue a barra com um peso adequado.\nLevante a barra à altura dos ombros com as duas mãos e braços estendidos, em base larga: posição inicial.\nRotacione o tronco e o quadril balançando o peso para baixo de um lado, com os braços sempre estendidos.\nInverta o movimento para balançar o peso até o lado oposto.\nContinue alternando o movimento até completar a série.',
  'Landmine Linear Jammer':
    'Posicione a barra em um landmine (ou fixe-a em um canto), carregue com peso adequado e monte o acessório de manoplas.\nLevante a barra do chão, levando as manoplas aos ombros. Esta será sua posição inicial.\nEm uma postura atlética, agache flexionando o quadril e levando-o para trás, mantendo os braços flexionados.\nEstenda com força e de forma explosiva quadris, joelhos, tornozelos e cotovelos até a extensão completa, com a maior potência possível.\nRetorne à posição inicial.',
  'Lateral Bound':
    'Em meio agachamento, de frente a 90° em relação à direção do deslocamento: posição inicial.\nDeixe a perna da frente fazer um contramovimento para dentro enquanto transfere o peso para a perna de fora.\nImpulsione-se imediatamente e estenda o corpo, tentando saltar para o lado o mais longe possível.\nAo aterrissar, impulsione-se imediatamente na direção oposta, retornando à posição inicial original.\nContinue de um lado para o outro por várias repetições.',
  'Lateral Box Jump':
    'Assuma uma posição em pé confortável, com uma caixa baixa posicionada ao seu lado. Esta será sua posição inicial.\nDesça a quarto de agachamento para iniciar o reflexo de estiramento e inverta de imediato para saltar para cima e para o lado.\nSuba os joelhos o suficiente para garantir que os pés passem com boa folga sobre a caixa.\nAterrisse no centro da caixa, usando as pernas para absorver o impacto.\nSalte com cuidado para o outro lado da caixa e continue de um lado para o outro por várias repetições.',
  'Lateral Cone Hops':
    'Posicione vários cones em uma fileira, separados por alguns passos.\nFique ao lado da extremidade dos cones, de frente a 90° em relação à direção do deslocamento: posição inicial.\nFlexione os joelhos para ativar o reflexo de estiramento e inverta de imediato, saltando para cima e para o lado sobre o cone.\nUse as pernas para absorver o impacto e rebata para o próximo salto, continuando pela fileira de cones.',
  'Lateral Raise - With Bands':
    'Em pé sobre a faixa, tensão com braços estendidos; pegada pronada um pouco menor que a largura dos ombros, manoplas junto às coxas, cotovelos com leve flexão, costas retas: posição inicial.\nExpire e eleve as manoplas para os lados com os ombros até pouco acima da paralela, inclinando a mão como ao derramar água, braços estendidos, tronco parado; pausa 1 seg no topo.\nInspire e abaixe lentamente as manoplas até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Latissimus Dorsi-SMR':
    'Deitado, coloque o rolo de espuma sob as costas, para um lado, logo atrás da axila: posição inicial.\nMantenha o braço alongado atrás do corpo, transfira o peso para os dorsais com o tronco afastado do chão; mantenha 10-30 seg e troque de lado.',
  'Leg Extensions':
    'Sente-se na cadeira extensora, apoio sobre a parte inferior da perna e pernas a 90°; não desça além de 90° para evitar estresse no joelho.\nExpire e estenda as pernas ao máximo com os quadríceps, corpo parado no banco; pausa de 1 segundo no alto.\nInspire e abaixe lentamente o peso até a posição inicial, sem passar do limite de 90°.\nRepita pelo número de repetições recomendado.',
  'Leg Lift':
    'Em pé, pés na largura dos ombros, apoie-se em um rack de agachamento ou no encosto de uma cadeira para o equilíbrio.\nExpire e levante uma perna para trás (com ou sem caneleira), como uma flexão de perna em pé, a outra reta.\nAbaixe lentamente a perna elevada até o chão enquanto inspira.\nRepita pelo número de repetições recomendado.\nRepita o movimento com a perna oposta.',
  'Leg Press':
    'Sente-se no leg press e coloque os pés na plataforma com afastamento médio (largura dos ombros).\nSolte os travas e estenda as pernas sem travar os joelhos, com tronco e pernas a 90°: posição inicial.\nInspire e abaixe a plataforma até as duas partes da perna formarem um ângulo de 90°.\nExpire e empurre com os calcanhares e quadríceps para voltar à posição inicial.\nRepita as repetições recomendadas e trave bem os pinos de segurança ao terminar.',
  'Leg Pull-In':
    'Deite-se com as pernas estendidas e as mãos (palmas para baixo) ao lado do corpo ou sob os glúteos: posição inicial.\nExpire e leve as coxas ao abdômen até os joelhos chegarem ao peito, panturrilhas paralelas ao chão; contraia e mantenha 1 seg.\nVolte à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Leg-Over Floor Press':
    'Deite-se com o kettlebell sobre o peito pela alça; cruze a perna do lado ativo sobre a outra e estenda o braço livre como apoio.\nEmpurre o kettlebell até travar o braço no alto.\nAbaixe o peso até o cotovelo tocar o chão, com o kettlebell sobre o cotovelo, e repita as repetições desejadas.',
  'Leg-Up Hamstring Stretch':
    'Deite-se de costas, flexione um joelho e apoie esse pé totalmente no chão para estabilizar a coluna.\nEstenda a outra perna no ar, joelho estendido e sola do pé voltada para o teto (o mais próximo que conseguir).\nEstique lentamente as pernas o máximo possível e depois puxe a perna em direção ao nariz. Troque de lado.',
  'Leverage Chest Press':
    'Ajuste o pino à carga e o assento à sua altura; manoplas na altura inferior ou média do peito.\nO peito e a cabeça devem estar erguidos e as escápulas retraídas. Esta será sua posição inicial.\nEmpurre as manoplas para a frente estendendo os cotovelos.\nApós uma pausa no alto, retorne quase à posição inicial sem apoiar o peso nos batentes até terminar a série.',
  'Leverage Deadlift':
    'Ajuste o pino à carga, fique entre as manoplas e segure as inferiores; abaixe o quadril inspirando, olhar à frente e peito erguido: posição inicial.\nRetorne o peso à posição inicial.',
  'Leverage Decline Chest Press':
    'Ajuste o pino à carga e o assento à sua altura; manoplas na parte inferior do peito, peito e cabeça erguidos, escápulas retraídas: posição inicial.\nEmpurre as manoplas para a frente estendendo os cotovelos.\nApós uma pausa no alto, retorne quase à posição inicial sem apoiar o peso nos batentes até terminar a série.',
  'Leverage High Row':
    'Ajuste o pino à carga, o assento para alcançar as manoplas e o apoio dos joelhos; pegada pronada: posição inicial.\nPuxe as manoplas em direção ao tronco, retraindo as escápulas enquanto flexiona os cotovelos.\nFaça uma pausa na parte final do movimento e depois retorne lentamente as manoplas à posição inicial.\nEm séries de várias repetições, não retorne o peso totalmente aos batentes para manter a tensão muscular.',
  'Leverage Incline Chest Press':
    'Ajuste o pino à carga e o assento à sua altura; manoplas na parte superior do peito, peito e cabeça erguidos, escápulas retraídas: posição inicial.\nEmpurre as manoplas para a frente estendendo os cotovelos.\nApós uma pausa no alto, retorne quase à posição inicial sem apoiar o peso nos batentes até terminar a série.',
  'Leverage Iso Row':
    'Ajuste a carga e o assento para que as manoplas fiquem na altura do peito; segure com pegada neutra ou pronada.\nPuxe as manoplas em direção ao tronco, retraia as escápulas e flexione os cotovelos.\nPause no final do movimento e retorne lento sem bater nos batentes, para manter a tensão muscular.',
  'Leverage Shoulder Press':
    'Ajuste a carga e o assento à sua altura: manoplas perto dos ombros, peito e cabeça erguidos, pegada pronada.\nEmpurre as manoplas para cima estendendo os cotovelos.\nPause no alto e retorne até um pouco acima do início, sem apoiar nos batentes até terminar a série.',
  'Leverage Shrug':
    'Ajuste a carga e posicione-se entre as manoplas.\nSegure as manoplas superiores, inspire e abaixe o quadril; olhe para a frente e mantenha o peito erguido.\nEmpurre o chão com os calcanhares e fique em pé estendendo quadris e joelhos, braços retos, ombros atrás.\nEleve o peso encolhendo os ombros em direção às orelhas, em linha reta para cima e para baixo.\nPause no topo e retorne o peso à posição inicial.',
  'Linear 3-Part Start Technique':
    'Em uma linha de partida, posicione o pé esquerdo com a ponta junto ao tornozelo direito e o direito 10-15 cm atrás.\nColoque a mão direita sobre a linha e aproxime o nariz do joelho esquerdo.\nAgache inclinado para a frente, cabeça mais baixa que o quadril, peso sobre a perna esquerda.\nLeve a mão esquerda paralela ao chão apontando para trás e saia explosivamente quando estiver pronto.',
  'Linear Acceleration Wall Drill':
    'Incline-se a 45 graus contra uma parede, pés juntos e glúteos contraídos.\nSuba rápido o joelho direito, pause e leve-o direto para baixo, em direção ao chão.\nTroque de perna: suba o joelho oposto e ataque o chão diretamente para baixo.\nRepita com a direita e, ao tocar o pé, alterne golpes rápidos esquerda-direita o mais veloz possível.',
  'Linear Depth Jump':
    'Fique em pé sobre uma caixa, de frente para outra plataforma separada por alguns passos.\nDesça suavemente até o chão entre as plataformas, flexionando joelhos e quadris.\nInverta o movimento explosivamente, estendendo quadris, joelhos e tornozelos para saltar à outra plataforma.\nAterrisse suavemente, absorvendo o impacto com as pernas.',
  'Log Lift':
    'Segure as alças e faça o clean: incline-se, suba o log jalando-o ao peito e estenda quadris e joelhos.\nFaça push press: flexione os joelhos, estenda os cotovelos para subir o log acima da cabeça e leve a cabeça para a frente.\nRepita o máximo de vezes possível e controle a descida do log ao devolvê-lo ao chão.',
  'London Bridges':
    'Prenda uma corda de escalada a uma viga alta; trave a barra do smith embaixo (ou use uma caixa firme).\nSuba na barra usando a corda para se equilibrar.\nCom o corpo reto, incline-se para trás e desça mão sobre mão pela corda até ficar perpendicular ao chão.\nCom o corpo reto, inverta o movimento subindo mão sobre mão de volta à posição inicial.',
  'Looking At Ceiling':
    'Ajoelhe-se no chão segurando os calcanhares com as duas mãos.\nLevante os glúteos para cima e para a frente, leve a cabeça para trás olhando o teto e arqueie as costas.',
  'Low Cable Crossover':
    'Coloque as polias na posição baixa, selecione a resistência e segure uma manopla em cada mão.\nDê um passo à frente com tensão nas polias, palmas para a frente, mãos abaixo da cintura e braços retos.\nCom leve flexão nos braços, leve as mãos para cima até o centro, juntando-as à frente do peito com palmas para cima.\nRetorne os braços à posição inicial após uma breve pausa.',
  'Low Cable Triceps Extension':
    'Selecione a carga e deite-se de barriga para cima no banco de uma máquina de remada sentada com corda, cabeça para o acessório.\nSegure as pontas da corda por fora com as palmas uma para a outra (pegada neutra).\nFlexione os cotovelos a 90 graus, braços perpendiculares ao tronco, cotovelos para dentro e antebraços para a polia.\nExpire e estenda os antebraços até ficarem retos e verticais, sem mover braços ou cotovelos; contraia o tríceps por um segundo.\nInspire e retorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Low Pulley Row To Neck':
    'Sente-se em uma máquina de remada com polia baixa e acessório de corda.\nSegure a corda com palmas para baixo, costas retas, joelhos levemente flexionados e braços estendidos à frente.\nPuxe a corda em direção ao pescoço flexionando os cotovelos e expirando, braços paralelos ao chão, cotovelos para fora, tronco parado.\nMantenha a contração por um segundo e inspire retornando lentamente, sem mover o tronco.\nRepita pelo número de repetições recomendado.',
  'Lower Back Curl':
    'Deite-se de bruços com os braços estendidos para os lados.\nEstenda a coluna com os músculos lombares, levantando o peito do chão sem usar os braços, cabeça erguida; repita 10-20 vezes.',
  'Lower Back-SMR':
    'Sentado, coloque um rolo de espuma sob a lombar, braços cruzados à frente e ombros protraídos.\nLevante o quadril, incline-se para trás com o peso sobre a lombar, desloque para um lado e role 10-30 segundos; repita do outro lado.',
  'Lunge Pass Through':
    'Fique em pé ereto segurando um kettlebell na mão direita.\nDê um passo à frente com o pé esquerdo e abaixe flexionando quadril e joelho, tronco ereto, até quase tocar o chão com o joelho de trás.\nNo afundo, passe o kettlebell por baixo da perna da frente para a mão oposta.\nEmpurre pelo calcanhar e retorne à posição inicial.\nRepita alternando as pernas pelo número de repetições recomendado.',
  'Lunge Sprint':
    'Ajuste a barra do smith a boa altura, apoie-a nos ombros e coloque um pé na frente e outro atrás.\nAbaixe o joelho de trás quase ao chão flexionando os joelhos e abaixando o quadril.\nInverta de imediato: empurre explosivo pelo calcanhar da frente com leve pressão do pé de trás, salte e troque de perna.\nRepita pelo número de repetições recomendado.',
  'Lying Bent Leg Groin':
    'Deite-se de costas, joelhos flexionados e solas unidas; peça ao parceiro que segure seus joelhos.\nTente juntar os joelhos apertando enquanto seu parceiro impede o movimento.\nApós 10-20 segundos, relaxe enquanto seu parceiro empurra suave os joelhos ao chão; avise se for demais para evitar lesão.',
  'Lying Cable Curl':
    'Segure com as duas mãos uma barra reta ou W na polia baixa, pegada supinada na largura dos ombros.\nDeite-se de costas em frente à pilha de pesos, pés contra a estrutura da máquina e pernas retas.\nEstenda os braços com cotovelos próximos ao corpo e flexione-os levemente.\nSuba a barra lentamente ao peito expirando e apertando o bíceps, cotovelos parados e junto ao corpo.\nMantenha a contração por um segundo no topo e retorne lentamente à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Lying Cambered Barbell Row':
    'Coloque uma barra cambered (curvada) sob um banco de exercícios.\nDeite-se de bruços no banco e segure a barra com pegada pronada mais larga que os ombros.\nExpire e reme a barra para cima com cotovelos junto ao corpo: ao peito para costas médio-superiores, ou ao abdômen para dorsais.\nMantenha um segundo no alto e inspire baixando lentamente à posição inicial.',
  'Lying Close-Grip Bar Curl On High Pulley':
    'Coloque um banco reto em frente a uma polia alta ou máquina de puxada alta.\nSegure a barra reta com pegada supinada na largura aproximada dos ombros.\nDeite-se de costas com a cabeça além da ponta do banco.\nEstenda os braços retos acima dos ombros formando 90 graus com o tronco, cotovelos junto ao corpo.\nExpire e faça a rosca semicircular até a barra tocar o queixo; contraia o bíceps por um segundo, só mova os antebraços.\nVolte lentamente à posição inicial.\nRepita o número recomendado de repetições.',
  'Lying Close-Grip Barbell Triceps Extension Behind The Head':
    'Deite-se de costas em um banco reto com a cabeça perto da ponta, segurando uma barra reta ou W (pegadas internas se for W) com pegada pronada na largura dos ombros.\nEstenda os braços à frente e leve-os para trás em semicírculo até ficarem acima da cabeça e paralelos ao chão, cotovelos junto ao corpo.\nInspire e abaixe a barra flexionando os cotovelos, braços parados, até os antebraços ficarem perpendiculares ao chão.\nExpire e empurre a barra em semicírculo até os antebraços ficarem paralelos ao chão; contraia o tríceps por um segundo, só mova os antebraços.\nRepita o número recomendado de repetições.',
  'Lying Close-Grip Barbell Triceps Press To Chin':
    'Deite-se de costas em um banco reto com a cabeça além da ponta, segurando uma barra reta ou W (pegadas internas se for W) com pegada pronada na largura dos ombros.\nEstenda os braços à frente segurando a barra sobre o peito, em ângulo de 90 graus com o tronco.\nInspire e abaixe a barra em semicírculo flexionando os cotovelos, braços parados e cotovelos junto ao corpo, até tocar levemente o queixo.\nExpire e empurre a barra de volta em semicírculo; contraia o tríceps por um segundo, só mova os antebraços.\nRepita o número recomendado de repetições.',
  'Lying Crossover':
    'Deite-se de costas com as pernas estendidas.\nCruze uma perna sobre o corpo com o joelho flexionado ao chão; seu parceiro segura seu ombro e controla a perna cruzada.\nTente levantar o joelho flexionado do chão enquanto seu parceiro impede o movimento.\nApós 10-20 segundos, relaxe enquanto seu parceiro pressiona suave o joelho ao chão; repita do outro lado.',
  'Lying Dumbbell Tricep Extension':
    'Deite-se em um banco reto com dois halteres à frente, braços estendidos a 90 graus do tronco e do chão, palmas para dentro, cotovelos junto ao corpo.\nInspire e, com braços e cotovelos parados, abaixe o peso lentamente até os halteres ficarem perto das orelhas.\nCom cotovelos para dentro e braços parados, use o tríceps para levar o peso de volta expirando.\nRepita o número recomendado de repetições.',
  'Lying Face Down Plate Neck Resistance':
    'Deite-se de bruços em um banco reto com uma anilha atrás da cabeça, ombros pouco além da ponta do banco.\nCom a anilha firme na cabeça, abaixe-a lentamente (como se dissesse "sim") inspirando.\nLevante a cabeça em semicírculo à posição inicial expirando; segure a contração por um segundo.\nRepita o número recomendado de repetições.',
  'Lying Face Up Plate Neck Resistance':
    'Deite-se de barriga para cima em um banco reto com uma anilha sobre a testa, ombros pouco além da ponta do banco.\nCom a anilha firme na testa, abaixe a cabeça para trás em semicírculo inspirando.\nLevante a cabeça em semicírculo à posição inicial expirando; segure a contração por um segundo.\nRepita o número recomendado de repetições.',
  'Lying Glute':
    'Deite-se de costas com seu parceiro ajoelhado ao seu lado.\nFlexione um quadril levantando a perna, pé sobre o quadril oposto e perna inferior perpendicular; seu parceiro segura joelho e tornozelo.\nTente empurrar a perna em direção ao parceiro enquanto ele impede o movimento.\nApós 10-20 segundos, relaxe enquanto seu parceiro empurra suave o tornozelo e o joelho ao peito; avise se for demais.',
  'Lying Hamstring':
    'Deite-se de costas, pernas estendidas; levante uma perna ao teto e peça ao parceiro que segure o tornozelo.\nCom o parceiro segurando a perna, tente flexionar o joelho contraindo o posterior de coxa por 10-20 segundos.\nRelaxe a perna e deixe o parceiro empurrá-la suave em direção à cabeça; avise se for demais. Troque de lado.',
  'Lying High Bench Barbell Curl':
    'Deite-se de bruços em um banco alto, peito além da ponta, segurando a barra (ou barra W pelas pegadas internas) com pegada supinada, braços estendidos e perpendiculares ao chão.\nCom cotovelos junto ao corpo e braços parados, suba o peso em semicírculo expirando e contraindo o bíceps por um segundo.\nInspire e volte lentamente à posição inicial sem balançar o corpo; só os antebraços se movem.\nRepita o número recomendado de repetições.',
  'Lying Leg Curls':
    'Ajuste a alavanca à sua altura e deite-se de bruços com o rolo na parte de trás das pernas, abaixo das panturrilhas; use de preferência mesa inclinada.\nCom o tronco reto, pernas estendidas, segure as pegadas laterais e posicione as pontas dos pés retas.\nExpire e flexione as pernas para cima sem levantar as coxas do apoio; segure a contração por um segundo.\nInspire e leve as pernas de volta à posição inicial. Repita o número recomendado de repetições.',
  'Lying Machine Squat':
    'Ajuste a máquina a uma altura que permita entrar com os joelhos flexionados e as coxas abaixo da paralela.\nDe barriga para cima na máquina: joelhos flexionados, coxas abaixo da paralela, joelhos sem passar da ponta dos pés, ângulo posteriores-panturrilha menor que 90°, costas e ombros apoiados sob as almofadas.\nSegure as pegadas e posicione os pés na largura dos ombros, levemente voltados para fora: posição inicial.\nEmpurre com a ponta dos pés, expire e estenda o corpo contraindo os quadríceps; segure por 1 segundo (na primeira repetição pode se ajudar pressionando as coxas com as mãos).\nInspire e desça lentamente até as coxas ficarem paralelas à plataforma, com ângulo de 90° entre posteriores e panturrilhas.\nRepita o número de repetições recomendado.',
  'Lying One-Arm Lateral Raise':
    'Segure um halter com uma das mãos e deite-se de bruços em um banco reto; segure a perna do banco com a outra mão para estabilidade.\nPosicione a palma da mão com o halter em posição neutra (voltada para o tronco), braço estendido e cotovelo levemente flexionado: posição inicial.\nExpire e levante o braço com o halter para o lado até o cotovelo ficar na altura do ombro, braço paralelo ao chão e perpendicular ao tronco; segure a contração por 1 segundo.\nInspire e abaixe lentamente o halter até a posição inicial.\nRepita o número de repetições recomendado.',
  'Lying Prone Quadriceps':
    'Deite-se de bruços com o parceiro ajoelhado ao lado; flexione um joelho tentando tocar o glúteo com o pé, enquanto o parceiro segura o joelho e o tornozelo: posição inicial.\nTente estender o joelho enquanto o parceiro impede o movimento.\nApós 10 a 20 segundos, relaxe os músculos enquanto o parceiro empurra suavemente o pé em direção ao glúteo, alongando mais o quadríceps e o flexor do quadril.\nApós 10 a 20 segundos, troque de lado.',
  'Lying Rear Delt Raise':
    'Segure um halter em cada mão e deite-se de bruços em um banco reto.\nPosicione as palmas em posição neutra (voltadas para o tronco), braços estendidos e cotovelos levemente flexionados: posição inicial.\nExpire e levante os braços para os lados até os cotovelos ficarem na altura dos ombros, braços paralelos ao chão e perpendiculares ao tronco; segure a contração por 1 segundo.\nInspire e abaixe lentamente os halteres até a posição inicial.\nRepita o número de repetições recomendado e troque para o outro braço.',
  'Lying Supine Dumbbell Curl':
    'Deite-se de barriga para cima em um banco reto, segurando um halter em cada mão sobre as coxas.\nLeve os halteres para as laterais com os braços estendidos e as palmas voltadas para as coxas (pegada neutra).\nCom os braços perto do tronco e os cotovelos para dentro, abaixe os braços (estendidos, com leve flexão nos cotovelos) o máximo possível em direção ao chão e trave: posição inicial.\nExpire e suba os halteres em rosca girando os punhos até as palmas ficarem para cima; contraia os bíceps totalmente e segure por 1 segundo (apenas os antebraços se movem; braços parados e cotovelos junto ao corpo).\nVolte bem lentamente à posição inicial.',
  'Lying T-Bar Row':
    'Carregue a máquina de remada em T e ajuste a altura das pernas para que a parte superior do peito fique no topo do apoio (em algumas máquinas, escolha o degrau adequado).\nDeite-se de bruços no apoio e segure as pegadas com palmas para baixo, para cima ou para dentro, conforme a parte das costas a enfatizar.\nRetire a barra do suporte e estenda os braços à sua frente: posição inicial.\nExpire e puxe lentamente o peso para cima, contraindo as costas em cima; mantenha os braços perto do tronco, o corpo apoiado no apoio o tempo todo e evite usar os bíceps.\nSegure a contração por 1 segundo em cima, depois inspire e volte lentamente à posição inicial.\nRepita o número de repetições recomendado.',
  'Lying Triceps Press':
    'Deite-se em um banco reto com uma barra W ou reta no chão atrás da cabeça e os pés no chão.\nSegure a barra com pegada pronada de largura média e levante-a à frente com os braços estendidos, perpendiculares ao tronco e ao chão, cotovelos junto ao corpo: posição inicial.\nInspire e abaixe lentamente o peso até a barra tocar de leve a testa, com braços e cotovelos parados.\nExpire e use os tríceps para levar o peso de volta à posição inicial.\nRepita o número de repetições recomendado.',
  'Machine Bench Press':
    'Sente-se na máquina de supino e selecione a carga.\nPise na alavanca para levar as pegadas para a frente e poder segurá-las com os braços totalmente estendidos.\nSegure as pegadas com palmas para baixo e levante os cotovelos até os braços ficarem paralelos ao chão ao lado do tronco (antebraços apontando para a frente): posição inicial.\nInspire e traga as pegadas de volta em sua direção.\nExpire e empurre as pegadas para longe de você contraindo os peitorais; segure a contração por 1 segundo antes de voltar à posição inicial.\nRepita o número de repetições recomendado.\nAo terminar, pise novamente na alavanca e devolva lentamente as pegadas à posição original.',
  'Machine Bicep Curl':
    'Ajuste o banco à altura adequada, selecione a carga e apoie a parte superior dos braços nas almofadas segurando as pegadas: posição inicial.\nFlexione o cotovelo levando o antebraço em direção à parte superior do braço.\nFaça uma pausa em cima e volte lentamente com o peso à posição inicial.\nEvite levar o peso até o fim do curso até terminar a série, para manter a tensão no músculo.',
  'Machine Preacher Curls':
    'Sente-se na máquina de rosca Scott e selecione a carga.\nApoie a parte de trás dos braços (tríceps) no apoio da rosca Scott e segure as pegadas com pegada supinada, cotovelos para dentro: posição inicial.\nExpire e suba as pegadas contraindo os bíceps; segure por 1 segundo em cima (apenas os antebraços se movem; braços parados e apoiados no suporte).\nInspire e abaixe lentamente as pegadas até a posição inicial.\nRepita o número de repetições recomendado.',
  'Machine Shoulder (Military) Press':
    'Sente-se na máquina de desenvolvimento de ombros e selecione a carga.\nSegure as pegadas ao lado do corpo com os cotovelos flexionados e alinhados com o tronco: posição inicial.\nExpire e suba as pegadas estendendo totalmente os braços; segure a contração por 1 segundo em cima.\nInspire e abaixe lentamente as pegadas até a posição inicial.\nRepita o número de repetições recomendado.',
  'Machine Triceps Extension':
    'Ajuste o banco à altura adequada, selecione a carga e apoie a parte superior dos braços nas almofadas segurando as pegadas: posição inicial.\nEstenda o cotovelo afastando o antebraço da parte superior do braço.\nFaça uma pausa ao completar o movimento e volte lentamente com o peso à posição inicial.\nEvite levar o peso até o fim do curso até terminar a série, para manter a tensão no músculo.',
  'Medicine Ball Chest Pass':
    'Você precisa de um parceiro; se não tiver, faça o movimento contra uma parede.\nFique de frente para o parceiro segurando a medicine ball na altura do tronco com as duas mãos.\nLeve a bola ao peito e arremesse estendendo os cotovelos; em aplicações esportivas, dê um passo ao arremessar.\nSeu parceiro pega a bola e arremessa de volta para você.\nReceba o arremesso com as duas mãos na altura do peito.',
  'Medicine Ball Full Twist':
    'Você precisa de uma medicine ball e de um parceiro; fique de costas um para o outro, a 60–90 cm: posição inicial.\nSegure a bola à frente do tronco e gire quadris e ombros ao mesmo tempo que seu parceiro.\nPara uma rotação completa, você e seu parceiro giram na mesma direção (sentido anti-horário).\nPasse a bola ao parceiro e ambos giram na direção oposta para repetir.',
  'Medicine Ball Scoop Throw':
    'Assuma meio agachamento com uma medicine ball nas mãos, braços pendurados até a bola ficar perto dos pés.\nProjete o quadril para a frente estendendo as pernas e salte para cima.\nLeve os braços estendidos para cima, acima da cabeça, e solte a bola no ponto mais alto, buscando a maior distância possível atrás de você.',
  'Middle Back Shrug':
    'Deite-se de bruços em um banco inclinado segurando um halter em cada mão, braços estendidos pendurados para o chão e palmas uma de frente para a outra: posição inicial.\nExpire e aproxime as escápulas; segure a contração por 1 segundo completo (como o inverso de um abraço, ou elevações posteriores sem braços).\nInspire e volte à posição inicial.\nRepita o número de repetições recomendado.',
  'Middle Back Stretch':
    'Fique em pé com os pés na largura dos ombros e as mãos nos quadris.\nGire a cintura até sentir o alongamento; segure por 10 a 15 segundos e gire para o outro lado.',
  'Mixed Grip Chin':
    'Segure a barra fixa com um espaçamento cerca de 2,5 cm maior que os ombros, uma palma para a frente e a outra para você: posição inicial.\nExpire e puxe o corpo para cima; com o braço de palma para você use os dorsais e mantenha o cotovelo perto do tronco; com o outro, cotovelo afastado mas alinhado com o tronco.\nSegure a contração por 1 segundo em cima, depois inspire e desça lentamente.\nRepita o número de repetições recomendado.\nNa série seguinte, inverta a pegada de cada mão.',
  'Monster Walk':
    'Coloque uma faixa em ambos os tornozelos e outra em ambos os joelhos, com tensão suficiente ao afastar os pés na largura dos ombros.\nDê passos curtos para a frente alternando o pé esquerdo e o direito.\nApós vários passos, ande para trás até o ponto de partida.',
  'Mountain Climbers':
    'Comece na posição de flexão de braço, apoiado nas mãos e nas pontas dos pés; leve um joelho à frente sob o quadril, flexionando joelho e quadril: posição inicial.\nInverta as pernas de forma explosiva: estenda a perna flexionada apoiando a ponta do pé e leve a outra perna à frente com quadril e joelho flexionados; alterne por 20 a 30 segundos.',
  'Moving Claw Series':
    'Ao correr, flexione o joelho buscando chutar o glúteo enquanto o quadril se estende, para melhorar a técnica de sprint.\nRecarregue o quadríceps ao trazer a perna de volta para a frente, atacando o solo no próximo passo.\nBloqueie com os braços enquanto corre, socando para a frente em um movimento rápido de 1-2.',
  'Muscle Snatch':
    'Segure a barra carregada na altura da metade da coxa com pegada aberta, pés sob os quadris e pontas para fora; abaixe os quadris, peito erguido, olhar à frente e ombros logo à frente da barra: posição inicial.\nEmpurre pela parte da frente dos calcanhares para iniciar a puxada, elevando a barra; depois estenda quadris, joelhos e tornozelos na segunda puxada, impulsionando a barra para cima o mais rápido possível, perto do corpo.\nContinue elevando a barra até a posição acima da cabeça, sem flexionar novamente os joelhos.',
  'Muscle Up':
    'Segure as argolas com pegada falsa (base das palmas sobre as argolas) e inicie uma barra fixa levando os cotovelos para baixo, junto ao corpo.\nAo chegar em cima, leve as argolas em direção às axilas girando os ombros para a frente para que os cotovelos passem direto para trás, preparando as paralelas.\nCom controle e estabilidade, estenda os cotovelos para completar o movimento.\nDesça até o chão com cuidado.',
  'Narrow Stance Hack Squats':
    'Apoie as costas no encosto da máquina e encaixe os ombros sob as almofadas.\nPosicione os pés na plataforma com base estreita (menor que a largura dos ombros, cerca de 7 cm ou menos entre eles), pontas levemente para fora; mantenha a cabeça erguida e as costas apoiadas o tempo todo.\nSegure as pegadas laterais e libere as barras de segurança (geralmente girando-as da posição frontal para a diagonal).\nEstenda as pernas sem travar os joelhos: posição inicial.\nInspire e desça flexionando os joelhos, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar levemente menor que 90° (coxas abaixo da paralela).\nExpire e suba empurrando principalmente com os calcanhares, estendendo as pernas até a posição inicial.\nRepita o número de repetições recomendado.',
  'Narrow Stance Leg Press':
    'Sente-se na máquina de leg press, posicione os pés na plataforma com base estreita (menor que a largura dos ombros, cerca de 7 cm ou menos entre eles), pontas levemente para fora; cabeça erguida e costas apoiadas o tempo todo.\nAbaixe as barras de segurança e empurre a plataforma até estender totalmente as pernas (sem travar os joelhos), formando 90° entre tronco e pernas: posição inicial.\nInspire e abaixe lentamente a plataforma até formar 90° entre coxa e panturrilha.\nExpire e empurre principalmente com os calcanhares usando os quadríceps para voltar à posição inicial.\nRepita o número de repetições recomendado e trave bem os pinos de segurança ao terminar.',
  'Narrow Stance Squats':
    'Por segurança, use um rack de agachamento; ajuste a barra à sua altura, carregue-a e apoie a parte de trás dos ombros (abaixo do pescoço) sobre ela.\nSegure a barra com as duas mãos, retire-a do rack empurrando com as pernas enquanto endireita o tronco.\nDê um passo para trás, posicione os pés com base estreita (menor que a largura dos ombros, cerca de 7 a 15 cm entre eles), pontas levemente para fora, cabeça erguida e costas retas: posição inicial.\nInspire e desça flexionando os joelhos, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar levemente menor que 90°; cuide para os joelhos não passarem da ponta dos pés.\nExpire e suba empurrando principalmente com o calcanhar, estendendo as pernas até a posição inicial.\nRepita o número de repetições recomendado.',
  'Natural Glute Ham Raise':
    'Em uma máquina de puxada alta ou banco Scott, posicione os tornozelos sob os apoios, os joelhos no assento, de costas para a máquina, com boa postura ereta: posição inicial.\nAbaixe o corpo com controle até os joelhos ficarem quase retos.\nCom controle, suba de volta à posição inicial.\nSe não completar a repetição, use uma faixa, um parceiro ou se impulsione com as mãos em uma caixa.',
  'Neck Press':
    'Deite-se em um banco reto, retire a barra do suporte com pegada de largura média (90° entre antebraço e braço) e segure-a reta sobre o pescoço com os braços travados: posição inicial.\nInspire e desça lentamente até sentir a barra no pescoço.\nApós uma pausa de 1 segundo, expire e empurre a barra com o peito até a posição inicial; trave os braços, contraia o peito e segure por 1 segundo antes de descer de novo (a descida deve levar pelo menos o dobro do tempo da subida).\nRepita o movimento pelo número de repetições prescrito.\nAo terminar, coloque a barra de volta no suporte.',
  'Neck-SMR':
    'Coloque um rolo de massagem ou de macarrão atrás da cabeça contra o pescoço, levemente inclinado (não sobre a coluna) para pressionar os músculos dos dois lados: posição inicial.\nA partir da parte superior do pescoço, role lentamente, pausando 10 a 30 segundos nos pontos de tensão.',
  'Oblique Crunches':
    'Deite-se de costas com a parte inferior das costas pressionada contra o chão; coloque uma mão ao lado da cabeça e a outra ao lado do corpo contra o chão.\nEleve os pés e apoie-os em uma superfície plana.\nLevante o ombro do lado da mão que toca a cabeça.\nEleve o ombro e o corpo até tocar o joelho oposto (ex.: cotovelo direito com joelho esquerdo, ou vice-versa).\nAbaixe o corpo até a posição inicial depois que o joelho tocar o cotovelo.\nInspire ao descer (fase excêntrica) e expire ao subir (fase concêntrica).\nAlterne assim até completar as repetições recomendadas para cada lado.',
  'Oblique Crunches - On The Floor':
    'Deite-se sobre o lado direito, pernas uma sobre a outra, com os joelhos levemente flexionados.\nColoque a mão esquerda atrás da cabeça.\nSuba o cotovelo esquerdo como em um abdominal normal, com ênfase nos oblíquos.\nSuba o mais alto possível, segure a contração por 1 segundo e desça devagar à posição inicial.\nInspire ao descer (fase excêntrica) e expire ao subir (fase concêntrica).',
  'Olympic Squat':
    'Apoie a barra sobre o trapézio, peito erguido e cabeça à frente; pés na largura do quadril, pontas para fora.\nDesça flexionando os joelhos sem levar o quadril para trás, joelhos alinhados aos pés, tronco ereto e peso no calcanhar.\nQuando a coxa tocar a panturrilha, inverta o movimento empurrando o peso para cima.',
  'On Your Side Quad Stretch':
    'Deite-se sobre o lado direito com o joelho direito flexionado a 90° apoiado no chão para estabilizar o tronco.\nFlexione o joelho esquerdo e segure o pé esquerdo com a mão esquerda; empurre o quadril para a frente e o pé para trás contra a mão para alongar o flexor do quadril. Troque de lado.',
  'On-Your-Back Quad Stretch':
    'Deite-se em um banco reto ou step e deixe uma perna e um braço pendurados para o lado.\nFlexione o joelho e segure o peito do pé sem arquear a lombar.\nLeve o umbigo à coluna (posição neutra), pressione o pé contra a mão e levante esse quadril em direção ao teto para somar o alongamento.\nTroque de lado.',
  'One Arm Against Wall':
    'Em pé, apoie um braço flexionado contra uma parede ou batente de porta.\nIncline-se devagar em direção ao braço até sentir um alongamento nos dorsais.',
  'One Arm Chin-Up':
    'Coloque uma toalha ao redor de uma barra fixa.\nSegure a barra com a palma voltada para você: uma mão segura a barra e a outra a toalha.\nIncline o tronco para trás cerca de 30°, arqueando a lombar e projetando o peito: posição inicial.\nSuba até a barra tocar o peito, ombros e braços para baixo e para trás, expirando; contraia as costas na contração, mantendo o tronco estável e movendo só os braços.\nApós 1 segundo na contração, inspire e desça devagar até estender os braços e alongar totalmente os dorsais.\nRepita o número de repetições indicado.\nTroque de braço e repita o movimento.',
  'One Arm Dumbbell Bench Press':
    'Deite-se em um banco reto com um halter em uma mão sobre a coxa.\nUse a coxa para subir o halter e segure-o à frente do corpo na largura dos ombros, ajudando com a outra mão para posicioná-lo.\nCom o halter na largura dos ombros, gire o punho para que a palma fique voltada para fora: posição inicial.\nAbaixe o peso devagar para o lado do corpo inspirando, com controle total; use a mão livre só se precisar equilibrar.\nExpire e empurre o halter para cima com o peitoral, trave o braço, contraia o peito por 1 segundo; desça o dobro mais devagar que a subida.\nRepita o número de repetições do seu programa.\nTroque de braço e repita o movimento.',
  'One Arm Dumbbell Preacher Curl':
    'Apoie o braço direito com um halter sobre o banco Scott ou inclinado, halter na altura do ombro: posição inicial.\nInspire e abaixe devagar o halter até estender o braço e alongar totalmente o bíceps.\nExpire e suba o peso com o bíceps até contraí-lo totalmente, halter na altura do ombro; leve o mínimo mais alto que o polegar.\nContraia o bíceps por 1 segundo na contração e repita o número de repetições recomendado.\nTroque de braço e repita o movimento.',
  'One Arm Floor Press':
    'Deite-se de costas no chão ou um colchonete, com as costas pressionadas contra o chão e os joelhos flexionados.\nPeça que lhe entreguem a barra em uma mão, braço quase estendido como em um supino, com pegada neutra (palma para o tronco).\nColoque a mão livre ao lado do corpo.\nAbaixe a barra até o cotovelo tocar o chão, inspirando nesta fase excêntrica.\nSuba a barra até a posição inicial expirando nesta fase concêntrica.\nRepita até completar as repetições recomendadas.\nTroque de braço e repita o movimento.',
  'One Arm Lat Pulldown':
    'Selecione a carga, ajuste o apoio de joelhos e segure a pegada pronada: posição inicial.\nPuxe a pegada para baixo, aproximando o cotovelo do corpo ao flexioná-lo.\nPause embaixo e volte devagar a pegada à posição inicial.\nEm várias repetições, não solte o peso por completo para manter a tensão muscular.',
  'One Arm Pronated Dumbbell Triceps Extension':
    'Deite-se em um banco reto com um halter, braço estendido perpendicular ao corpo, palma para os pés (pegada pronada).\nColoque a mão que não está levantando sobre o bíceps para apoio.\nComece a abaixar lentamente o halter enquanto inspira.\nSuba o halter contraindo o tríceps, expirando nesta fase concêntrica.\nRepita até completar as repetições da série.\nTroque de braço e repita o movimento.',
  'One Arm Supinated Dumbbell Triceps Extension':
    'Deite-se em um banco reto com um halter, braço estendido perpendicular ao corpo, palma para o rosto (pegada supinada).\nColoque a mão que não está levantando sobre o bíceps para apoio.\nComece a abaixar lentamente o halter enquanto inspira.\nSuba o halter contraindo o tríceps, expirando nesta fase concêntrica.\nRepita até completar as repetições da série.\nTroque de braço e repita o movimento.\nTroque de braço novamente e repita o movimento.',
  'One Half Locust':
    'Deite-se de bruços no chão.\nColoque a mão esquerda sob o osso do quadril esquerdo para amortecer o quadril e o púbis.\nFlexione o joelho direito para segurar o pé com a mão direita.\nLevante o pé e os ombros do chão ao mesmo tempo, alongando o flexor do quadril direito, o peito e os ombros; troque de lado. Sem desconforto lombar, tente com os dois braços e pernas.',
  'One Handed Hang':
    'Segure a barra fixa com uma mão (pegada pronada), pés no chão ou um degrau; deixe a maior parte do peso pendurado 10 a 20 segundos e troque de lado.',
  'One Knee To Chest':
    'Comece deitado no chão.\nEstenda uma perna reta e leve o outro joelho ao peito, segurando abaixo da articulação para proteger a patela.\nPuxe suavemente esse joelho em direção ao nariz.\nTroque de lado; alonga glúteo e lombar da perna flexionada e o flexor do quadril da estendida.',
  'One Leg Barbell Squat':
    'Fique em pé a 60-90 cm à frente de um banco reto, de costas para ele, com a barra no chão e os pés na largura dos ombros.\nFlexione os joelhos e, com pegada pronada mais larga que os ombros, suba a barra até apoiá-la no peito.\nSuba a barra acima da cabeça e apoie-a na base do pescoço; leve um pé para trás com a ponta no banco, cabeça erguida e costas retas, peito estufado.\nInspire e desça até a coxa ficar paralela ao chão, joelho sobre os dedos do pé e peito sobre o meio da coxa.\nConduza com peito e quadril, contraia o quadríceps e suba à posição inicial expirando.\nRepita o número recomendado de repetições.\nTroque de perna e repita o movimento.',
  'One-Arm Dumbbell Row':
    'Escolha um banco reto e coloque um halter de cada lado.\nApoie o joelho direito no banco, incline o tronco pela cintura até ficar paralelo ao chão e apoie a mão direita na outra ponta como suporte.\nPegue o halter do chão com a mão esquerda, lombar reta e palma para o tronco: posição inicial.\nPuxe o peso reto até a lateral do peito, braço perto do corpo e tronco imóvel, expirando; use as costas, não os braços nem o antebraço.\nAbaixe o peso reto até a posição inicial, inspirando.\nRepita o movimento pelo número de repetições indicado.\nTroque de lado e repita com o outro braço.',
  'One-Arm Flat Bench Dumbbell Flye':
    'Deite-se em um banco reto com um halter sobre a coxa, pegada neutra.\nUse a coxa para subir o halter à frente do corpo com o braço estendido e pegada neutra; segure o banco com a mão livre: posição inicial.\nCom o cotovelo levemente flexionado, abaixe o braço em um arco amplo até sentir o alongamento no peitoral, inspirando; o cotovelo fica fixo, o movimento é só no ombro.\nVolte o braço pelo mesmo arco à posição inicial, contraindo o peitoral e expirando.\nSegure 1 segundo a contração e repita o número de repetições indicado.\nTroque de braço e repita o exercício.',
  'One-Arm High-Pulley Cable Side Bends':
    'Conecte uma alça padrão à torre e coloque a polia na posição mais alta.\nFique de lado para a polia e segure a alça em cima com pegada supinada.\nPuxe a polia para baixo até o cotovelo tocar seu lado e a alça ficar junto ao ombro.\nSepare os pés na largura do quadril e apoie a mão livre no quadril como ponto de giro.\nCom o braço fixo, contraia o oblíquo e abaixe o peso em um abdominal lateral.\nNa contração máxima, solte devagar o peso sem deixar a pilha descansar por completo, mantendo tensão constante.\nRepita até a falha.\nTroque de lado e repita a mesma sequência de movimentos.',
  'One-Arm Incline Lateral Raise':
    'Deite-se de lado em um banco inclinado com um halter, ombro contra o banco e braço cruzado sobre o corpo, palma na altura do umbigo.\nSegure o halter com o braço de cima estendido à frente, paralelo ao chão: posição inicial.\nCom o halter paralelo ao chão, eleve o braço em linha reta até apontar para o teto, expirando; segure 1 segundo sentindo a contração do ombro.\nInspire e abaixe o peso cruzando o corpo até a posição inicial.\nRepita o movimento pelo número de repetições indicado.\nTroque de braço e repita o movimento.',
  'One-Arm Kettlebell Clean':
    'Coloque o kettlebell entre os pés; ao abaixar, leve o quadril para trás e olhe para a frente.\nSuba o kettlebell ao ombro estendendo pernas e quadril, girando o punho.\nVolte o peso à posição inicial.',
  'One-Arm Kettlebell Clean and Jerk':
    'Segure o kettlebell pela alça.\nSuba o kettlebell ao ombro estendendo pernas e quadril, girando o punho até a palma ficar voltada para a frente.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta de imediato empurrando pelos calcanhares, quase saltando, e empurre o kettlebell acima da cabeça até travar o braço com o impulso do corpo.\nReceba o peso acima da cabeça voltando a um agachamento por baixo dele.\nCom o peso acima da cabeça, fique em pé e abaixe o kettlebell ao chão para a próxima repetição.',
  'One-Arm Kettlebell Floor Press':
    'Deite-se no chão com o kettlebell em uma mão, braço apoiado no chão e palma voltada para dentro.\nEmpurre o kettlebell em linha reta para o teto, girando o punho.\nAbaixe o kettlebell de volta à posição inicial e repita.',
  'One-Arm Kettlebell Jerk':
    'Suba o kettlebell ao ombro estendendo pernas e quadril, girando o punho até a palma ficar voltada para a frente: posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta de imediato empurrando pelos calcanhares, quase saltando, empurre o kettlebell acima da cabeça até travar o braço, receba-o em agachamento e fique em pé.\nAbaixe o peso para realizar a próxima repetição.',
  'One-Arm Kettlebell Military Press To The Side':
    'Suba o kettlebell ao ombro estendendo pernas e quadril, girando o punho até a palma ficar voltada para dentro: posição inicial.\nOlhe para o kettlebell e empurre-o para cima e para fora até travar o braço acima da cabeça.\nAbaixe o kettlebell ao ombro com controle e repita, contraindo forte o dorsal, os glúteos e o abdômen para estabilidade.',
  'One-Arm Kettlebell Para Press':
    'Suba o kettlebell ao ombro estendendo pernas e quadril, girando o punho até a palma ficar voltada para a frente: posição inicial.\nSegure o kettlebell com o cotovelo ao lado e empurre-o para cima e para fora até travar o braço acima da cabeça.\nAbaixe o kettlebell ao ombro com controle e repita, contraindo forte o dorsal, os glúteos e o abdômen para estabilidade.',
  'One-Arm Kettlebell Push Press':
    'Suba o kettlebell ao ombro estendendo pernas e quadril, girando o punho até a palma ficar voltada para a frente: posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta de imediato empurrando pelos calcanhares, quase saltando, e empurre o kettlebell acima da cabeça até travar o braço; abaixe para a próxima repetição.',
  'One-Arm Kettlebell Row':
    'Com o kettlebell à frente dos pés, flexione os joelhos e leve o quadril para trás ao se inclinar; puxe o kettlebell ao abdômen retraindo a escápula e flexionando o cotovelo, costas retas. Abaixe e repita.',
  'One-Arm Kettlebell Snatch':
    'Coloque o kettlebell entre os pés, flexione os joelhos e leve o quadril para trás: posição inicial.\nOlhe para a frente e balance o kettlebell para trás, entre as pernas.\nInverta de imediato impulsionando com quadril e joelhos para acelerar o kettlebell para cima; na altura do ombro, gire a mão e empurre até travar o braço acima da cabeça.',
  'One-Arm Kettlebell Split Jerk':
    'Suba o kettlebell até o ombro estendendo pernas e quadril, girando o punho até a palma ficar voltada para a frente: posição inicial.\nDesça o corpo flexionando os joelhos, mantendo o tronco ereto.\nInverta de imediato empurrando pelos calcanhares, quase saltando, e empurre o kettlebell acima da cabeça até travar o braço com o impulso do corpo.\nReceba o peso acima da cabeça em agachamento, com uma perna à frente e outra atrás.\nCom o peso acima da cabeça, fique em pé juntando os pés e abaixe o peso para a próxima repetição.',
  'One-Arm Kettlebell Split Snatch':
    'Segure o kettlebell em uma mão pela alça.\nAgache e depois estenda quadril, joelhos e tornozelos, nessa ordem, para elevar o kettlebell acima da cabeça.\nEstenda o corpo por completo e desça em afundo (uma perna à frente, outra atrás), travando o kettlebell acima com o impulso do quadril.\nFique em pé, junte os pés com o peso travado acima da cabeça e abaixe o kettlebell até a posição inicial.',
  'One-Arm Long Bar Row':
    'Encaixe a barra em um landmine ou canto para fixá-la e carregue o peso na ponta.\nFique ao lado da barra, segure-a com uma mão perto do colar e fique em pé usando o quadril e as pernas.\nFlexione os joelhos, leve o quadril para trás e o peito erguido, com o braço estendido: essa é a posição inicial.\nPuxe o peso até o seu lado retraindo o ombro e flexionando o cotovelo, sem solavancos nem trapaça.\nFaça uma breve pausa e volte à posição inicial.',
  'One-Arm Medicine Ball Slam':
    'Fique em postura atlética com um pé à frente e segure a bola medicinal do lado da perna de trás.\nGire o braço para trás e eleve a bola acima da cabeça estendendo quadril, joelhos e tornozelos para pegar impulso.\nNo ponto máximo de extensão, flexione ombros, coluna e quadril e arremesse a bola com força no chão à sua frente.\nPegue a bola no rebote e repita o número de vezes indicado.',
  'One-Arm Open Palm Kettlebell Clean':
    'Coloque o kettlebell entre os pés.\nSegure a alça com uma mão e eleve o kettlebell rápido, deixando-o girar para a bola cair na sua palma.\nLance o kettlebell para a frente e pegue a alça com a mesma mão.\nLeve o kettlebell ao chão e repita, trabalhando os dois braços.',
  'One-Arm Overhead Kettlebell Squats':
    'Faça um clean e press de kettlebell com um braço: puxe-o ao ombro estendendo pernas e quadril, gire o punho e empurre o peso acima da cabeça estendendo o cotovelo.\nOlhando para a frente, com o kettlebell travado acima de você, flexione joelhos e quadril e desça o tronco entre as pernas com cabeça e peito erguidos.\nFaça uma pausa de um segundo embaixo e suba novamente empurrando pelos calcanhares.',
  'One-Arm Side Deadlift':
    'Fique de lado junto à barra, perto do centro dela, e flexione os joelhos para alcançá-la.\nSegure a barra como uma maleta, com a palma voltada para você; use munhequeira se o peso for alto. Essa é sua posição inicial.\nLevante a barra com as pernas enquanto expira, estendendo os braços por completo até ficar em pé.\nAbaixe a barra lentamente enquanto inspira, flexionando os joelhos para evitar lesões.\nRepita o número recomendado de repetições.\nTroque de braço e repita o movimento.',
  'One-Arm Side Laterals':
    'Segure um halter em uma mão e apoie-se com a outra em um banco inclinado, inclinando-se para o lado que levanta para manter o equilíbrio.\nFique em pé com o tronco reto e o halter ao lado do corpo, braço estendido e palma voltada para você. Essa é sua posição inicial.\nSem balançar o tronco, levante o halter para o lado com leve flexão no cotovelo, mão inclinada à frente, até o braço ficar paralelo ao chão; expire e pause um segundo no topo.\nAbaixe o halter lentamente até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'One-Legged Cable Kickback':
    'Prenda uma tornozeleira de couro a uma polia baixa e coloque-a no tornozelo.\nFique de frente para a pilha de pesos, a cerca de 60 cm, segurando a estrutura de aço.\nCom joelhos e quadril levemente flexionados e abdômen contraído, leve a perna de trabalho para trás em arco semicircular expirando e apertando o glúteo por um segundo no topo.\nTraga a perna de trabalho para a frente lentamente, resistindo ao cabo, até a posição inicial.\nRepita o número recomendado de repetições.\nTroque de perna e repita do outro lado.',
  'Open Palm Kettlebell Clean':
    'Coloque o kettlebell entre os pés e eleve-o estendendo pernas e quadril em direção aos ombros.\nSolte o kettlebell enquanto sobe, deixando-o girar para a bola cair nas suas palmas.\nPegue o kettlebell à frente com as duas mãos, abaixe-o até a posição inicial e repita.',
  'Otis-Up':
    'Deite-se de costas com os pés presos e os joelhos flexionados, segurando um peso junto ao peito com as duas mãos. Essa é sua posição inicial.\nFlexione o quadril e a coluna para levantar o tronco do chão.\nAo subir, empurre o peso acima da cabeça na parte alta do movimento.\nTraga o peso de volta ao peito invertendo o movimento abdominal, sem descer o tronco até o chão.',
  'Overhead Cable Curl':
    'Ajuste o mesmo peso nos dois lados da máquina de polia.\nAjuste a altura das duas polias acima dos ombros.\nFique no centro, segure cada alça com pegada supinada (palmas para o teto), braços estendidos e paralelos ao chão, pés na largura dos ombros. Essa é a posição inicial.\nExpire e contraia lentamente os bíceps de cada lado até os antebraços e bíceps se tocarem.\nInspire e leve os antebraços de volta à posição inicial, mantendo o resto do corpo parado.\nRepita o número recomendado de repetições do seu programa.',
  'Overhead Lat':
    'Sente-se ereto no chão com seu parceiro atrás; levante um braço e flexione o cotovelo tentando encostar a mão nas costas, enquanto ele segura seu tríceps e punho. Essa é sua posição inicial.\nTente puxar o braço para o lado do corpo enquanto seu parceiro impede.\nApós 10 a 20 segundos, relaxe o braço e deixe seu parceiro alongar mais o dorsal com pressão suave no tríceps; segure 10 a 20 segundos e troque de lado.',
  'Overhead Slam':
    'Segure a bola medicinal com as duas mãos, pés na largura dos ombros. Essa é sua posição inicial.\nEleve a bola acima da cabeça estendendo o corpo por completo como contramovimento.\nInverta o movimento e arremesse a bola no chão à sua frente com toda a força.\nReceba a bola com as duas mãos no rebote e repita.',
  'Overhead Squat':
    'Fique com a barra no chão à sua frente, pés mais afastados que a largura dos ombros.\nFlexione os joelhos e segure a barra com pegada pronada mais larga que os ombros; levante-a até apoiá-la no peito.\nLeve a barra acima da cabeça, levemente atrás, braços estendidos, cabeça erguida, costas retas e escápulas retraídas. Essa é sua posição inicial.\nInspire e desça flexionando os joelhos até as coxas ficarem paralelas ao chão, mantendo as costas retas e os braços estendidos acima da cabeça.\nExpire e use os pés e as pernas para subir o peso de volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Overhead Stretch':
    'Em pé e reto, entrelace os dedos com as palmas para o teto e estenda os braços para cima, ombros para baixo.\nPuxe o cóccix para baixo e estabilize o tronco para alongar por completo a frente e as costas do tronco.',
  'Overhead Triceps':
    'Sente-se ereto no chão com seu parceiro atrás; levante um braço e flexione o cotovelo tentando encostar a mão nas costas, enquanto ele segura seu cotovelo e punho. Essa é sua posição inicial.\nTente estender o braço para cima enquanto seu parceiro impede.\nApós 10 a 20 segundos, relaxe o braço e deixe seu parceiro alongar mais o tríceps com pressão suave no punho; segure 10 a 20 segundos e troque de lado.',
  'Pallof Press':
    'Conecte uma alça a uma torre com o cabo na altura dos ombros (ou use uma polia baixa se não for possível).\nDe lado para o cabo, segure a alça com as duas mãos e afaste-se a um braço de distância, com tensão no cabo.\nPés na largura do quadril, joelhos levemente flexionados, segure o cabo na altura do meio do peito. Essa é sua posição inicial.\nEmpurre o cabo para longe do peito estendendo os dois braços por completo, com o core firme e ativado.\nSegure a posição por vários segundos antes de voltar à posição inicial.\nAo final da série, repita virado para o lado oposto.',
  'Pallof Press With Rotation':
    'Conecte uma alça a uma torre com o cabo na altura dos ombros.\nDe lado para o cabo, segure a alça com uma mão e afaste-se a um braço de distância, alinhando o braço estendido com o cabo.\nPés na largura do quadril, puxe o cabo até o peito e segure a alça também com a outra mão.\nDe frente, empurre o cabo para longe do peito com o core firme e ativado.\nCom o quadril reto, gire o tronco para longe da polia um quarto de volta.\nCom postura firme e braços retos, volte devagar à posição neutra com os braços estendidos à frente.\nCom tensão lateral no core, leve as mãos ao peito e empurre imediatamente até a extensão completa: isso é uma repetição.\nRepita até a falha.\nReposicione-se e repita a mesma sequência do lado oposto.',
  'Palms-Down Dumbbell Wrist Curl Over A Bench':
    'Coloque dois halteres em um dos lados de um banco plano.\nAjoelhe-se com os dois joelhos, de frente para o banco.\nSegure os dois halteres com pegada pronada (palmas para baixo) e apoie os antebraços no banco, com os punhos pendurados na borda.\nExpire e flexione os punhos para cima.\nInspire e abaixe os punhos lentamente até a posição inicial.\nMantenha os antebraços parados; só o punho se move neste exercício.\nRepita o número recomendado de repetições.',
  'Palms-Down Wrist Curl Over A Bench':
    'Coloque uma barra em um dos lados de um banco plano.\nAjoelhe-se com os dois joelhos, de frente para o banco.\nSegure a barra com pegada pronada (palmas para baixo) e apoie os antebraços no banco, com os punhos pendurados na borda.\nExpire e flexione os punhos para cima.\nInspire e abaixe os punhos lentamente até a posição inicial.\nMantenha os antebraços parados; só o punho se move neste exercício.\nRepita o número recomendado de repetições.',
  'Palms-Up Barbell Wrist Curl Over A Bench':
    'Coloque uma barra em um dos lados de um banco plano.\nAjoelhe-se com os dois joelhos, de frente para o banco.\nSegure a barra com pegada supinada (palmas para cima) e apoie os antebraços no banco, com os punhos pendurados na borda.\nExpire e flexione os punhos para cima.\nInspire e abaixe os punhos lentamente até a posição inicial.\nMantenha os antebraços parados; só o punho se move neste exercício.\nRepita o número recomendado de repetições.',
  'Palms-Up Dumbbell Wrist Curl Over A Bench':
    'Coloque dois halteres em um dos lados de um banco plano.\nAjoelhe-se com os dois joelhos, de frente para o banco.\nSegure os dois halteres com pegada supinada (palmas para cima) e apoie os antebraços no banco, com os punhos pendurados na borda.\nExpire e flexione os punhos para cima.\nInspire e abaixe os punhos lentamente até a posição inicial, inspirando durante o movimento.\nMantenha os antebraços parados; só o punho se move neste exercício.\nRepita o número recomendado de repetições.',
  'Parallel Bar Dip':
    'Fique entre as barras paralelas, apoie uma mão em cada uma e dê um salto leve para chegar com os braços travados. Essa é sua posição inicial.\nFlexione os cotovelos e abaixe o corpo até passar de 90 graus, sem balançar e com boa postura.\nEstenda os cotovelos para se empurrar de volta à posição inicial.\nRepita o número de repetições desejado.',
  'Pelvic Tilt Into Bridge':
    'Deite-se com os pés no chão e os calcanhares bem abaixo dos joelhos.\nLevante apenas o cóccix em direção ao teto para alongar a lombar (sem levantar toda a coluna ainda) e contraia o abdômen.\nLevante toda a coluna, exceto o pescoço, para passar a uma ponte.',
  'Peroneals Stretch':
    'Sentado, passe um cinto, corda ou faixa ao redor de um dos pés. Essa é sua posição inicial.\nCom a perna estendida e o calcanhar fora do chão, puxe o cinto para inverter o pé, trazendo sua parte interna em sua direção; segure 10 a 20 segundos e troque de lado.',
  'Peroneals-SMR':
    'Deite-se de lado apoiando o peso no antebraço e em um rolo de espuma sob a parte externa da perna de baixo, com a perna de cima sobre ela ou cruzada à frente. Essa é sua posição inicial.\nLevante o quadril do chão e role de baixo do joelho até acima do tornozelo, pausando 10 a 30 segundos nos pontos de tensão; repita na outra perna.',
  'Physioball Hip Bridge':
    'Deite-se sobre uma bola com a parte superior das costas apoiada, quadril sem apoio e os dois pés apoiados no chão, na largura do quadril ou mais. Essa é sua posição inicial.\nEstenda o quadril com os glúteos e os posteriores de coxa, elevando-o ao fazer a ponte.\nFaça uma pausa no topo e volte à posição inicial.',
  'Pin Presses':
    'O supino com pinos elimina a fase excêntrica do supino e desenvolve a força de arranque, treinando uma amplitude específica.\nPosicione o banco dentro de um power rack, ajuste os pinos no ponto desejado (travamento ou uma polegada do peito) e apoie a barra sobre eles, pronta para levantar.\nDeite-se com a barra acima do seu ponto de contato habitual, pés recolhidos e costas arqueadas; tire os ombros do banco, retraia as escápulas e pressione o trapézio com os pés.\nUse uma pegada padrão de supino ou na largura dos ombros para enfatizar os tríceps, mantendo barra, punho e cotovelo alinhados.\nEmpurre a barra para cima com o máximo de força, mantendo os cotovelos junto ao corpo até o travamento.\nDevolva a barra aos pinos e pause antes da próxima repetição.',
  'Piriformis-SMR':
    'Sente-se com os glúteos sobre um rolo de espuma, joelhos flexionados e uma perna cruzada com o tornozelo sobre o joelho. Essa é sua posição inicial.\nTransfira o peso para o lado da perna cruzada e role sobre o glúteo até sentir tensão no topo; você pode puxar o joelho ao peito com uma mão. Mantenha 10 a 30 segundos e troque de lado.',
  Plank:
    'Fique de bruços apoiando o peso nos dedos dos pés e nos antebraços, com os braços flexionados diretamente abaixo dos ombros.\nMantenha o corpo reto e sustente a posição pelo maior tempo possível; levante um braço ou uma perna para aumentar a dificuldade.',
  'Plate Pinch':
    'Pegue duas anilhas de borda larga e junte-as com os lados lisos voltados para fora.\nSegure a anilha com os dedos de um lado e o polegar do outro, mantendo as duas juntas: posição inicial.\nAperte a anilha com os dedos e o polegar, e mantenha a posição pelo maior tempo possível.\nRepita o número de séries indicado no seu programa.\nTroque de braço e repita o movimento.',
  'Plate Twist':
    'Sente-se com as pernas estendidas, tronco ereto e braços levemente flexionados, segurando a anilha à frente do abdômen.\nCruze os tornozelos, levante as pernas (joelhos flexionados) e incline o tronco para trás para equilíbrio: posição inicial.\nLeve a anilha para o lado esquerdo e toque o chão, expirando no movimento.\nVolte inspirando à posição inicial e repita para o lado direito, com movimento lento e controlado para não lesionar as costas.\nRepita o número de repetições recomendado.',
  'Platform Hamstring Slides':
    'Deite-se de costas em piso de madeira, pernas estendidas, com uma toalha ou peso leve sob o calcanhar: posição inicial.\nComece flexionando o joelho, mantendo a outra perna reta.\nContinue deslizando o calcanhar em sua direção pelo chão.\nNa flexão completa do joelho, inverta o movimento e volte à posição inicial.',
  'Plie Dumbbell Squat':
    'Segure um halter pela base com as duas mãos, em pé, pernas mais afastadas que os ombros e joelhos levemente flexionados.\nAponte as pontas dos pés para fora e mantenha os braços parados: posição inicial.\nFlexione lentamente os joelhos até as coxas ficarem paralelas ao chão, inspirando nesta fase excêntrica.\nEmpurre principalmente com o calcanhar para voltar à posição inicial, expirando.\nRepita o número de repetições recomendado.',
  'Plyo Kettlebell Pushups':
    'Fique em flexão na ponta dos pés, uma mão no chão e outra no kettlebell no chão, cotovelos estendidos: posição inicial.\nComece descendo o máximo que puder, mantendo as costas retas.\nEmpurre rápido e explosivo para o outro lado do kettlebell, trocando de mão, e repita descendo e alternando de lado.',
  'Plyo Push-up':
    'Fique em posição de bruços no chão, apoiando seu peso nas mãos e na ponta dos pés.\nEstenda os braços com as mãos na largura dos ombros e mantenha o corpo reto: posição inicial.\nDesça flexionando os cotovelos, abaixando o peito em direção ao chão.\nNa parte de baixo, empurre rápido estendendo os cotovelos até as mãos saírem do chão.\nVolte à posição inicial e repita o exercício.\nPara mais dificuldade, acrescente palmas ao movimento enquanto estiver no ar.',
  'Posterior Tibialis Stretch':
    'Sentado, passe um cinto, corda ou faixa ao redor de um dos pés: posição inicial.\nCom a perna estendida, calcanhar fora do chão, puxe o cinto para everter o pé em sua direção; mantenha 10-20 s e troque de lado.',
  'Power Clean':
    'Fique em pé com os pés um pouco mais afastados que os ombros e pontas dos pés levemente para fora.\nAgache e segure a barra com pegada pronada fechada, mãos um pouco mais afastadas que os ombros, fora dos joelhos, cotovelos estendidos.\nPosicione a barra a cerca de 2,5 cm na frente das canelas, sobre a parte da frente dos pés.\nMantenha as costas planas ou levemente arqueadas, peito erguido e para fora, e escápulas retraídas.\nMantenha a cabeça neutra, alinhada com a coluna, olhar para frente, e inspire nesta fase.\nEstenda com força o quadril e os joelhos para levantar a barra, expirando; mantenha o ângulo do tronco e não deixe o quadril subir antes dos ombros.\nMantenha os cotovelos totalmente estendidos, a cabeça neutra e os ombros sobre a barra.\nEnquanto a barra sobe, mantenha-a o mais próxima possível das canelas.\nQuando a barra passar pelos joelhos, projete o quadril para frente e flexione levemente os joelhos (sem travá-los); as coxas devem tocar a barra.\nMantenha as costas planas ou levemente arqueadas, cotovelos estendidos e cabeça neutra; prenda a respiração até a próxima fase.\nInspire e depois estenda com força e rapidez o quadril e os joelhos, ficando na ponta dos pés.\nMantenha a barra colada ao corpo, costas planas, cotovelos para os lados, cabeça neutra, ombros sobre a barra e braços retos pelo maior tempo possível.\nCom as pernas e o quadril já estendidos, encolha os ombros rápido sem flexionar os cotovelos, expirando.\nQuando os ombros atingirem a elevação máxima, flexione os cotovelos para começar a puxar o corpo sob a barra.\nContinue puxando com os braços o mais alto e por mais tempo possível; o tronco ficará ereto ou arqueado, a cabeça um pouco para trás e os pés podem sair do chão.\nCom a parte inferior já estendida e a barra perto da altura máxima, puxe o corpo para baixo da barra e gire os braços por baixo dela.\nAo mesmo tempo, flexione o quadril e os joelhos até uma posição de um quarto de agachamento.\nCom os braços sob a barra, inspire e levante os cotovelos até os braços ficarem paralelos ao chão; apoie a barra nas clavículas e ombros frontais.\nReceba a barra com o tronco ereto e firme, cabeça neutra e pés apoiados por completo, expirando.\nFique em pé estendendo o quadril e os joelhos até a posição totalmente ereta.\nAbaixe a barra de forma controlada, reduzindo gradualmente a tensão dos braços até as coxas, inspirando.\nAo mesmo tempo, flexione o quadril e os joelhos para amortecer o impacto da barra nas coxas.\nAgache com os cotovelos totalmente estendidos até a barra tocar o chão.\nRecomece na Fase 1 e repita o número de repetições recomendado.',
  'Power Clean from Blocks':
    'Com a barra sobre as caixas, pegada um pouco além das pernas, quadril baixo, peso nos calcanhares, costas retas e ombros à frente da barra: posição inicial.\nInicie a primeira puxada empurrando com os calcanhares e estendendo os joelhos, costas e braços fixos; quando a barra chegar ao meio da coxa, estenda o quadril.\nAcelere como um salto estendendo quadril, joelhos e tornozelos sem puxar com os braços; ao final da segunda puxada o corpo fica estendido, levemente inclinado para trás, braços retos.\nNa terceira puxada, encolha os ombros com força e flexione os braços (cotovelos para cima e para fora); entre sob a barra e apoie-a nos ombros protraídos, perto da garganta, mãos relaxadas.\nRecupere-se empurrando com os calcanhares, tronco ereto e cotovelos para cima, até ficar em pé, e devolva o peso às caixas.',
  'Power Jerk':
    'Em pé com a barra nos ombros, pés sob o quadril, flexione um pouco os joelhos (sem levar o quadril para trás) e inverta o movimento com máxima potência.\nEmpurre com os calcanhares para máxima velocidade e força, tirando a cabeça do caminho quando a barra sair dos ombros.\nAo tirar os pés do chão, leve-os rápido para a posição de recepção, um pouco mais larga, com joelhos parcialmente flexionados.\nReceba a barra com os braços totalmente estendidos acima da cabeça.\nVolte à posição em pé.',
  'Power Partials':
    'Fique em pé, tronco ereto, um halter em cada mão, braços estendidos e cotovelos próximos ao tronco.\nPalmas voltadas para o tronco e pés na largura dos ombros: posição inicial.\nCom braços retos e tronco parado, levante os halteres para os lados até a altura dos ombros, expirando.\nContraia por um segundo e abaixe os halteres inspirando; mantenha as palmas para baixo com o mínimo um pouco mais alto para focar a tensão nos ombros.\nRepita pelo número de repetições recomendado.',
  'Power Snatch':
    'Com a barra no chão perto das canelas, pegada aberta, pés sob o quadril, quadril baixo, peito erguido e ombros à frente da barra: posição inicial.\nInicie a primeira puxada empurrando com a frente dos calcanhares, mantendo o ângulo das costas até a barra passar pelos joelhos.\nNa segunda puxada, estenda quadril, joelhos e tornozelos subindo a barra rápido e próxima ao corpo; na extensão máxima, encolha os ombros e flexione os cotovelos para os lados.\nLeve os pés para uma posição um pouco mais larga, entre sob a barra e receba-a em um agachamento parcial, com os braços totalmente estendidos acima da cabeça.\nVolte à posição em pé com o peso acima da cabeça.',
  'Power Snatch from Blocks':
    'Com a barra sobre caixas ou suportes, pegada aberta, pés sob o quadril, quadril baixo, peito erguido, ombros à frente da barra e cotovelos para fora: posição inicial.\nInicie a primeira puxada empurrando com a frente dos calcanhares, tirando a barra das caixas.\nNa segunda puxada, estenda quadril, joelhos e tornozelos subindo a barra rápido e próxima ao corpo; na extensão máxima, encolha os ombros e flexione os cotovelos para os lados.\nEntre com força sob a barra levando os pés logo fora do quadril, e receba-a acima de um agachamento completo, com os braços estendidos acima da cabeça.\nCom a barra alinhada sobre a frente dos calcanhares, cabeça e peito erguidos, empurre com os calcanhares até ficar em pé e devolva o peso às caixas.',
  'Power Stairs':
    'Mova um implemento escada acima; para treinar, use um pneu ou uma caixa.\nSegure o implemento com as duas mãos, pés bem afastados, cabeça e peito erguidos; empurre com os calcanhares estendendo joelhos e quadril para levantá-lo.\nIncline-se para trás e lance o peso sobre o degrau (16-18 polegadas de altura), ajudando com as pernas.\nRepita de 3 a 5 repetições e continue com um peso maior, movendo-se o mais rápido possível.',
  'Preacher Curl':
    'No banco Scott, segure a barra W pela pegada interna mais próxima, palmas para frente, levemente inclinadas para dentro.\nApoie os braços e o peito no estofado do banco, segurando a barra W na altura dos ombros: posição inicial.\nInspire e abaixe lentamente a barra até estender o braço e alongar totalmente o bíceps.\nExpire e suba a barra com o bíceps até contraí-lo totalmente na altura dos ombros; aperte por um segundo.\nRepita pelo número de repetições recomendado.',
  'Preacher Hammer Dumbbell Curl':
    'Apoie os braços sobre o banco Scott, segurando um halter em cada mão com pegada neutra (palmas uma para a outra).\nInspire e abaixe lentamente os halteres até estender o braço e alongar totalmente o bíceps.\nExpire e suba os halteres com o bíceps até contraí-lo totalmente na altura dos ombros.\nAperte o bíceps com força por um segundo na contração e repita pelo número de repetições recomendado.',
  'Press Sit-Up':
    'Deite-se em um banco com a barra sobre o peito e as pernas presas na extensão do banco abdominal: posição inicial.\nInspire contraindo abdômen e glúteos, enrole o tronco como em um abdominal e empurre a barra acima da cabeça com os braços ao expirar, focando no abdômen.\nAbaixe o tronco à posição inicial trazendo a barra de volta ao corpo, inspirando.\nRepita pelo número de repetições recomendado.',
  'Prone Manual Hamstring':
    'Com um parceiro, deite-se de bruços com as pernas retas; ele coloca a mão sobre o seu calcanhar.\nFlexione o joelho em um curl enquanto seu parceiro oferece resistência crescente; comunique-se para ajustar a pressão.\nFaça uma pausa no topo e volte à posição inicial enquanto seu parceiro oferece resistência na direção contrária.',
  'Prowler Sprint':
    'Carregue o trenó em uma superfície adequada com um peso que exija esforço sem deixar você muito lento.\nSegure as alças verticais ou baixas com os braços estendidos, inclinando-se sobre o trenó.\nCom boa postura, empurre o chão com passos curtos e alternados, movendo-se o mais rápido possível por uma distância curta.',
  'Pull Through':
    'Em pé, de costas para uma polia baixa com corda ou alça, cabo entre as pernas e pés bem afastados.\nAlcance entre as pernas flexionando o quadril (joelhos levemente flexionados) e estenda-o com braços retos até ficar em pé, sem puxar com os ombros.',
  Pullups:
    'Segure a barra com as palmas para frente: pegada aberta (mais larga que os ombros), média (igual aos ombros) ou fechada (mais estreita que os ombros).\nCom os braços estendidos, incline o tronco 30 graus para trás, arqueando a lombar e projetando o peito: posição inicial.\nPuxe até a barra tocar o peito, levando ombros e braços para baixo e para trás, expirando; contraia as costas no topo e mova só os braços, sem usar os antebraços.\nApós um segundo na contração, inspire e desça lentamente à posição inicial com os braços estendidos e os dorsais alongados.\nRepita esse movimento pelo número de repetições indicado.',
  'Push Press - Behind the Neck':
    'Em pé com a barra na nuca, flexione um pouco os joelhos sem levar o quadril para trás e inverta com máxima potência, empurrando com os calcanhares em trajetória vertical.\nAproveitando o impulso, termine de empurrar o peso acima da cabeça estendendo os braços.\nVolte à posição inicial, usando as pernas para absorver o impacto.',
  'Push Up to Side Plank':
    'Fique em posição de flexão sobre as pontas dos pés, mãos um pouco além da largura dos ombros.\nFaça uma flexão permitindo que os cotovelos flexionem; ao descer, mantenha o corpo reto.\nFaça uma flexão e, ao subir, passe o peso para o lado esquerdo, gire e leve o braço direito ao teto em prancha lateral.\nAbaixe o braço de volta ao chão para outra flexão e gire para o outro lado.\nRepita a série, alternando os lados, por 10 repetições ou mais.',
  'Push-Up Wide':
    'Com as mãos bem afastadas, apoie-se em prancha sobre as pontas dos pés e as mãos, cotovelos estendidos, corpo reto e quadril sem cair: posição inicial.\nPara começar, permita que os cotovelos flexionem, abaixando o peito em direção ao chão, inspirando.\nCom os peitorais, empurre estendendo os cotovelos de volta à posição inicial, expirando.\nApós uma pausa na contração, repita o movimento pelo número de repetições indicado.',
  'Push-Ups - Close Triceps Position':
    'De bruços, coloque as mãos mais próximas que os ombros (pegada fechada) e sustente o tronco com os braços estendidos.\nDesça até o peito quase tocar o chão, inspirando.\nCom tríceps e peitorais, empurre de volta à posição inicial contraindo o peito, expirando.\nApós uma pausa de um segundo na contração, repita o movimento pelo número de repetições indicado.',
  'Push-Ups With Feet Elevated':
    'De bruços, coloque as mãos cerca de 36 polegadas afastadas e sustente o tronco com os braços estendidos.\nColoque os dedos dos pés sobre um banco reto para elevar o corpo; quanto maior a altura do banco, maior a resistência.\nDesça até o peito quase tocar o chão, inspirando.\nCom os peitorais, empurre de volta à posição inicial contraindo o peito, expirando.\nApós uma pausa de um segundo na contração, repita o movimento pelo número de repetições indicado.',
  'Push-Ups With Feet On An Exercise Ball':
    'De bruços, coloque as mãos cerca de 36 polegadas afastadas e sustente o tronco com os braços estendidos.\nColoque os dedos dos pés sobre uma bola de exercício para elevar o corpo.\nDesça até o peito quase tocar o chão, inspirando.\nCom os peitorais, empurre de volta à posição inicial contraindo o peito, expirando.\nApós uma pausa de um segundo na contração, repita o movimento pelo número de repetições indicado.',
  Pushups:
    'De bruços, coloque as mãos cerca de 36 polegadas afastadas e sustente o tronco com os braços estendidos.\nAbaixe o corpo até o peito quase tocar o chão, inspirando.\nExpire e empurre o corpo de volta à posição inicial contraindo o peito.\nApós uma breve pausa na contração, repita a descida pelo número de vezes necessário.',
  'Pushups (Close and Wide Hand Positions)':
    'De bruços, corpo reto; mãos mais afastadas que os ombros (pegada aberta) ou mais próximas (pegada fechada), tronco sustentado com braços estendidos.\nDesça até o peito quase tocar o chão, inspirando.\nCom os peitorais, empurre de volta à posição inicial contraindo o peito, expirando.\nApós uma pausa de um segundo na contração, repita o movimento pelo número de repetições indicado.',
  Pyramid:
    'Role o tronco para frente sobre a bola até o quadril descansar sobre ela, como o ponto mais alto do corpo.\nApoie as mãos e os pés no chão com braços e pernas retos ou levemente flexionados (conforme a bola e sua flexibilidade); desenvolve estabilidade no tronco e nos ombros.',
  'Quad Stretch':
    'Deite-se de lado, passe uma faixa ao redor do pé de cima e flexione o joelho levando o pé em direção aos glúteos.\nPuxe a faixa sobre o ombro ou a cabeça para aumentar o alongamento do quadríceps; mantenha 10-20 segundos e troque de lado.',
  'Quadriceps-SMR':
    'Deite-se de bruços apoiado nas mãos ou antebraços, coloque um rolo de espuma sob o quadríceps e mantenha o pé fora do chão, a perna relaxada.\nTransfira o máximo de peso tolerável para essa perna e role o rolo desde acima do joelho até abaixo do quadril, mantendo 10-30 segundos nos pontos de tensão; troque de lado.',
  'Quick Leap':
    'Use uma caixa para este exercício.\nFique de frente para a caixa, a 1-2 pés de distância da borda.\nSalte sobre a caixa usando o quadril e aterrisse com as duas pernas flexionadas e os pés apoiados no chão.\nAo aterrissar, estenda todo o corpo e lance os braços acima da cabeça para saltar com explosão da caixa; absorva o impacto com as pernas.',
  'Rack Delivery':
    'Segure a barra na posição de espantalho: braços superiores paralelos ao chão, antebraços pendendo e pegada em gancho com os dedos sobre os polegares.\nGire os cotovelos ao redor da barra levando-a aos ombros, relaxando a pegada; os ombros devem protrair formando uma prateleira onde a barra toque levemente a garganta.\nMantenha a barra próxima ao corpo para evitar colisões; ao dominar o movimento, aumente velocidade e carga antes de avançar.',
  'Rack Pull with Bands':
    'Em um rack de potência, posicione a barra sobre os pinos na altura desejada (abaixo dos joelhos, acima ou no meio da coxa); prenda as faixas na base do rack ou em halteres e a outra extremidade na barra.\nPosicione-se na posição de levantamento terra: pés sob o quadril, pegada na largura dos ombros, costas arqueadas e quadril para trás; use pegada mista, em gancho ou straps se o peso for elevado.\nOlhando para a frente, estenda quadril e joelhos puxando o peso até a extensão completa, levando os ombros para trás; devolva o peso aos pinos e repita.',
  'Rack Pulls':
    'No rack, apoie a barra sobre os pinos (abaixo dos joelhos, acima ou no meio da coxa) e assuma a posição de levantamento terra: pés sob o quadril, pegada na largura dos ombros, costas arqueadas; use pegada mista, em gancho ou straps com cargas altas.\nOlhando para a frente, estenda quadril e joelhos puxando o peso até a extensão completa, levando os ombros para trás.\nDevolva o peso aos pinos e repita.',
  'Rear Leg Raises':
    'Apoie-se de quatro, com a cabeça para a frente e os joelhos flexionados a 90 graus entre os posteriores de coxa e as panturrilhas.\nEstenda uma perna para cima e para trás, estendendo joelho e quadril; repita 5-10 vezes e troque de lado.',
  'Recumbent Bike':
    'Sente-se na bicicleta e ajuste o assento à sua altura.\nSelecione o modo manual ou um programa no menu (pode ser necessário pedalar para ligar); insira idade e peso para estimar calorias e ajuste a resistência durante o treino.\nÉ de baixo impacto e boa opção cardiovascular: uma pessoa de 150 lbs queima cerca de 230 calorias em 30 minutos em ritmo moderado, contra 450 ou mais correndo.',
  'Return Push from Stance':
    'Você precisa de um parceiro para este exercício.\nComece em postura atlética de 2 ou 3 apoios.\nAo sinal, mova-se para receber o passe do seu parceiro.\nPegue a bola medicinal com as duas mãos e devolva-a imediatamente.\nModifique o exercício correndo por trajetos diferentes.',
  'Reverse Band Bench Press':
    'Em um rack de potência, prenda as faixas nos suportes ou na parte superior do rack e a outra extremidade na barra sobre o banco.\nDeite-se, recolha os pés, arqueie as costas e retraia os ombros apertando as escápulas; pressione o trapézio contra o banco com os pés e mantenha a tensão o movimento todo.\nRetire a barra sem protrair os ombros, aperte a barra tentando separá-la e abaixe até a parte inferior do peito, com barra, punho e cotovelo alinhados.\nPause ao tocar o tronco e empurre a barra para cima com força máxima, cotovelos junto ao corpo até a extensão completa.',
  'Reverse Band Box Squat':
    'Em um rack de potência com uma caixa atrás na altura adequada, prenda as faixas sobre a barra (suportes ou topo do rack) e a outra extremidade na barra.\nApoie a barra na parte de trás dos ombros apertando as escápulas e girando os cotovelos para frente; retire do rack, arqueie a lombar e dê um passo atrás, pés mais afastados para costas/glúteos/adutores/posteriores ou mais próximos para quadríceps.\nCom costas, ombros e core firmes, empurre joelhos e glúteos para fora e sente-se até a caixa, canelas perpendiculares ao chão; pause e relaxe os flexores do quadril sem quicar.\nCom o peso nos calcanhares empurrando pés e joelhos para fora, suba da caixa conduzindo com a cabeça, mantendo tensão da cabeça aos pés; cuidado ao devolver a barra ao rack.',
  'Reverse Band Deadlift':
    'Em um rack de potência, prenda as faixas na parte superior do rack e a outra extremidade na barra.\nAproxime-se com a barra centralizada sobre os pés (na largura do quadril); flexione o quadril e segure a barra na largura dos ombros com pegada pronada ou mista em séries pesadas.\nRespire fundo, abaixe o quadril e flexione os joelhos até as canelas tocarem a barra; olhe para a frente, peito erguido, costas arqueadas, e empurre com os calcanhares.\nAo passar a barra pelos joelhos, puxe-a para trás juntando as escápulas enquanto leva o quadril para frente contra a barra.\nAbaixe a barra flexionando o quadril e guiando-a até o chão.',
  'Reverse Band Power Squat':
    'Em um rack de potência com pinos e barra na altura adequada, carregue a barra e prenda as faixas no topo do rack, com a outra extremidade na barra.\nApoie a barra atrás dos ombros apertando as escápulas e girando os cotovelos para frente; retire do rack, arqueie a lombar, dê um passo atrás com os pés bem afastados para costas, glúteos, adutores e posteriores.\nOlhando para a frente, com costas, ombros e core firmes, empurre joelhos e glúteos para fora e sente-se para trás o máximo possível, canelas perpendiculares ao chão; uma barra mais baixa exige mais inclinação de tronco; desça até quebrar o paralelo (dobra do quadril no nível do joelho).\nSuba conduzindo com a cabeça, mantendo tensão da cabeça aos pés com peso nos calcanhares e empurrando pés e joelhos para fora, até voltar à posição inicial.',
  'Reverse Band Sumo Deadlift':
    'Em um rack de potência, prenda as faixas no topo do rack e a outra extremidade na barra carregada no chão.\nAproxime-se com a barra cruzando o meio dos pés, bem afastados perto dos colares; flexione o quadril e segure a barra com os braços sob os ombros, por dentro das pernas, pegada pronada, mista ou em gancho, ombros relaxados.\nRespire fundo, abaixe o quadril olhando para a frente com o peito erguido; empurre o chão afastando os pés para os lados, peso na metade de trás dos pés, estendendo quadril e joelhos.\nAo passar a barra pelos joelhos, incline-se para trás levando o quadril contra a barra e juntando as escápulas.\nAbaixe o peso ao chão flexionando o quadril e controlando a descida.',
  'Reverse Barbell Curl':
    'Em pé e ereto, segure a barra na largura dos ombros com pegada pronada e cotovelos próximos ao tronco.\nSem mover a parte superior dos braços, suba a barra contraindo o bíceps ao expirar até a altura dos ombros; mantenha a contração por um segundo.\nAbaixe lentamente a barra à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Barbell Preacher Curls':
    'Segure uma barra W com pegada pronada na largura dos ombros.\nApoie a parte superior de ambos os braços no banco Scott com os braços estendidos.\nAo expirar, suba a barra na rosca com o bíceps até a altura dos ombros e aperte por um segundo.\nAo inspirar, abaixe lentamente a barra até estender os braços e alongar totalmente o bíceps.\nRepita pelo número de repetições recomendado.',
  'Reverse Cable Curl':
    'Em pé e ereto, segure um acessório de barra na polia baixa com pegada pronada na largura dos ombros e cotovelos próximos ao tronco.\nSem mover a parte superior dos braços, suba o peso contraindo o bíceps ao expirar até a altura dos ombros; aperte por um segundo.\nAbaixe lentamente à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Crunch':
    'Deite-se com as pernas estendidas e os braços ao lado do corpo, palmas no chão; mantenha os braços parados durante o exercício.\nSuba as pernas até as coxas ficarem perpendiculares ao chão e os pés juntos e paralelos ao chão.\nAo inspirar, leve as pernas ao tronco girando a pelve para trás e elevando o quadril do chão, até os joelhos tocarem o peito.\nMantenha a contração por um segundo e volte as pernas à posição inicial ao expirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Flyes':
    'Deite-se de bruços em um banco inclinado, peito e abdômen apoiados, e segure halteres com pegada neutra.\nEstenda os braços à frente, perpendiculares ao banco, pernas paradas apoiando a ponta dos pés.\nCom os cotovelos levemente flexionados, abra os pesos para os lados em arco ao expirar, apertando as escápulas.\nEleve os braços até ficarem paralelos ao chão.\nSinta a contração e abaixe lentamente os pesos ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Flyes With External Rotation':
    'Deite-se de bruços em um banco inclinado a 30 graus, peito e abdômen apoiados.\nSegure halteres com as palmas para o chão, braços à frente e perpendiculares ao banco, cotovelos com leve flexão; pernas paradas apoiando a ponta dos pés, calcanhares sem tocar o chão.\nCom os cotovelos levemente flexionados, abra os pesos para os lados em arco ao expirar.\nAo subir o peso, gire o punho 90 graus de pegada pronada para pegada neutra, apertando as escápulas.\nEleve os braços até a altura da cabeça.\nSinta a contração e abaixe lentamente os pesos ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Grip Bent-Over Rows':
    'Em pé e ereto, segure a barra com pegada supinada.\nFlexione levemente os joelhos, incline o tronco para frente com as costas retas quase paralelas ao chão e a cabeça erguida; a barra fica à frente com os braços perpendiculares ao chão.\nSem mover o tronco, levante a barra ao expirar com os cotovelos próximos ao corpo, sem forçar o antebraço; aperte as costas no topo e mantenha por um segundo.\nAbaixe lentamente o peso à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Grip Triceps Pushdown':
    'Prenda um acessório de barra (reta ou W) em uma polia alta.\nDe frente, segure-o com pegada supinada na largura dos ombros e abaixe a barra com os dorsais até estender os braços, cotovelos junto ao corpo, pés na largura dos ombros.\nSuba lentamente o acessório ao inspirar até alinhá-lo com o peito, movendo somente os antebraços.\nAbaixe a barra à posição inicial ao expirar, contraindo os tríceps com força.\nRepita pelo número de repetições recomendado.',
  'Reverse Hyperextension':
    'Carregue o peso apropriado, coloque os pés entre as almofadas e deite-se sobre a almofada superior, quadril pendurado para trás, segurando as alças.\nFlexione o quadril levando as pernas para a frente.\nEstenda o quadril chutando a perna para trás, sem hiperestender, parando antes da amplitude total.\nFlexione o quadril novamente levando o carrinho para a frente o máximo possível.\nRepita pelo número de repetições desejado.',
  'Reverse Machine Flyes':
    'Ajuste as alças totalmente para trás, selecione o peso e a altura do assento na altura dos ombros; segure com as palmas para dentro.\nEm movimento semicircular, leve as mãos para os lados e para trás, contraindo os deltoides posteriores.\nMantenha os braços levemente flexionados, com todo o movimento na articulação do ombro.\nPause atrás e volte lentamente com o peso à posição inicial.',
  'Reverse Plate Curls':
    'Em pé e ereto, segure uma anilha com as duas mãos e braços estendidos, pegada pronada, dedos no lado áspero e polegar no liso (posições 11 e 1 horas).\nPés na largura dos ombros e a anilha próxima à virilha.\nSuba lentamente a anilha ao expirar, cotovelos junto ao corpo e braços superiores parados, até bíceps e antebraço se tocarem, alinhada com o tronco.\nSinta a contração por um segundo e abaixe o peso à posição inicial ao inspirar.\nRepita pelo número de repetições recomendado.',
  'Reverse Triceps Bench Press':
    'Deite-se em um banco reto, retire a barra do rack com pegada fechada e supinada na largura dos ombros e segure-a sobre você com os braços travados, perpendiculares ao chão.\nAo inspirar, desça lentamente até sentir a barra na parte média do peito, cotovelos próximos ao tronco para maximizar o trabalho dos tríceps.\nApós pausa de um segundo, empurre a barra de volta ao expirar usando os tríceps, trave os braços e mantenha por um segundo; a descida deve durar pelo menos o dobro da subida.\nRepita pelo número de repetições indicado.\nAo terminar, coloque a barra de volta no rack.',
  'Rhomboids-SMR':
    'Deite-se de costas, coloque um rolo de espuma sob a parte superior das costas e cruze os braços à frente protraindo os ombros.\nEleve o quadril transferindo o peso para o rolo e role para um lado por vez sobre a parte média e superior das costas; pause 10-30 segundos nos pontos de tensão.',
  'Rickshaw Carry':
    'Carregue a estrutura com o peso adequado, posicione-se no centro, segure as alças e empurre com os calcanhares para levantá-la, peito e cabeça erguidos, costas retas.\nCaminhe imediatamente com passos curtos, rápidos e controlados, peito erguido, cabeça para frente, respirando; coloque a estrutura no chão ao chegar ao ponto final.',
  'Rickshaw Deadlift':
    'Carregue a estrutura e posicione-se centralizado entre as alças, pés na largura do quadril; flexione o quadril para segurar as alças deixando as escápulas protraírem.\nRespire fundo, abaixe o quadril e flexione os joelhos, cabeça para frente, peito erguido, costas arqueadas; empurre com os calcanhares e junte as escápulas levando o quadril para frente ao subir o peso.\nAbaixe o peso flexionando o quadril e guiando-o até o chão.',
  'Ring Dips':
    'Segure uma argola em cada mão e dê um pequeno salto para chegar à posição inicial com os braços travados.\nFlexione os cotovelos abaixando o corpo até passar de 90 graus, sem balançar e com boa postura.\nEstenda os cotovelos empurrando-se de volta à posição inicial.\nRepita pelo número de repetições desejado.',
  'Rocket Jump':
    'Fique com os pés afastados na largura dos ombros e os braços junto ao corpo.\nAgache até a metade e salte com explosão o mais alto possível.\nEstenda todo o corpo alcançando acima da cabeça; ao aterrissar, absorva o impacto com as pernas.',
  'Rocking Standing Calf Raise':
    'Use um rack de agachamento; ajuste a barra à sua altura e apoie-a sobre os ombros, abaixo do pescoço.\nSegure a barra com os dois braços e retire-a do rack empurrando com as pernas ao endireitar o tronco.\nAfaste-se do rack, pés na largura dos ombros e pontas para fora; cabeça erguida, costas retas e joelhos com leve flexão. Posição inicial.\nExpire e eleve os calcanhares ao máximo, contraindo as panturrilhas; mantenha os joelhos parados e sustente 1 segundo.\nInspire e abaixe os calcanhares lentamente, flexionando os tornozelos até alongar as panturrilhas.\nExpire e eleve as pontas dos pés contraindo os músculos tibiais da frente da perna.\nSustente 1 segundo e inspire enquanto abaixa novamente.\nRepita pelo número de repetições recomendado.',
  'Rocky Pull-Ups/Pulldowns':
    'Segure a barra fixa com palmas para frente e pegada aberta.\nCom os braços estendidos, incline o tronco 30 graus para trás, curvando a lombar e projetando o peito. Posição inicial.\nExpire e suba o tronco até a barra tocar o peito alto, levando ombros e braços para baixo e atrás; contraia as costas e mantenha o tronco estável.\nSustente 1 segundo, inspire e desça lentamente até estender os braços e alongar os dorsais.\nRepita mantendo o tronco reto; a barra deve tocar a nuca em vez do peito, inclinando levemente a cabeça para frente.\nVolte à posição inicial e repita pelo número de repetições indicado.',
  'Romanian Deadlift':
    'Segure a barra no chão com pegada pronada um pouco mais aberta que os ombros; use munhequeiras ou plataforma elevada se precisar.\nFlexione levemente os joelhos, mantenha as canelas verticais, quadril atrás e costas retas. Posição inicial.\nExpire e use o quadril para levantar a barra, com costas e braços retos, em movimento constante e controlado.\nEm pé, abaixe a barra empurrando o quadril atrás com joelhos quase retos; inspire fundo no início, prenda o ar ao abaixar e expire ao terminar.\nRepita pelo número de repetições recomendado.',
  'Romanian Deadlift from Deficit':
    'Em pé, segure a barra com os braços estendidos; use uma plataforma elevada para mais amplitude de movimento se quiser.\nFlexione levemente os joelhos, leve o bumbum para trás e abaixe o tronco conforme sua flexibilidade, com as costas em extensão e a barra junto às pernas; sentirá tensão nos posteriores de coxa.\nInverta o movimento para voltar à posição inicial.',
  'Rope Climb':
    'Segure a corda com as duas mãos acima da cabeça e puxe para baixo dando um pequeno salto.\nEnrole a corda em uma perna prendendo-a com os pés e estenda os braços para cima segurando com firmeza.\nSolte os pés enquanto se puxa para cima com os braços, levando os joelhos ao peito.\nPrenda os pés novamente e fique em pé para pegar uma pegada mais alta; continue até o topo.\nPara descer, afrouxe a pegada dos pés e deslize em um movimento de mão sobre mão.',
  'Rope Crunch':
    'Ajoelhe-se a 30-60 cm de uma polia com uma corda acoplada.\nEscolha a carga, segure a corda com as duas mãos acima da cabeça e mantenha o tronco ereto. Posição inicial.\nFlexione a coluna aproximando a caixa torácica das pernas enquanto puxa o cabo para baixo.\nFaça uma pausa embaixo e retorne lentamente à posição inicial.\nAdicione rotações ou incline para o lado para trabalhar os oblíquos.',
  'Rope Jumping':
    'Segure uma ponta da corda em cada mão, gire-a sobre a cabeça e salte quando ela tocar o chão; mantenha um ritmo constante.\nPular corda exige coordenação e energia: uma pessoa de 68 kg (150 lb) queima cerca de 350 calorias em 30 minutos, contra 450+ correndo.',
  'Rope Straight-Arm Pulldown':
    'Acople a corda à polia alta, segure-a com as duas mãos e, com os pés escalonados, incline-se pelo quadril com as costas retas e os braços estendidos para cima. Posição inicial.\nCom os braços retos, estenda o ombro para puxar a corda até as coxas.\nFaça uma pausa embaixo contraindo os dorsais.\nRetorne à posição inicial sem deixar a carga descansar totalmente na pilha.',
  'Round The World Shoulder Stretch':
    'Fique em pé com as pernas juntas, segurando uma barra leve ou um cabo de vassoura.\nSegure o bastão atrás do quadril com pegada mais aberta que os ombros, palmas para baixo e polegares para fora.\nLevante lentamente os braços por trás da cabeça sem forçar se ficar difícil.',
  'Rowing, Stationary':
    'Sente-se no remo com os calcanhares fixos nos pedais e as correias ajustadas; incline-se para a frente a partir do quadril.\nNa fase de impulso, com os joelhos flexionados junto ao peito, empurre os pedais e estenda as pernas levando as mãos ao abdômen superior e os ombros para trás; use pernas e quadril para proteger as costas.\nNa recuperação, estenda os braços, flexione os joelhos e leve o corpo para a frente para voltar à fase inicial.',
  "Runner's Stretch":
    'De pé, leve uma perna para trás e abaixe lentamente o tronco em direção ao chão.\nMantenha o calcanhar da frente no chão; se ele levantar, leve a perna de trás mais para trás.\nColoque as mãos ao lado da perna da frente, empurre o bumbum em direção ao teto e abaixe gradualmente; alongará o flexor do quadril de trás e o posterior de coxa e glúteo da frente.',
  'Running, Treadmill':
    'Suba na esteira e escolha o modo manual ou um programa; informe idade e peso para estimar calorias e ajuste a inclinação conforme a intensidade.\nCorra com postura adequada e segure as barras laterais só quando necessário: uma pessoa de 68 kg (150 lb) queima mais de 450 calorias correndo a 8 mph por 30 minutos.',
  'Russian Twist':
    'Deite-se com os pés fixos sob um suporte ou presos por um parceiro, com os joelhos flexionados.\nEleve o tronco formando um V com as coxas; estenda os braços à frente, perpendiculares ao tronco, com as mãos entrelaçadas. Posição inicial.\nExpire e gire o tronco para a direita até os braços ficarem paralelos ao chão.\nSustente 1 segundo, volte ao centro e repita para o lado esquerdo com a mesma técnica.\nRepita pelo número de repetições recomendado.',
  'Sandbag Load':
    'Posicione os sacos a cerca de 15 m (50 pés) da plataforma de carga.\nLevante o saco abraçando-o com os braços e estendendo quadril e joelhos; normalmente não é permitido apoiá-lo no ombro.\nMova-se rápido até a plataforma, estenda quadril, joelhos e tornozelos para erguê-lo alto e coloque-o sem deixar cair.\nVolte à posição inicial para o próximo saco e repita até concluir.',
  'Scapular Pull-Up':
    'Segure a barra fixa com pegada pronada.\nA partir da posição pendurada, eleve-se alguns centímetros sem usar os braços, deprimindo os ombros em um movimento inverso ao de encolher.\nFaça uma pausa no topo e retorne lentamente à posição inicial.',
  'Scissor Kick':
    'Deite-se de costas com os braços estendidos ao lado do corpo, palmas para baixo; mantenha-os imóveis durante todo o exercício.\nCom leve flexão dos joelhos, levante as pernas até os calcanhares ficarem a 15 cm do chão. Posição inicial.\nLevante a perna esquerda a cerca de 45 graus enquanto desce a direita até 5-7 cm do chão.\nAlterne, levantando a perna direita e abaixando a esquerda; lembre-se de respirar.\nRepita pelo número de repetições recomendado.',
  'Scissors Jump':
    'Assuma um afundo com um pé à frente e o joelho flexionado, e o joelho de trás quase tocando o chão.\nCom o joelho da frente alinhado ao pé, estenda ambas as pernas e salte o mais alto possível balançando os braços.\nNo ar, troque a posição das pernas: a da frente vai para trás e a de trás para a frente.\nAo aterrissar, absorva o impacto na posição de afundo e repita.',
  'Seated Band Hamstring Curl':
    'Fixe uma faixa elástica perto do chão e coloque um banco a cerca de meio metro de distância.\nSente-se no banco, prenda a faixa atrás dos tornozelos e comece com as pernas retas. Posição inicial.\nFlexione os joelhos levando os pés em direção ao banco; incline-se levemente para trás se precisar para não tocar o chão.\nFaça uma pausa no topo e retorne lentamente à posição inicial.',
  'Seated Barbell Military Press':
    'Sente-se no banco com a barra atrás da cabeça (peça a um parceiro ou pegue com cuidado) usando pegada pronada mais aberta que os ombros, com 90 graus entre antebraço e braço ao abaixar.\nLevante a barra acima da cabeça estendendo os braços, mantendo-a na altura dos ombros e um pouco à frente. Posição inicial.\nInspire e abaixe a barra lentamente até a clavícula.\nExpire e levante a barra de volta à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Seated Barbell Twist':
    'Sente-se na ponta de um banco reto com a barra sobre as coxas e os pés na largura dos ombros.\nSegure a barra com palmas para baixo, mãos mais afastadas que os ombros, e levante-a acima da cabeça com os braços estendidos.\nAbaixe a barra por trás da cabeça até ela apoiar na base do pescoço. Posição inicial.\nCom pés e cabeça imóveis, mova a cintura de um lado para o outro sem forçar, sentindo os oblíquos; use um movimento lento e controlado.\nExpire ao girar para o lado e inspire ao voltar à posição inicial.\nRepita pelo número de repetições recomendado.',
  'Seated Bent-Over One-Arm Dumbbell Triceps Extension':
    'Sente-se na ponta de um banco reto com um halter em um braço, pegada neutra (palma voltada para você).\nFlexione levemente os joelhos e incline o tronco para a frente a partir do quadril, costas retas quase paralelas ao chão, cabeça erguida.\nMantenha o braço com o halter junto ao tronco, paralelo ao chão, com o antebraço apontando para baixo e 90 graus entre os dois. Posição inicial.\nExpire e estenda o tríceps até o braço ficar reto, movendo apenas o antebraço e mantendo o braço superior imóvel.\nSustente 1 segundo no topo e inspire enquanto abaixa lentamente o halter até a posição inicial.\nRepita o movimento pelo número de repetições prescrito.\nTroque de braço e repita o exercício.',
  'Seated Bent-Over Rear Delt Raise':
    'Coloque um par de halteres à frente de um banco reto, alinhados para a frente.\nSente-se na ponta do banco com as pernas juntas e os halteres atrás das panturrilhas.\nIncline-se pela cintura com as costas retas para pegar os halteres, palmas uma para a outra. Posição inicial.\nExpire e levante os halteres para os lados até os braços ficarem paralelos ao chão, tronco imóvel e cotovelos levemente flexionados; não balance o tronco nem leve os braços para trás.\nSustente 1 segundo no topo e abaixe lentamente os halteres até a posição inicial.\nRepita pelo número de repetições recomendado.',
  'Seated Bent-Over Two-Arm Dumbbell Triceps Extension':
    'Sente-se na ponta de um banco reto com um halter em cada mão, pegada neutra (palmas voltadas para você).\nFlexione levemente os joelhos e incline o tronco para a frente a partir do quadril, costas retas quase paralelas ao chão, cabeça erguida.\nMantenha os braços com os halteres junto ao tronco, paralelos ao chão, antebraços apontando para baixo e 90 graus entre eles. Posição inicial.\nExpire e estenda os tríceps até os braços ficarem retos, movendo apenas os antebraços.\nSustente 1 segundo no topo e inspire enquanto abaixa lentamente os halteres até a posição inicial.\nRepita o movimento pelo número de repetições prescrito.',
  'Seated Biceps':
    'Sente-se com os joelhos flexionados e os braços estendidos atrás, palmas uma para a outra; seu parceiro segura seus punhos atrás de você. Posição inicial.\nTente flexionar os cotovelos enquanto seu parceiro impede o movimento.\nApós 10-20 segundos, relaxe os braços enquanto seu parceiro puxa suavemente seus punhos para cima; avise-o para evitar lesões.',
  'Seated Cable Rows':
    'Use uma polia baixa com triângulo (pegada neutra); sente-se com os pés na plataforma frontal e os joelhos levemente flexionados, sem travar.\nIncline-se para a frente mantendo o alinhamento natural das costas e segure as alças do triângulo.\nCom os braços estendidos, puxe para trás até formar 90 graus com as pernas, costas levemente arqueadas e peito projetado. Posição inicial.\nExpire e puxe as alças até o abdômen mantendo o tronco imóvel, contraindo as costas; sustente 1 segundo e inspire ao voltar lentamente.\nRepita pelo número de repetições recomendado.',
  'Seated Cable Shoulder Press':
    'Ajuste a carga e sente-se segurando as alças, com os braços a 90 graus do corpo, cotovelos a 90 graus e cabeça e peito erguidos. Posição inicial.\nEstenda os cotovelos empurrando as alças juntas por cima da cabeça.\nFaça uma pausa no topo e retorne à posição inicial mantendo a tensão nos cabos.\nTambém pode fazer com as costas afastadas do encosto, alternando as mãos.',
  'Seated Calf Raise':
    'Sente-se na máquina com as pontas dos pés na plataforma e os calcanhares para fora; escolha a posição de pés que preferir.\nColoque a parte inferior das coxas sob o apoio, ajustado à sua altura, e segure-o com as mãos para não deslizar.\nLevante levemente a alavanca empurrando os calcanhares e solte a trava. Posição inicial.\nInspire e abaixe os calcanhares lentamente, flexionando os tornozelos até alongar totalmente as panturrilhas.\nExpire e eleve os calcanhares ao máximo contraindo as panturrilhas; sustente 1 segundo.\nRepita pelo número de repetições recomendado.',
  'Seated Calf Stretch':
    'Sente-se ereto em um colchonete.\nFlexione um joelho e apoie esse pé no chão para estabilizar o tronco.\nEstenda a outra perna e flexione o tornozelo.\nCom uma faixa, toalha ou a mão, puxe os dedos do pé em sua direção; sustente 10-20 segundos e troque de lado.',
  'Seated Close-Grip Concentration Barbell Curl':
    'Sente-se em um banco reto com uma barra ou barra W entre as pernas abertas, joelhos flexionados e pés no chão.\nLevante a barra e apoie a parte de trás dos braços na face interna das coxas, perto do joelho; use pegada supinada mais fechada que os ombros, braços estendidos. Posição inicial.\nExpire e faça a rosca contraindo os bíceps até a barra chegar à altura dos ombros, movendo apenas os antebraços; sustente 1 segundo apertando.\nInspire e retorne a barra lentamente à posição inicial, sem balançar o corpo.\nRepita pelo número de repetições recomendado.',
  'Seated Dumbbell Curl':
    'Sente-se em um banco reto com um halter em cada mão, braços estendidos e cotovelos próximos ao tronco.\nGire as palmas para o tronco. Esta é a posição inicial.\nFaça a rosca sem mover o braço superior; gire os punhos ao passar pelas coxas para as palmas ficarem à frente no topo. Contraia os bíceps ao expirar até a altura dos ombros; mantenha 1 segundo.\nTraga os halteres de volta à posição inicial inspirando e girando os punhos para pegada neutra.\nRepita pelo número de repetições recomendado.',
  'Seated Dumbbell Inner Biceps Curl':
    'Sente-se na ponta de um banco reto com um halter em cada mão, braços estendidos e cotovelos próximos ao tronco.\nGire as palmas para dentro, em posição neutra. Esta é a posição inicial.\nSem mover o braço superior, suba os halteres para fora e para cima girando as palmas para fora, antebraços alinhados com os deltoides laterais.\nMova apenas os antebraços até contrair totalmente os bíceps, com os halteres na altura dos ombros; mantenha 1 segundo.\nAbaixe os halteres lentamente inspirando e girando os braços para voltar à pegada neutra.\nRepita pelo número de repetições recomendado.',
  'Seated Dumbbell Palms-Down Wrist Curl':
    'Coloque dois halteres no chão à frente de um banco reto.\nSente-se na borda do banco com os pés no chão, afastados na largura dos ombros.\nPegue os halteres e apoie os antebraços nas coxas, palmas para baixo, com os punhos pendurados fora da borda.\nFaça a rosca de punho para cima enquanto expira.\nAbaixe os punhos lentamente até a posição inicial inspirando; mantenha os antebraços imóveis, mova só o punho.\nRepita pelo número de repetições recomendado.\nAo terminar, abaixe os halteres até o chão.',
  'Seated Dumbbell Palms-Up Wrist Curl':
    'Coloque dois halteres no chão à frente de um banco reto.\nSente-se na borda do banco com os pés no chão, afastados na largura dos ombros.\nPegue os halteres e apoie os antebraços nas coxas, palmas para cima, com os punhos pendurados fora da borda.\nFaça a rosca de punho para cima enquanto expira.\nAbaixe os punhos lentamente até a posição inicial inspirando; mantenha os antebraços imóveis, mova só o punho.\nRepita pelo número de repetições recomendado.\nAo terminar, abaixe os halteres até o chão.',
  'Seated Dumbbell Press':
    'Sente-se em um banco de desenvolvimento militar ou utilitário com encosto, halteres na vertical sobre as coxas.\nLeve os halteres para cima um de cada vez, com ajuda das coxas, até a altura dos ombros.\nGire os punhos com as palmas para a frente. Esta é a posição inicial.\nEmpurre os halteres para cima até se tocarem no topo enquanto expira.\nMantenha 1 segundo no topo e desça lentamente até a posição inicial inspirando.\nRepita pelo número de repetições recomendado.',
  'Seated Flat Bench Leg Pull-In':
    'Sente-se em um banco com as pernas estendidas à frente, ligeiramente abaixo da paralela, segurando as laterais do banco; tronco inclinado 45 graus para trás.\nTraga os joelhos em sua direção enquanto aproxima o tronco deles, expirando.\nMantenha 1 segundo e volte à posição inicial inspirando.\nRepita pelo número de repetições recomendado.',
  'Seated Floor Hamstring Stretch':
    'Sente-se em um colchonete com a perna direita estendida à frente e a esquerda flexionada, pé contra a coxa direita.\nIncline-se para a frente a partir do quadril e alcance o tornozelo até sentir o alongamento no posterior de coxa; mantenha 15 segundos e repita do outro lado.',
  'Seated Front Deltoid':
    'Sente-se ereto no chão com as pernas flexionadas; seu parceiro, atrás de você, segura seus punhos com os braços estendidos para trás, palmas para o chão.\nCom os cotovelos estendidos, tente mover os braços para a frente enquanto seu parceiro resiste ao movimento por 10-20 segundos.\nRelaxe os músculos e deixe seu parceiro aumentar suavemente o alongamento nos ombros e peito; mantenha 10-20 segundos.',
  'Seated Glute':
    'Sentado com os joelhos flexionados, cruze um tornozelo sobre o joelho oposto; incline-se para a frente enquanto seu parceiro, atrás, segura seus ombros.\nTente empurrar o tronco para trás por 10-20 segundos enquanto seu parceiro impede o movimento.\nRelaxe os músculos enquanto seu parceiro empurra suavemente seu tronco para a frente por 10-20 segundos.',
  'Seated Good Mornings':
    'Posicione uma caixa dentro de um rack de agachamento com os pinos na altura adequada; entre sob a barra apoiando-a nos ombros (não no trapézio), junte as escápulas e gire os cotovelos para a frente.\nRetire a barra do rack com um arco firme na lombar, cabeça à frente; empurre os joelhos e o bumbum para fora e sente-se na caixa. Esta é a posição inicial.\nCom a barra firme, incline-se para a frente a partir do quadril o máximo possível; ajuste os pinos na altura da paralela como segurança e referência.\nFaça uma pausa logo acima dos pinos e inverta o movimento até ficar ereto.',
  'Seated Hamstring':
    'Sentado com as pernas estendidas, incline-se para a frente enquanto seu parceiro, atrás, segura seus ombros. Esta é a posição inicial.\nTente empurrar o tronco para trás por 10-20 segundos enquanto seu parceiro impede o movimento.\nRelaxe os músculos enquanto seu parceiro empurra suavemente seu tronco para a frente por 10-20 segundos.',
  'Seated Hamstring and Calf Stretch':
    'Passe um cinto, corda ou faixa elástica ao redor de um pé e sente-se com as duas pernas estendidas. Esta é a posição inicial.\nIncline-se levemente para a frente e puxe o cinto levando os dedos do pé para trás; mantenha 10-20 segundos e repita com a outra perna.',
  'Seated Head Harness Neck Resistance':
    'Coloque um arnês de pescoço no chão na extremidade de um banco reto; sente-se na ponta com os pés mais afastados que a largura dos ombros e as pontas para fora.\nIncline o tronco quase paralelo ao chão e ajuste o arnês ao redor da cabeça com as duas mãos, com os pesos apoiados no chão para não tensionar o pescoço; depois segure o peso com as duas mãos e eleve o tronco até quase perpendicular ao chão, com a cabeça levemente inclinada para a frente.\nColoque as duas mãos sobre os joelhos. Esta é a posição inicial.\nAbaixe lentamente o pescoço até o queixo tocar o peito enquanto inspira.\nLeve o pescoço de volta à posição inicial enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Seated Leg Curl':
    'Ajuste a alavanca da máquina à sua altura e sente-se com as costas no encosto.\nColoque a parte de trás da perna sobre a alavanca acolchoada, abaixo das panturrilhas, com o apoio sobre as coxas acima dos joelhos; segure as alças, pés retos e pernas totalmente estendidas. Esta é a posição inicial.\nPuxe a alavanca em direção às coxas flexionando os joelhos o máximo possível enquanto expira, tronco imóvel; mantenha 1 segundo.\nRetorne lentamente à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Leg Tucks':
    'Sente-se em um banco com as pernas estendidas à frente, ligeiramente abaixo da paralela, segurando as laterais do banco; tronco inclinado 45 graus para trás.\nTraga os joelhos em sua direção enquanto aproxima o tronco deles, expirando.\nMantenha 1 segundo e volte à posição inicial inspirando.\nRepita pelo número de repetições recomendado.',
  'Seated One-Arm Dumbbell Palms-Down Wrist Curl':
    'Sente-se em um banco reto com um halter na mão direita.\nApoie os pés no chão, um pouco mais afastados que a largura dos ombros.\nIncline-se para a frente e apoie o antebraço direito sobre a coxa direita, palma para baixo, com a parte de trás do punho sobre o joelho. Esta é a posição inicial.\nAbaixe o halter o máximo possível com pegada firme enquanto inspira.\nFaça a rosca com o halter o mais alto possível contraindo o antebraço enquanto expira; mantenha 1 segundo. Apenas o punho deve se mover.\nComplete as repetições recomendadas, troque de braço e repita.',
  'Seated One-Arm Dumbbell Palms-Up Wrist Curl':
    'Sente-se em um banco reto com um halter na mão direita.\nApoie os pés no chão, um pouco mais afastados que a largura dos ombros.\nIncline-se para a frente e apoie o antebraço direito sobre a coxa direita, palma para cima, com a parte da frente do punho sobre o joelho. Esta é a posição inicial.\nAbaixe o halter o máximo possível com pegada firme enquanto inspira.\nFaça a rosca com o halter o mais alto possível contraindo o antebraço enquanto expira; mantenha 1 segundo. Apenas o punho deve se mover.\nComplete as repetições recomendadas, troque de braço e repita.',
  'Seated One-arm Cable Pulley Rows':
    'Sente-se na máquina com os pés na plataforma frontal ou na barra transversal, joelhos levemente flexionados e não travados.\nIncline-se para a frente mantendo as costas alinhadas e segure a alça simples com o braço esquerdo, palma para baixo.\nCom o braço estendido, puxe para trás até o tronco formar 90 graus com as pernas, costas levemente arqueadas e peito projetado; o braço direito pode ficar junto à cintura. Esta é a posição inicial.\nPuxe a alça em direção ao tronco mantendo o braço próximo a ele e girando o punho para neutro (palma para o tronco) ao chegar aos abdominais, tronco imóvel, enquanto expira.\nMantenha a contração por 1 segundo e volte lentamente inspirando, girando o punho de volta para palma para baixo.\nRepita pelo número de repetições recomendado e depois faça o mesmo com a mão direita.',
  'Seated Overhead Stretch':
    'Sente-se ereto em um colchonete.\nJunte as solas dos pés, a 15-20 cm à frente do quadril.\nApoie uma mão no chão ao seu lado e a outra atrás da cabeça.\nLevante o cotovelo em direção ao teto enquanto inclina o tronco para o outro lado; mantenha 10-20 segundos e troque de lado.',
  'Seated Palm-Up Barbell Wrist Curl':
    'Segure uma barra com as duas mãos, palmas para cima, na largura dos ombros.\nApoie os pés no chão, um pouco mais afastados que a largura dos ombros.\nIncline-se para a frente e apoie os antebraços sobre as coxas, palmas para cima, com a frente dos punhos sobre os joelhos. Esta é a posição inicial.\nAbaixe a barra o máximo possível com pegada firme enquanto inspira.\nFaça a rosca com a barra o mais alto possível contraindo os antebraços enquanto expira; mantenha 1 segundo no topo. Apenas o punho deve se mover.',
  'Seated Palms-Down Barbell Wrist Curl':
    'Segure uma barra com as duas mãos, palmas para baixo, na largura dos ombros.\nApoie os pés no chão, um pouco mais afastados que a largura dos ombros.\nIncline-se para a frente e apoie os antebraços sobre as coxas, palmas para baixo, com a parte de trás dos punhos sobre os joelhos. Esta é a posição inicial.\nAbaixe a barra o máximo possível com pegada firme enquanto inspira.\nFaça a rosca com a barra o mais alto possível contraindo os antebraços enquanto expira; mantenha 1 segundo no topo. Apenas o punho deve se mover.',
  'Seated Side Lateral Raise':
    'Sente-se na ponta de um banco reto com os pés firmes no chão; segure os halteres com palmas para dentro e braços estendidos ao lado do corpo. Esta é a posição inicial.\nSem balançar o tronco, levante os halteres para os lados com cotovelos levemente flexionados e mãos um pouco inclinadas para a frente, até os braços ficarem paralelos ao chão; expire e mantenha 1 segundo no topo.\nAbaixe os halteres lentamente até a posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'Seated Triceps Press':
    'Sente-se em um banco com encosto e segure um halter com as duas mãos acima da cabeça, braços estendidos, palmas para dentro e polegares em volta dele; peça ajuda para erguê-lo se estiver pesado. Esta é a posição inicial.\nCom a parte superior dos braços próxima à cabeça (cotovelos para dentro) e perpendicular ao chão, abaixe o halter em semicírculo atrás da cabeça até os antebraços tocarem os bíceps enquanto inspira; apenas os antebraços devem se mover.\nLevante o halter com os tríceps até a posição inicial enquanto expira.\nRepita pelo número de repetições recomendado.',
  'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl':
    'Coloque um banco à frente de uma polia baixa com barra ou acessório de barra W.\nAfaste o banco o suficiente para gerar tensão no cabo ao levar a alça até a parte superior das coxas.\nSegure a alça com as duas mãos, palmas para cima, pegada na largura dos ombros.\nSente-se no banco com os pés firmes no chão na largura dos ombros.\nIncline-se para a frente e apoie os antebraços nas coxas, com a parte de trás dos punhos sobre os joelhos. Esta é a posição inicial.\nAbaixe a barra o máximo possível com pegada firme enquanto inspira.\nFaça a rosca com a barra o mais alto possível contraindo os antebraços; apenas o punho deve se mover, não os antebraços.\nMantenha a contração por 1 segundo no topo e volte à posição inicial enquanto inspira.\nRepita pelo número de repetições recomendado.',
  'See-Saw Press (Alternating Side Press)':
    'Pegue um halter em cada mão e fique em pé, ereto.\nLevante os halteres até a altura do peito/ombros e gire os punhos com as palmas para você, como se preparasse um desenvolvimento Arnold. Esta é a posição inicial.\nEstenda o braço esquerdo acima da cabeça girando o punho para a palma ficar à frente no topo, abrindo o cotovelo, enquanto inclina o quadril para o lado oposto; deve parecer que alcança algo acima à direita com o braço esquerdo. Expire ao fazer isso.\nAo chegar ao topo, inspire; com o peso estendido acima da cabeça e o corpo inclinado à direita, inicie o movimento para o lado esquerdo.\nRepita pelo número de repetições recomendado.',
  'Shotgun Row':
    'Acople uma alça simples a uma polia baixa.\nDepois de escolher a carga, posicione-se a alguns passos de distância com as pernas afastadas; braço estendido e ombro para a frente. Esta é a posição inicial.\nRetraia o ombro e flexione o cotovelo para puxar, supinando o punho até a palma ficar para cima no final do movimento.\nApós uma breve pausa, retorne à posição inicial.',
  'Shoulder Circles':
    'Com os ombros relaxados e os braços soltos ao lado do corpo (ou no colo, se sentado), role os ombros para a frente, para cima, para trás e para baixo.\nInverta a direção; você pode alternar os ombros ou movê-los juntos.',
  'Shoulder Press - With Bands':
    'Fique em pé sobre uma faixa elástica de modo que a tensão comece com os braços estendidos; suba as alças até a altura dos ombros, uma de cada lado.\nGire os punhos com as palmas para a frente, cotovelos flexionados e antebraços alinhados com o tronco. Esta é a posição inicial.\nSuba as alças até estender totalmente os braços acima da cabeça enquanto expira.',
  'Shoulder Raise':
    'Relaxe os braços ao lado do corpo e eleve os ombros em direção às orelhas; depois abaixe-os.',
  'Shoulder Stretch':
    'Leve o braço esquerdo através do corpo e mantenha-o esticado.',
  'Side Hop-Sprint':
    'Posicione-se ao lado de um cone ou barreira.\nSalte lateralmente sobre o obstáculo e aproveite o impulso da aterrissagem para voltar ao ponto de partida.\nSalte as repetições indicadas o mais rápido possível e finalize correndo uma curta distância após o último salto.',
  'Side Lateral Raise':
    'Fique em pé com o tronco reto, halteres ao lado do corpo, braços estendidos e palmas voltadas para você. Posição inicial.\nSem balançar o tronco, levante os halteres para os lados com cotovelos levemente flexionados e mãos inclinadas para a frente, até os braços ficarem paralelos ao chão; expire e pause um segundo no topo.\nAbaixe lentamente os halteres até a posição inicial enquanto inspira.\nRepita o número de repetições recomendado.',
  'Side Laterals to Front Raise':
    'Em pé, segure um par de halteres ao lado do corpo. Posição inicial.\nCom os cotovelos levemente flexionados, levante os pesos à frente até a altura dos ombros sem balançar o corpo.\nNo topo, abra os pesos para os lados à sua frente mantendo os braços estendidos.\nAbaixe os pesos com um movimento controlado.\nNa repetição seguinte, levante os pesos à frente até os ombros e depois abra-os para os lados.\nAbaixe os pesos até a posição inicial.',
  'Side Leg Raises':
    'Fique em pé ao lado de uma cadeira, segurando-se como apoio, equilibrado sobre uma perna. Posição inicial.\nCom a perna esticada, levante-a o mais para o lado possível e desça-a em balanço, cruzando a perna oposta.\nRepita o balanço de 5 a 10 vezes, aumentando a amplitude de movimento conforme avança.',
  'Side Lying Groin Stretch':
    'Comece deitando-se sobre o lado direito e dobre o joelho direito à sua frente para estabilizar o tronco.\nApoie a cabeça na mão ou no ombro direito; levante a perna esquerda e segure-a atrás do joelho (mais fácil) ou pelo pé (mais difícil).\nPuxe o joelho esquerdo em direção ao ombro esquerdo e pressione o pé ou joelho contra o chão; para intensificar, estique a perna esquerda. Troque de lado.',
  'Side Neck Stretch':
    'Comece com os ombros relaxados e incline suavemente a cabeça em direção ao ombro.\nAuxilie o alongamento com uma puxada suave na lateral da cabeça.',
  'Side Standing Long Jump':
    'Fique em pé com os pés na largura do quadril em postura atlética, peito erguido, joelhos e quadril levemente flexionados. Posição inicial.\nIncline-se para a direita e estenda quadril, joelhos e tornozelos para saltar, usando os braços, o mais longe possível para a direita.\nAterrisse voltado para a mesma direção, pés na largura do quadril, absorvendo o impacto com a parte inferior do corpo.',
  'Side To Side Chins':
    'Segure a barra fixa com as palmas voltadas para a frente e pegada aberta.\nCom os braços estendidos e pegada aberta, incline o tronco 30 graus para trás, arqueando a lombar e projetando o peito. Posição inicial.\nPuxe o tronco para a esquerda até quase tocar a barra no peito, levando ombros e braços para baixo e para trás; expire e contraia as costas ao máximo. Mantenha o tronco estável sem balançar, movendo só os braços; os antebraços apenas seguram a barra.\nApós um segundo de contração, inspire enquanto retorna à posição inicial.\nAgora puxe o tronco para a direita até quase tocar a barra no peito, levando ombros e braços para baixo e para trás; expire e contraia as costas ao máximo. Mantenha o tronco estável, movendo só os braços; os antebraços apenas seguram a barra.\nApós um segundo de contração, inspire enquanto retorna à posição inicial.\nRepita os passos 3 a 6 até completar o número indicado de repetições para cada lado.',
  'Side Wrist Pull':
    'De pé, cruze o braço esquerdo à frente do corpo e segure o punho esquerdo com a mão direita na altura do quadril, com o braço flexionado.\nEstique e levante lentamente o braço até a altura do ombro; sinta o alongamento nas costas, não no ombro, sem puxar forte a articulação. Troque de lado.',
  'Side to Side Box Shuffle':
    'Posicione-se ao lado da caixa com o pé esquerdo apoiado no meio dela.\nSalte para o outro lado da caixa, aterrissando com o pé direito sobre ela e o esquerdo no chão; ajude-se balançando os braços.\nContinue se deslocando de um lado para o outro sobre a caixa.',
  'Side-Lying Floor Stretch':
    'Deite-se sobre o lado esquerdo, dobrando o joelho esquerdo à frente para estabilizar o tronco (use também os abdominais).\nEstique a perna direita com o pé atrás do esquerdo; estique o braço direito acima da cabeça e puxe o punho para alongar todo o lado direito. Troque de lado.',
  'Single Dumbbell Raise':
    'Com os pés afastados, segure um halter com as duas mãos pela cabeça do halter (não a haste), braços estendidos na altura da cintura. Posição inicial.\nLevante o peso acima dos ombros com os braços estendidos, mantendo tronco e quadril parados.\nRetorne à posição inicial e repita o número de repetições recomendado.',
  'Single Leg Butt Kick':
    'Fique em pé sobre uma perna, com o joelho da outra flexionado e elevado. Posição inicial.\nCom um salto com contramovimento, salte estendendo quadril, joelho e tornozelo da perna de apoio.\nImediatamente flexione o joelho e tente tocar o glúteo com o calcanhar da perna que salta.\nRetorne a perna parcialmente flexionada sob o quadril e aterrisse; a perna oposta permanece quase na mesma posição.',
  'Single Leg Glute Bridge':
    'Deite-se no chão com os pés apoiados e os joelhos flexionados.\nLevante uma perna do chão trazendo o joelho em direção ao peito. Posição inicial.\nEmpurre com o calcanhar, estenda o quadril para cima e tire os glúteos do chão.\nEstenda o máximo possível, faça uma pausa e retorne à posição inicial.',
  'Single Leg Push-off':
    'Fique em pé com um pé apoiado sobre a caixa, com o calcanhar perto da borda.\nImpulsione-se com o pé sobre a caixa, ganhando o máximo de altura ao estender quadril e joelho.\nAterrisse com o mesmo pé sobre a caixa, retornando o outro pé à posição inicial.',
  'Single-Arm Cable Crossover':
    'Mova as polias para a posição alta, selecione a resistência e segure uma alça em cada mão.\nDê um passo à frente entre as polias, braços estendidos e mãos juntas, cabeça e peito erguidos ao se inclinar, pés escalonados. Posição inicial.\nCom o braço esquerdo fixo, abra o direito para o lado com o cotovelo levemente flexionado, perpendicular ao corpo, na altura dos ombros.\nRetorne o braço à posição inicial levando a mão de volta à linha média do corpo.\nSegure um segundo na posição inicial e repita com o lado oposto, alternando pelo número de repetições indicado.',
  'Single-Arm Linear Jammer':
    'Posicione uma barra em um landmine ou ancore-a firmemente em um canto. Carregue a barra com um peso adequado.\nLevante a barra do chão até os ombros com uma ou as duas mãos, em postura ampla. Posição inicial.\nEstenda o cotovelo empurrando o peso para cima de forma explosiva, estendendo totalmente quadril e joelhos para máxima força.\nRetorne à posição inicial.',
  'Single-Arm Push-Up':
    'Deite-se de bruços apoiado nas pontas dos pés e em um braço, com o braço de trabalho estendido sob o ombro; afaste mais os pés do que em uma flexão normal para mais base.\nMantenha boa postura e coloque a mão livre atrás das costas. Posição inicial.\nAbaixe-se permitindo que o cotovelo flexione até tocar o chão.\nDesça lentamente e inverta a direção estendendo o braço para retornar à posição inicial.',
  'Single-Cone Sprint Drill':
    'Fique em pé ao lado de um cone com um braço para trás e o outro para a frente; este exercício treina a agilidade dos pés.\nMovimente os pés rápido com passos curtos e braços ativos, contornando o cone com os joelhos altos.\nDescanse após três voltas ao redor do cone.',
  'Single-Leg High Box Squat':
    'Posicione uma caixa em um rack. Fixe uma faixa ou corda em um ponto acima da caixa.\nDiante da caixa, suba até ficar totalmente em pé com a outra perna sem apoio, segurando a faixa para o equilíbrio.\nContinue subindo e descendo com a mesma perna antes de trocar para o lado oposto.',
  'Single-Leg Hop Progression':
    'Disponha uma fileira de cones à sua frente, equilibrado sobre uma perna com o joelho oposto elevado. Posição inicial.\nSalte para a frente, saltando e aterrissando com a mesma perna sobre o cone.\nUse um salto com contramovimento para saltar de cone em cone.\nNo final, dê meia-volta e retorne com a outra perna.',
  'Single-Leg Lateral Hop':
    'Posicione-se ao lado de um cone ou barreira, apoiado em uma perna com o joelho levemente flexionado. Posição inicial.\nExecute um salto com contramovimento para saltar lateralmente sobre o cone.\nAterrisse sobre a perna que saltou e rebata imediatamente de volta à posição inicial.\nContinue saltando de um lado para o outro.',
  'Single-Leg Leg Extension':
    'Sente-se e ajuste a máquina: o apoio contra a parte inferior da canela (sem tocar no tornozelo) e o ponto de pivô alinhado com o joelho. Escolha uma carga adequada.\nCom boa postura, estenda totalmente uma perna e pause no topo do movimento.\nRetorne à posição inicial sem deixar o peso descansar, mantendo a tensão no músculo.\nRepita o número de repetições desejado.',
  'Single-Leg Stride Jump':
    'Posicione-se ao lado de uma caixa com o pé interno sobre ela, perto da borda.\nBalance os braços para cima enquanto empurra com a perna sobre a caixa, saltando o mais alto possível e impulsionando o joelho oposto.\nAterrisse na mesma posição em que começou, usando a perna interna para desacelerar o impacto.',
  'Sit Squats':
    'Fique em pé com os pés na largura dos ombros. Posição inicial.\nFlexione os joelhos e o quadril, sentando para trás com o quadril.\nAgache parcialmente, ficando acima da paralela, e inverta rápido o movimento até a posição inicial; repita de 5 a 10 vezes.',
  'Sit-Up':
    'Deite-se com os pés fixos sob algo estável ou seguros por um parceiro, joelhos flexionados.\nColoque as mãos atrás da cabeça e entrelace os dedos. Posição inicial.\nEleve o tronco até formar um V imaginário com as coxas, expirando.\nApós um segundo de contração, abaixe o tronco à posição inicial inspirando.\nRepita o número de repetições recomendado.',
  Skating:
    'Aprenda a fazer curvas e frear, e use equipamentos de proteção; patinar melhora o condicionamento cardiorrespiratório, a resistência muscular, o equilíbrio e a coordenação.\nPatine 30 minutos em ritmo confortável, ou em intervalos: 2 minutos rápido a cada 5, recuperando nos 3 restantes. Uma pessoa de 150 lb queima cerca de 175 calorias em 30 minutos em ritmo confortável (semelhante a uma caminhada rápida).',
  'Sled Drag - Harness':
    'Carregue o trenó com o peso desejado e prenda a correia de tração: com alças, arnês ou a um cinto de peso.\nPuxando para a frente ou para trás, incline-se na direção do deslocamento e avance estendendo quadril e joelhos.',
  'Sled Overhead Backward Walk':
    'Prenda duas alças a um trenó conectado por corda ou corrente. Carregue o trenó com um peso leve.\nDe frente para o trenó, ande de costas até tensionar a linha, mãos acima da cabeça com os cotovelos estendidos. Posição inicial.\nCaminhe de costas mantendo os braços elevados acima da cabeça, evitando movimentos bruscos.',
  'Sled Overhead Triceps Extension':
    'Prenda duas alças a um trenó usando corrente ou corda. Carregue o trenó com uma carga adequada.\nDe costas para o trenó, afaste-se até tensionar a linha; levante as mãos acima da cabeça, juntas e com as palmas voltadas uma para a outra, cotovelos flexionados para cima. Posição inicial.\nEstenda o cotovelo para esticar o braço, mantendo fixa a parte superior do braço para isolar o tríceps.\nNa extensão completa, dê um passo à frente para tirar a folga da linha; você pode escalonar os pés para mais estabilidade.',
  'Sled Push':
    'Carregue o trenó de empurrar com o peso desejado.\nIncline-se contra o trenó segurando as alças, braços estendidos; empurre rápido estendendo quadril e joelhos.',
  'Sled Reverse Flye':
    'Prenda duas alças ao trenó com corda ou corrente e carregue um peso leve.\nVoltado para o trenó, ande de costas até tensionar a linha; segure as alças na altura da cintura, joelhos flexionados e peito erguido.\nSem flexionar os cotovelos, puxe as alças para cima e para os lados com rotação externa, palmas para a frente.\nRetorne à posição inicial dando alguns passos para trás para tirar a folga da linha.',
  'Sled Row':
    'Prenda duas alças ao trenó com corda ou corrente, carregue o peso e ande de costas até tensionar a linha.\nCom uma alça em cada mão, flexione levemente os joelhos, cabeça e peito erguidos, braços estendidos.\nFlexione os cotovelos retraindo as escápulas para puxar o trenó em sua direção.\nDê um ou dois passos para trás para recuperar a tensão da linha e repita.',
  'Sledgehammer Swings':
    'Fique em pé diante de um pneu a cerca de 60 cm, em postura escalonada, e empunhe a marreta.\nSe você é destro, mão esquerda na parte de baixo do cabo e a direita mais acima, próxima à cabeça da marreta.\nDeslize a mão direita até a cabeça ao subir a marreta e junte-a à esquerda ao descer; golpeie o pneu com força e controle o rebote.\nRepita do outro lado.',
  'Smith Incline Shoulder Raise':
    'Coloque um banco inclinado sob a máquina Smith, ajuste a barra na altura de braços quase estendidos e deite-se com os ombros sob a barra.\nCom pegada pronada na largura dos ombros, retire a barra e mantenha-a estendida acima de você com leve flexão nos cotovelos.\nExpire e suba a barra até estender totalmente os braços, sentindo a contração nos ombros.\nPause um segundo e abaixe a barra à posição inicial inspirando.\nRepita o número de repetições indicado.\nAo terminar, recoloque a barra no suporte.',
  'Smith Machine Behind the Back Shrug':
    'Com a barra na altura das coxas, carregue o peso adequado.\nFique com a barra atrás de você, pegada pronada na largura dos ombros, destrave o peso e mantenha-se erguido com os braços estendidos.\nEleve os ombros diretamente para cima sem flexionar braços ou punhos.\nPause brevemente e retorne o peso à posição inicial.\nRepita as repetições desejadas antes de travar a barra no suporte.',
  'Smith Machine Bench Press':
    'Deite-se em um banco reto sob a Smith; pegada pronada mais aberta que os ombros e mantenha a barra travada acima do peito.\nInspire e desça lentamente a barra até a parte média do peito.\nPause um segundo, expire e empurre a barra com o peito até travar os braços; a descida deve durar o dobro da subida.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, trave a barra de volta no suporte.',
  'Smith Machine Bent Over Row':
    'Ajuste a barra da Smith a cerca de 5 cm abaixo dos joelhos.\nFlexione levemente os joelhos e incline o tronco à frente com as costas retas até quase paralelas ao chão, cabeça erguida.\nSegure a barra com pegada pronada, destrave-a e deixe-a pender à sua frente com os braços estendidos perpendiculares ao chão.\nCom o tronco parado, expire e levante a barra com os cotovelos próximos ao corpo; contraia as costas no topo e segure um segundo.\nInspire e abaixe lentamente o peso à posição inicial.\nRepita o número de repetições recomendado.',
  'Smith Machine Calf Raise':
    'Ajuste a barra da Smith à sua altura, suba em um bloco com a ponta dos pés e posicione a barra na parte de trás dos ombros.\nSegure a barra com as duas mãos à frente e gire-a para destravá-la do suporte.\nEleve os calcanhares o mais alto possível empurrando com a ponta dos pés, joelhos estendidos; mantenha a contração um segundo.\nInspire e abaixe lentamente os calcanhares à posição inicial.\nRepita o número de repetições recomendado.',
  'Smith Machine Close-Grip Bench Press':
    'Deite-se em banco reto sob a Smith com pegada fechada e pronada na largura dos ombros; mantenha a barra travada acima do peito.\nInspire e desça lentamente a barra até o peito, mantendo os cotovelos próximos ao tronco para focar nos tríceps.\nPause um segundo, expire e empurre a barra com os tríceps até travar os braços; a descida deve durar o dobro da subida.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, trave a barra de volta no suporte.',
  'Smith Machine Decline Press':
    'Posicione um banco declinado sob o rack com a barra acima do peito e carregue o peso adequado.\nDestrave a barra, estenda os braços com as costas levemente arqueadas e as escápulas retraídas.\nFlexione os braços e abaixe a barra até o peito.\nPause brevemente e estenda os braços para retornar o peso à posição inicial.\nAo completar as repetições desejadas, trave a barra no suporte.',
  'Smith Machine Hang Power Clean':
    'Posicione a barra na altura dos joelhos e carregue-a com o peso adequado.\nPegada pronada mais aberta que os ombros, destrave a barra com braços estendidos, cabeça e peito erguidos, cotovelos para fora, quadril atrás tensionando os posteriores de coxa.\nEstenda com força o quadril e os joelhos acelerando a barra, braços esticados.\nNa extensão completa, flexione novamente o quadril e os joelhos para baixar sua posição de recepção.\nFlexione os braços girando os cotovelos ao redor da barra para recebê-la sobre os ombros.\nEstenda o quadril e os joelhos até ficar em pé com a barra sobre os ombros.',
  'Smith Machine Hip Raise':
    'Deite-se em um banco com os pés contra a barra carregada, destrave-a e estenda as pernas segurando as laterais da Smith.\nRotacione a pelve e flexione a coluna para elevar o quadril do banco, com leve flexão dos joelhos.\nPause brevemente e retorne o quadril ao banco.\nRepita o número de repetições desejado.',
  'Smith Machine Incline Bench Press':
    'Deite-se em banco inclinado sob a Smith, parte superior do peito sob a barra; pegada pronada mais aberta que os ombros, barra travada acima de você.\nInspire e desça lentamente a barra até a parte superior do peito.\nPause um segundo, expire e empurre com o peito até travar os braços; a descida deve durar o dobro da subida.\nRepita o movimento pelo número de repetições indicado.\nAo terminar, recoloque a barra no suporte.',
  'Smith Machine Leg Press':
    'Posicione a barra carregada a cerca de 60 cm do chão, apoiada nas travas; deite-se sob ela com a parte média dos pés na barra e joelhos no peito.\nEmpurre com os pés para subir a barra estendendo o quadril e os joelhos, sem travá-los.\nPause brevemente no topo e retorne à posição inicial.',
  'Smith Machine One-Arm Upright Row':
    'Com a barra na altura das coxas, carregue o peso adequado.\nPegada aberta com um braço, destrave o peso retirando a outra mão; braço estendido, em pé ereto com cabeça e peito erguidos.\nFlexione o cotovelo elevando o braço com o cotovelo para fora, até ficar paralelo ao chão.\nPause brevemente e retorne o peso à posição inicial.\nRepita as repetições desejadas antes de travar o peso no suporte.',
  'Smith Machine Overhead Shoulder Press':
    'Coloque um banco (de preferência com encosto) sob a Smith, com a barra na altura de braços quase estendidos ao sentar.\nSente-se um pouco atrás da barra, nariz alinhado com ela; palmas para a frente, destrave-a e suba com os braços totalmente estendidos.\nInspire e abaixe lentamente a barra até a altura do queixo.\nExpire e suba a barra de volta com os ombros à posição inicial.\nRepita o número de repetições recomendado.',
  'Smith Machine Pistol Squat':
    'Ajuste a barra à sua altura e posicione-a na parte de trás dos ombros.\nPegada com palmas para a frente, destrave a barra e retire-a estendendo as pernas.\nMova um pé cerca de 30 cm à frente da barra e estenda a outra perna no ar, olhar à frente, coluna neutra ou levemente arqueada.\nDesça flexionando joelho e quadril da perna de apoio até onde a flexibilidade permitir.\nPause brevemente embaixo e retorne empurrando com o calcanhar, estendendo joelho e quadril.',
  'Smith Machine Reverse Calf Raises':
    'Ajuste a barra à sua altura e posicione uma plataforma elevada logo abaixo.\nFique sobre a plataforma com os calcanhares firmes e a ponta dos pés para fora dela, pés na largura dos ombros.\nColoque os ombros sob a barra e fique em pé estendendo quadril e joelhos, joelhos levemente flexionados; a barra serve só para equilíbrio.\nExpire e eleve a ponta dos pés o mais alto possível contraindo a panturrilha, joelho parado sem flexão; mantenha um segundo.\nInspire e abaixe lentamente a ponta dos pés à posição inicial.\nRepita o número de repetições recomendado.',
  'Smith Machine Squat':
    'Ajuste a barra na altura que combine com sua estatura e apoie a parte de trás dos ombros, logo abaixo do pescoço, sobre ela.\nPegada com palmas para a frente ao lado do corpo, destrave a barra e retire-a do suporte empurrando com as pernas enquanto endireita o tronco.\nPés na largura dos ombros com pontas levemente para fora, cabeça erguida e costas retas; esta é a sua posição inicial.\nInspire e desça flexionando os joelhos até o ângulo coxa-panturrilha ficar um pouco menor que 90°, sem deixar os joelhos passarem da ponta dos pés.\nExpire e suba empurrando o chão com o calcanhar, endireitando as pernas até voltar à posição inicial.\nRepita o número de repetições recomendado.',
  'Smith Machine Stiff-Legged Deadlift':
    'Ajuste a barra da Smith à altura média da coxa e segure-a com pegada pronada na largura dos ombros; use munhequeiras com cargas altas.\nLevante a barra estendendo os braços e as costas retas, em pé com as pernas na largura dos ombros ou mais próximas, joelhos levemente flexionados.\nCom os joelhos parados, abaixe a barra na frente dos pés flexionando o quadril, costas retas, até sentir alongamento nos posteriores de coxa; expire.\nSuba o tronco estendendo o quadril e a cintura até a posição inicial; inspire.\nRepita o número recomendado de repetições.',
  'Smith Machine Upright Row':
    'Ajuste a barra da Smith à altura média da coxa e segure-a com pegada pronada na largura dos ombros; use munhequeiras com cargas altas.\nLevante a barra com os braços estendidos, costas retas e leve flexão nos cotovelos; esta é a posição inicial.\nExpire e suba a barra próxima ao corpo com os cotovelos guiando o movimento, até quase tocar o queixo; pause um segundo no topo.\nInspire e abaixe a barra lentamente à posição inicial.\nRepita o número recomendado de repetições.',
  'Smith Single-Leg Split Squat':
    'Coloque um banco reto a 60-90 cm atrás da Smith, ajuste a barra à sua altura e apoie-a na parte de trás dos ombros.\nPegada com palmas para a frente de cada lado, destrave a barra e retire-a do suporte empurrando com as pernas enquanto endireita o tronco.\nColoque um pé à frente sob a barra e estenda a outra perna atrás apoiando o peito do pé no banco; esta é a sua posição inicial.\nInspire e desça flexionando o joelho da frente, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar um pouco menor que 90°, sem o joelho passar da ponta do pé.\nExpire e suba empurrando o chão com o calcanhar, endireitando a perna até a posição inicial.\nRepita o número recomendado de repetições.\nTroque de perna e repita o movimento.',
  Snatch:
    'Posicione os pés na largura dos ombros, com a barra sobre a junção dos dedos com o pé.\nPegada pronada mais larga que os ombros, flexione os joelhos com as costas retas, quadril abaixado como se fosse sentar; esta é a sua posição inicial.\nEmpurre o chão com os pés e comece a levantar a barra próxima às pernas.\nQuando a barra chegar ao meio da coxa, empurre com as pernas e estenda o corpo explosivamente.\nEncolha os ombros ao subir a barra, cotovelos para os lados acima dela o maior tempo possível.\nCom um movimento rápido e potente, entre com o corpo sob a barra quando ela atingir altura suficiente e desça em agachamento com os braços travados acima da cabeça.\nLevante-se do agachamento com os pés alinhados e os braços estendidos segurando a barra acima da cabeça.',
  'Snatch Balance':
    'Comece com os pés na posição de puxada, barra na parte de trás dos ombros e pegada larga de snatch.\nImpulsione a barra com flexão e extensão brusca dos joelhos e entre agressivamente sob ela, levando os pés à posição de recepção.\nReceba a barra com os braços travados acima da cabeça perto do fundo do agachamento, tronco vertical e quadril baixo entre as pernas.\nDesça à profundidade completa, volte a ficar em pé e abaixe o peso com cuidado.',
  'Snatch Deadlift':
    'Com pegada larga de snatch e a barra na plataforma, pés sob o quadril com pontas para fora; agache até a barra com as costas em extensão total e olhar à frente.\nEmpurre pelos calcanhares e eleve o quadril, mantendo o ângulo das costas até a barra passar dos joelhos.\nLeve o quadril em direção à barra inclinando-se para trás e devolva a barra à plataforma invertendo o movimento.',
  'Snatch Pull':
    'Com a barra no chão perto das canelas, pegada larga de snatch, quadril abaixado, peso nos calcanhares, costas retas e ombros um pouco à frente da barra.\nEmpurre pelos calcanhares e estenda os joelhos na primeira puxada, mantendo o ângulo das costas e os braços retos até passar dos joelhos.\nNa segunda puxada, estenda o quadril ao a barra se aproximar do meio da coxa e acelere com um salto, estendendo quadril, joelhos e tornozelos.\nNão puxe com os braços para acelerar; ao final da segunda puxada o corpo deve ficar totalmente estendido, levemente atrás, com uma extensão violenta e breve.',
  'Snatch Shrug':
    'Com pegada larga e a barra pendurada no meio da coxa (gancho ou pronada), mantenha as costas retas e levemente inclinadas à frente.\nEncolha os ombros em direção às orelhas; pode usar mais carga que no snatch, mas sem deixar a execução lenta.',
  'Snatch from Blocks':
    'Com a barra carregada sobre caixas na altura desejada, pegada larga, pés sob o quadril com pontas para fora, quadril abaixado, peito erguido e ombros à frente da barra.\nEmpurre pela frente dos calcanhares para levantar a barra das caixas na primeira puxada.\nNa segunda puxada, estenda quadril, joelhos e tornozelos subindo a barra próxima ao corpo; encolha os ombros e flexione os cotovelos para os lados na extensão máxima.\nPuxe-se com força sob a barra levando os pés à posição de recepção e receba-a com o corpo baixo e os braços estendidos acima da cabeça.\nCom a barra alinhada sobre os calcanhares, cabeça e peito erguidos, empurre pelos calcanhares até ficar em pé e devolva o peso às caixas com cuidado.',
  'Speed Band Overhead Triceps':
    'Ancore uma faixa elástica no chão (por exemplo, na base de um banco inclinado) ou fique em pé sobre ela.\nPuxe a faixa atrás da cabeça com pegada pronada e cotovelos para cima; esta é a sua posição inicial.\nEstenda os cotovelos para esticar os braços, mantendo fixa a parte superior do braço.\nPause e volte à posição inicial.',
  'Speed Box Squat':
    'Prenda faixas na barra, ancoradas perto do chão; encurte-as se precisar de mais tensão.\nUse uma caixa de altura adequada e carregue a barra com 50-70% da sua repetição máxima, sem perder velocidade.\nApoie a barra na parte alta das costas, escápulas retraídas, costas arqueadas, corpo firme da cabeça aos pés.\nRetire a barra do rack, fique de frente para a caixa e sente-se para trás com controle até tocá-la.\nFaça uma breve pausa e saia explosivamente da caixa estendendo quadris e joelhos.',
  'Speed Squats':
    'Em um rack de agachamento, ajuste a barra à sua altura e apoie-a atrás dos ombros, abaixo do pescoço.\nSegure a barra dos dois lados e retire-a do suporte empurrando com as pernas enquanto endireita o tronco.\nAfaste os pés na largura dos ombros, pontas levemente para fora, cabeça erguida e costas retas: posição inicial.\nFlexione os joelhos e desça até menos de 90° entre coxa e panturrilha, inspirando; não deixe os joelhos passarem os pés.\nSuba a barra o mais rápido possível sem impulso, expirando e empurrando pelo calcanhar, até estender as pernas.\nRepita o número recomendado de repetições.',
  'Spell Caster':
    'Segure um halter em cada mão com pegada pronada, pés afastados, quadril e joelhos estendidos: posição inicial.\nLeve os dois halteres para um lado, próximo ao quadril, girando o tronco.\nCom os braços retos e os halteres paralelos ao chão, gire o tronco para o lado oposto.\nContinue alternando de um lado para o outro até completar a série.',
  'Spider Crawl':
    'Em prancha de bruços, apoie mãos e pontas dos pés, pés juntos, corpo reto e braços a 90°: posição inicial.\nLevante um pé do chão, gire a perna para fora e leve o joelho em direção ao cotovelo, o mais à frente possível.\nVolte a perna à posição inicial e repita com o lado oposto.',
  'Spider Curl':
    'Coloque a barra na parte do banco Scott onde você normalmente se sentaria, bem alinhada para não cair.\nFique na frente do banco Scott, deitado a 45°, com o tronco e o abdômen encostados no banco.\nApoie bem os pés (inclusive os dedos) no chão e coloque a parte superior dos braços sobre o apoio interno do banco.\nSegure a barra com pegada supinada (palmas para cima), mãos na largura dos ombros ou um pouco mais próximas.\nLevante a barra lentamente expirando e mantenha a contração por um segundo apertando os bíceps.\nAbaixe a barra lentamente até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Spinal Stretch':
    'Sente-se em uma cadeira com as costas retas e os pés apoiados no chão.\nEntrelace os dedos atrás da cabeça, com os cotovelos para fora e o queixo para baixo.\nGire a parte superior do corpo para um lado 3 vezes ao máximo, depois incline-se e leve o cotovelo ao chão junto ao joelho.\nVolte à posição ereta e repita para o outro lado.',
  'Split Clean':
    'Barra no chão junto às canelas, pegada pronada fora das pernas, quadril baixo, peso nos calcanhares, costas retas e ombros à frente da barra: posição inicial.\nPrimeira puxada: empurre pelos calcanhares, estenda os joelhos, mantenha o ângulo das costas e braços retos até passar dos joelhos.\nSegunda puxada: ao chegar na metade da coxa, estenda quadris, joelhos e tornozelos em um salto explosivo, sem puxar com os braços, até ficar estendido e levemente inclinado para trás.\nTerceira puxada: encolha os ombros com força, flexione os braços com cotovelos para cima e para fora, e puxe-se para baixo girando os cotovelos sob a barra.\nReceba a barra com os pés em afundo (um à frente, um atrás), apoiada nos ombros protraídos perto da garganta, mãos relaxadas, descendo até a posição mais baixa.\nRecupere-se empurrando pelos calcanhares, tronco ereto e cotovelos para cima, juntando os pés ao ficar em pé.',
  'Split Jerk':
    'Em pé com o peso na frente dos ombros, flexione os joelhos (pés sob o quadril) sem mover o quadril para trás.\nDesça um pouco e inverta com máxima potência, empurrando pelos calcanhares; tire a cabeça do caminho ao sair a barra dos ombros e leve os pés rápido à posição de recepção.\nMova os pés para uma base em afundo (um à frente, um atrás) com joelhos levemente flexionados e receba a barra com os braços travados sobre a cabeça.\nVolte à posição em pé, juntando os pés.',
  'Split Jump':
    'Adote uma base de afundo com um pé à frente, joelho flexionado e o joelho de trás quase tocando o chão.\nCertifique-se de que o joelho da frente fique alinhado com a linha média do pé.\nEstendendo as duas pernas, salte o mais alto possível, balançando os braços para ganhar impulso.\nNo ar, junte os pés e volte a colocá-los nas posições iniciais ao aterrissar.\nAbsorva o impacto voltando à posição inicial.',
  'Split Snatch':
    'Barra no chão perto das canelas, pegada larga, pés sob o quadril (pontas para fora se necessário), quadril baixo, peito erguido e ombros à frente da barra: posição inicial.\nPrimeira puxada: empurre pela frente dos calcanhares, levante a barra e mantenha o ângulo das costas até passar dos joelhos.\nSegunda puxada: estenda quadris, joelhos e tornozelos subindo a barra rápido e perto do corpo; na extensão máxima, encolha os ombros e flexione os cotovelos para os lados.\nPuxe-se com força para baixo da barra elevando-a acima da cabeça, movendo os pés para afundo (um à frente, um atrás), e receba-a o mais baixo possível com os braços estendidos.\nCom a barra alinhada sobre a frente dos calcanhares, cabeça e peito erguidos, empurre pelos calcanhares até ficar em pé, juntando os pés.\nDevolva o peso ao chão com cuidado.',
  'Split Squat with Dumbbells':
    'Posicione-se em uma base escalonada, com o pé de trás elevado e o pé da frente à frente.\nSegure um halter em cada mão, deixando-os pendurados ao lado do corpo: posição inicial.\nDesça flexionando joelho e quadril, com boa postura e o joelho da frente alinhado com o pé.\nNa parte baixa, empurre pelo calcanhar para estender joelho e quadril e voltar à posição inicial.',
  'Split Squats':
    'Em pé, salte para uma posição com as pernas afastadas (uma à frente, uma atrás), flexionando os joelhos e abaixando um pouco o quadril.\nAo descer, inverta de imediato saltando e trocando de perna; repita 5 a 10 vezes por lado.',
  'Squat Jerk':
    'Peso na frente dos ombros: flexione os joelhos sem mover o quadril para trás, desça pouco e inverta com potência empurrando os calcanhares, tirando a cabeça do caminho ao sair a barra.\nLeve os pés rápido à posição de recepção, logo fora do quadril (pontas para fora se necessário), e receba a barra em agachamento completo com os braços estendidos sobre a cabeça.\nCom a barra sobre a frente dos calcanhares, cabeça e peito erguidos, empurre pelos calcanhares até ficar em pé e abaixe o peso com cuidado.',
  'Squat with Bands':
    'Prenda as faixas nas extremidades da barra, ancoradas a suportes, ao rack ou a halteres, com a tensão adequada.\nApoie a barra atrás dos ombros com escápulas unidas e cotovelos girados para a frente, retire-a com arco lombar firme, pés mais afastados (mais ênfase em costas, glúteos, adutores e posteriores) e cabeça à frente.\nCom costas, ombros e core firmes, empurre joelhos e glúteos para fora e sente para trás com as canelas quase perpendiculares ao chão, descendo até passar da paralela (quadril na altura do joelho).\nCom o peso nos calcanhares e empurrando pés e joelhos para fora, suba guiando o movimento com a cabeça até a posição inicial.',
  'Squat with Chains':
    'Passe a corrente guia sobre as extremidades da barra, fixe a corrente pesada com mosquetão e ajuste o comprimento para que alguns elos toquem o chão no topo.\nApoie a barra atrás dos ombros com escápulas unidas e cotovelos girados para a frente, retire-a com arco lombar firme, pés mais afastados (mais ênfase em costas, glúteos, adutores e posteriores) e cabeça à frente.\nCom costas, ombros e core firmes, empurre joelhos e glúteos para fora e sente para trás com as canelas quase perpendiculares ao chão, descendo até passar da paralela (quadril na altura do joelho).\nCom o peso nos calcanhares e empurrando pés e joelhos para fora, suba guiando o movimento com a cabeça até a posição inicial.',
  'Squat with Plate Movers':
    'Ajuste a barra no rack logo abaixo da altura dos ombros, coloque uma anilha no chão a uns 60 cm atrás e apoie-a atrás dos ombros.\nSegure a barra com as duas mãos e retire-a do suporte empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack com base larga, pontas levemente para fora, um pé sobre a anilha e cabeça erguida: posição inicial.\nAbaixe lentamente flexionando joelhos e quadril até que o ângulo coxa-panturrilha fique um pouco menor que 90°.\nSuba a barra expirando, empurrando o chão com os calcanhares e estendendo quadril e joelhos.\nNo topo do movimento, dê um passo lateral, juntando os pés do outro lado da anilha.\nCom o pé interno, empurre a anilha deslizando-a pelo chão até onde você estava.\nColoque o pé interno sobre a anilha, adotando uma base larga para a próxima repetição.',
  'Squats - With Bands':
    'Reparta a faixa de forma igual entre os dois lados, pise no centro dela com os pés na largura dos ombros.\nSegure as faixas na mesma altura com pegada pronada (palmas para a frente) e as alças junto ao rosto: posição inicial.\nFlexione lentamente os joelhos e desça até que as coxas fiquem paralelas ao chão, expirando.\nEmpurre com os calcanhares para subir o corpo até a posição inicial, expirando.\nRepita o número recomendado de repetições.',
  Stairmaster:
    'Suba no stairmaster e escolha uma configuração manual ou um programa; insira sua idade e peso para estimar as calorias queimadas.\nMovimente as pernas com ritmo constante empurrando os pedais sem chegar ao chão; segure-se nas alças, que também medem a frequência cardíaca.\nÉ de baixo impacto mas mais exigente que outros cardios: uma pessoa de 150 lb queima mais de 300 calorias em 30 min, contra 175 caminhando.',
  'Standing Alternating Dumbbell Press':
    'Em pé com um halter em cada mão, leve-os aos ombros com palmas para a frente e cotovelos para fora: posição inicial.\nEstenda um braço empurrando o halter para cima, sem inclinar o corpo nem usar impulso, mantendo a outra mão no lugar.\nApós uma breve pausa, devolva o peso à posição inicial.\nRepita com o lado oposto, alternando entre os braços.',
  'Standing Barbell Calf Raise':
    'Em um rack de agachamento, ajuste a barra à sua altura e apoie-a atrás dos ombros, abaixo do pescoço.\nSegure a barra dos dois lados e retire-a do suporte empurrando com as pernas enquanto endireita o tronco.\nPés na largura dos ombros, pontas levemente para fora, cabeça erguida, costas retas, joelhos sem travar: posição inicial; pode usar um bloco sob a ponta dos pés para mais amplitude.\nEleve os calcanhares expirando, estenda os tornozelos ao máximo contraindo as panturrilhas sem flexionar o joelho, e mantenha um segundo no topo.\nAbaixe lentamente os calcanhares inspirando, flexionando os tornozelos até alongar as panturrilhas.\nRepita o número recomendado de repetições.',
  'Standing Barbell Press Behind Neck':
    'Em um rack de agachamento, ajuste a barra à sua altura e apoie-a atrás dos ombros, abaixo do pescoço.\nSegure a barra dos dois lados e retire-a do suporte empurrando com as pernas enquanto endireita o tronco.\nAfaste os pés na largura dos ombros, pontas levemente para fora, e mantenha as costas retas: posição inicial.\nEleve a barra acima da cabeça estendendo completamente os braços enquanto expira.\nMantenha a contração por um segundo e abaixe a barra à posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Bent-Over One-Arm Dumbbell Triceps Extension':
    'Com um halter em uma mão (palma para o tronco), flexione levemente os joelhos e incline o tronco quase paralelo ao chão, costas retas e cabeça erguida.\nMantenha o braço superior junto ao tronco e paralelo ao chão, com o antebraço para baixo formando 90° com o braço: posição inicial.\nCom o braço superior parado, estenda o tríceps expirando até o antebraço ficar paralelo ao chão e o braço estendido.\nMantenha a contração por um segundo no topo e abaixe lentamente o halter inspirando.\nRepita o movimento pelo número prescrito de repetições.\nTroque de braço e repita o exercício.',
  'Standing Bent-Over Two-Arm Dumbbell Triceps Extension':
    'Com um halter em cada mão (palmas para o tronco), incline o tronco quase paralelo ao chão, costas retas, cabeça erguida, braços superiores junto ao tronco e antebraços a 90° para baixo: posição inicial.\nCom os braços superiores parados, estenda o tríceps expirando até os antebraços ficarem paralelos ao chão e os braços estendidos.\nMantenha a contração por um segundo no topo e abaixe lentamente os halteres inspirando.\nRepita o movimento pelo número prescrito de repetições.',
  'Standing Biceps Cable Curl':
    'Em pé e erguido, segure uma barra de rosca na polia baixa, na largura dos ombros, cotovelos junto ao tronco, pegada supinada: posição inicial.\nCom os braços parados, flexione os cotovelos subindo a barra até os ombros, expirando e contraindo o bíceps por um segundo.\nAbaixe lentamente a barra até a posição inicial enquanto inspira.\nRepita o número recomendado de repetições.',
  'Standing Biceps Stretch':
    'Entrelace as mãos atrás das costas, palmas juntas, estique os braços e gire-os até as palmas ficarem voltadas para baixo.\nLevante os braços e mantenha a posição até sentir um alongamento nos bíceps.',
  'Standing Bradford Press':
    'Coloque a barra carregada na altura dos ombros no rack e apoie-a na frente dos ombros com pegada pronada na largura dos ombros: posição inicial.\nEstenda os cotovelos empurrando a barra acima da cabeça, sem travá-los, levando o peso para trás.\nAbaixe a barra até a parte de trás da cabeça até o cotovelo formar um ângulo reto.\nLevante a barra de volta acima da cabeça estendendo os cotovelos.\nAbaixe a barra até a posição inicial.\nAlterne assim até completar o número recomendado de repetições.',
  'Standing Cable Chest Press':
    'Ajuste as polias na altura do peito, fique a 30-60 cm à frente dos cabos com um em cada mão e escalone os pés para estabilidade.\nPosicione a parte superior do braço a 90° com as escápulas unidas: posição inicial.\nCom o corpo parado, estenda os cotovelos empurrando as alças para a frente até juntá-las na sua frente.\nFaça uma pausa no topo do movimento e volte à posição inicial.',
  'Standing Cable Lift':
    'Conecte uma alça padrão a uma torre e leve o cabo para a posição de polia mais baixa.\nDe lado para o cabo, segure a alça com uma mão e afaste-se à distância de um braço, com tensão no cabo e o braço estendido alinhado a ele.\nCom os pés na largura dos ombros, agache e segure a alça com as duas mãos, braços estendidos.\nEm um só movimento, puxe a alça para cima e através do corpo até estender os braços acima da cabeça.\nMantenha as costas retas e os braços próximos ao corpo, girando o pé de trás e estendendo as pernas para a amplitude completa.\nRetraia os braços e depois o corpo, voltando à posição neutra de forma lenta e controlada.\nRepita até a falha.\nDepois, reposicione-se e repita a mesma sequência do lado oposto.',
  'Standing Cable Wood Chop':
    'Conecte uma alça padrão a uma torre e leve o cabo para a posição de polia mais alta.\nDe lado para o cabo, segure a alça com uma mão e afaste-se à distância de um braço, com tensão no cabo e o braço estendido alinhado a ele.\nCom os pés na largura dos ombros, estenda a outra mão para cima e segure a alça com as duas mãos, braços estendidos.\nEm um só movimento, puxe a alça para baixo e através do corpo até o joelho da frente, girando o tronco.\nMantenha costas e braços retos e o core firme, girando o pé de trás e flexionando os joelhos para a amplitude completa.\nMantenha a base e os braços retos, voltando à posição neutra de forma lenta e controlada.\nRepita até a falha.\nDepois, reposicione-se e repita a mesma sequência do lado oposto.',
  'Standing Calf Raises':
    'Ajuste a alavanca acolchoada da máquina de panturrilha à sua altura.\nOmbros sob as almofadas, pontas dos pés no bloco e calcanhares para fora; empurre a alavanca estendendo quadril e joelhos (sem travar) até ficar ereto: posição inicial.\nEleve os calcanhares expirando, estenda os tornozelos ao máximo contraindo as panturrilhas sem flexionar o joelho, e mantenha um segundo no topo.\nAbaixe lentamente os calcanhares inspirando, flexionando os tornozelos até alongar as panturrilhas.\nRepita o número recomendado de repetições.',
  'Standing Concentration Curl':
    'Incline-se para a frente com um halter na mão que vai trabalhar; deixe o braço pendurado perpendicular ao chão, cotovelo para fora.\nFlexione o cotovelo e suba o peso sem mover a parte superior do braço; contraia o bíceps e pause no topo.\nAbaixe o halter de volta à posição inicial.\nRepita o número prescrito de repetições.',
  'Standing Dumbbell Calf Raise':
    'Fique em pé com um halter em cada mão; apoie a ponta dos pés em uma tábua firme de 5-7 cm, calcanhares tocando o chão.\nEleve os calcanhares contraindo as panturrilhas ao expirar; pés para frente, para dentro ou para fora conforme a ênfase. Pause 1 segundo no topo.\nInspire e abaixe lentamente os calcanhares até a posição inicial.\nRepita o número recomendado de vezes.',
  'Standing Dumbbell Press':
    'Em pé, pés na largura dos ombros, leve os halteres até a altura da cabeça com os cotovelos para fora a 90 graus.\nEstenda os cotovelos e suba os pesos juntos acima da cabeça, sem impulso das pernas nem inclinar o tronco para trás.\nFaça uma pausa e devolva lentamente o peso à posição inicial.',
  'Standing Dumbbell Reverse Curl':
    'Fique em pé reto com um halter em cada mão, pegada pronada, braços estendidos e pés na largura dos ombros.\nFlexione os cotovelos e suba os pesos contraindo o bíceps ao expirar; só os antebraços se movem, até a altura do ombro. Pause 1 segundo apertando.\nInspire e traga lentamente os halteres de volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Standing Dumbbell Straight-Arm Front Delt Raise Above Head':
    'Segure os halteres à frente das coxas, com as palmas voltadas para elas.\nMantenha os braços retos com leve flexão nos cotovelos, sem travá-los. Esta é a posição inicial.\nExpire e levante os halteres em semicírculo até estender os braços acima da cabeça.\nInspire e volte lentamente pelo mesmo trajeto à posição inicial.\nRepita o número recomendado de repetições.',
  'Standing Dumbbell Triceps Extension':
    'Fique em pé com os pés na largura dos ombros segurando um halter com as duas mãos; levante-o acima da cabeça até estender os braços.\nApoie o peso nas palmas com os polegares ao redor, palmas voltadas para o teto. Esta é a posição inicial.\nInspire e abaixe o peso em semicírculo atrás da cabeça até os antebraços tocarem o bíceps; cotovelos para dentro, parados e perpendiculares ao chão.\nExpire e use o tríceps para levantar o halter de volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Standing Dumbbell Upright Row':
    'Segure um halter em cada mão, pegada pronada, um pouco mais estreita que a largura dos ombros, apoiados nas coxas; braços estendidos, costas retas.\nExpire e suba os halteres próximos ao corpo com o deltoide lateral, cotovelos guiando e sempre mais altos que os antebraços, quase até o queixo. Pause 1 segundo no topo.\nInspire e abaixe os halteres lentamente de volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Standing Elevated Quad Stretch':
    'Fique de costas para um banco ou degrau, a cerca de 60-90 cm de distância.\nLevante uma perna para trás e apoie o pé no degrau, pelo peito do pé ou pela ponta, como for mais confortável.\nMantenha o joelho de apoio levemente flexionado sem passar da ponta do pé. Troque de lado.',
  'Standing Front Barbell Raise Over Head':
    'Fique em pé reto segurando a barra com as palmas para baixo, pegada mais estreita que a largura dos ombros.\nPés na largura dos ombros e cotovelos levemente flexionados. Esta é a posição inicial.\nExpire e levante a barra até ficar diretamente acima da cabeça, cotovelos sempre levemente flexionados.\nInspire e abaixe a barra à posição inicial após sentir a contração.\nRepita o número recomendado de repetições.',
  'Standing Gastrocnemius Calf Stretch':
    'Coloque o calcanhar direito em um degrau com o joelho estendido; incline-se e segure os dedos do pé direito com a mão direita, joelho esquerdo levemente flexionado, costas retas.\nApoie o peso na perna esquerda e coloque a mão esquerda sobre a coxa esquerda.\nPuxe os dedos do pé direito em direção ao joelho até sentir um alongamento na panturrilha.',
  'Standing Hamstring and Calf Stretch':
    'Passe um cinto, faixa ou corda ao redor de um pé e coloque-o à frente, em pé.\nFlexione a perna de trás, mantenha a da frente esticada, levante os dedos do pé da frente do chão e incline-se para a frente.\nPuxe o cinto para aumentar o alongamento na panturrilha. Mantenha 10-20 segundos e repita com o outro pé.',
  'Standing Hip Circles':
    'Fique em pé sobre uma perna, segurando-se em um apoio vertical.\nEleve o joelho que não está apoiado a 90 graus. Esta será a sua posição inicial.\nAbra o quadril o máximo possível, tentando fazer um grande círculo com o joelho.\nRealize este movimento lentamente por algumas repetições e repita do outro lado.',
  'Standing Hip Flexors':
    'Fique em pé, ereto, com a coluna vertical e o pé esquerdo levemente à frente do direito.\nFlexione os dois joelhos, levante o calcanhar de trás do chão e empurre o quadril direito para a frente (o alongamento será parcial, não profundo). Troque de lado.',
  'Standing Inner-Biceps Curl':
    'Fique em pé com um halter em cada mão, braços estendidos e cotovelos próximos ao tronco; pernas na largura dos ombros.\nGire as palmas para dentro, em pegada neutra. Esta é a posição inicial.\nExpire e suba os pesos para fora contraindo o bíceps sem mover o braço, girando o punho até terminar com pegada supinada (palmas para cima).\nMova apenas os antebraços até o bíceps ficar totalmente contraído e os halteres chegarem à altura do ombro, alinhados com o deltoide lateral.\nMantenha a contração por 1 segundo apertando o bíceps.\nInspire e traga lentamente os halteres de volta à posição inicial, girando os punhos de volta à pegada neutra.\nRepita o número recomendado de repetições.',
  'Standing Lateral Stretch':
    'Adote uma base um pouco mais larga que a distância do quadril, com os joelhos levemente flexionados.\nColoque a mão direita no quadril direito para apoiar a coluna.\nLevante o braço esquerdo em linha vertical, coloque a mão atrás da cabeça e mantenha-a ali enquanto inclina o tronco para a direita.\nMantenha o peso distribuído de forma uniforme entre as duas pernas (não se apoie no quadril esquerdo). Troque de lado.',
  'Standing Leg Curl':
    'Ajuste a alavanca à sua altura e incline o tronco 30-45 graus para a frente (mais recrutamento dos posteriores de coxa); apoie a alavanca atrás da perna direita, abaixo da panturrilha.\nCom a perna totalmente estendida e os pés retos, segure as alças laterais. Esta é a posição inicial.\nExpire e flexione a perna direita para cima ao máximo sem tirar a coxa do apoio; segure 1 segundo na contração total.\nInspire e volte à posição inicial. Repita o número recomendado de repetições.\nAgora faça o mesmo exercício com a perna esquerda.',
  'Standing Long Jump':
    'Faça na areia ou em outra superfície macia onde possa medir a distância; fique em meio agachamento com pés na largura dos ombros.\nUsando um grande balanço dos braços e um contramovimento das pernas, salte para a frente o mais longe que puder.\nTente aterrissar com os pés estendidos à sua frente, alcançando o mais longe possível com as pernas.\nMeça a distância do ponto de aterrissagem até o ponto de partida e registre os resultados.',
  'Standing Low-Pulley Deltoid Raise':
    'Em pé ao lado direito de uma polia baixa, cruze o corpo com a mão esquerda e segure o puxador com pegada pronada, braço descansando à frente; segure a máquina com a mão direita para apoio.\nMantenha as costas eretas e os pés na largura dos ombros. Esta é a posição inicial.\nExpire e eleve a mão esquerda para fora, cruzando o corpo, até a altura do ombro.\nMantenha 1 segundo no topo, depois inspire e abaixe lentamente o puxador até a posição inicial.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Low-Pulley One-Arm Triceps Extension':
    'Segure o puxador com o braço esquerdo, vire-se de costas para a polia baixa e eleve-o com as duas mãos acima da cabeça, palma para a frente, braço vertical; apoie a mão direita sobre o cotovelo esquerdo para estabilizar. Esta é a posição inicial.\nInspire e abaixe o peso em semicírculo atrás da cabeça até o antebraço tocar o bíceps; braço parado, cotovelo para dentro e perpendicular ao chão.\nExpire e use o tríceps para levantar o puxador até a posição inicial.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Military Press':
    'Coloque a barra na altura do peito em um rack de agachamento e segure-a com pegada pronada, mais afastada que a largura dos ombros.\nFlexione levemente os joelhos, apoie a barra na clavícula e levante-a do rack; dê um passo atrás com os pés na largura dos ombros.\nLevante a barra acima da cabeça estendendo os braços, na altura dos ombros e um pouco à frente da cabeça. Esta é a posição inicial.\nAbaixe a barra lentamente até a clavícula enquanto inspira.\nLevante a barra de volta à posição inicial enquanto expira.\nRepita o número recomendado de repetições.',
  'Standing Olympic Plate Hand Squeeze':
    'Fique em pé com as costas retas segurando uma anilha pela borda em cada mão, braços estendidos, pegada neutra e pés na largura dos ombros.\nInspire e abaixe as anilhas até os dedos quase estenderem, mas ainda sustentando o peso.\nExpire e feche as mãos para levantar as anilhas de volta à posição inicial.\nRepita o número recomendado de repetições do seu programa.',
  'Standing One-Arm Cable Curl':
    'Segure o puxador ao lado da polia baixa, a uma distância suficiente para o braço sustentar o peso.\nMantenha o braço parado e perpendicular ao chão, cotovelo para dentro e palma para a frente; segure a cintura com o outro braço para equilíbrio.\nExpire e flexione lentamente o puxador para cima sem mover o braço, até o antebraço tocar o bíceps.\nMantenha a contração apertando o bíceps, depois inspire e abaixe o puxador até a posição inicial.\nRepita o número recomendado de repetições.\nTroque de braço ao realizar este exercício.',
  'Standing One-Arm Dumbbell Curl Over Incline Bench':
    'Fique em pé atrás do encosto de um banco inclinado e apoie um halter sobre ele com pegada supinada, em uma das mãos.\nApoie a mão livre no canto ou lateral do banco, peito pressionado contra o encosto e pés firmes em posição afastada. Esta é a posição inicial.\nExpire e flexione o halter para cima contraindo o bíceps sem mover o braço, até a altura do ombro; segure a contração por 1 segundo.\nInspire e traga lentamente o halter de volta à posição inicial.\nRepita o número recomendado de repetições.\nTroque de braço ao realizar este exercício.',
  'Standing One-Arm Dumbbell Triceps Extension':
    'Fique em pé com um halter em uma mão, pés na largura dos ombros, e estenda totalmente o braço acima da cabeça com o dedo mindinho para o teto e a palma para a frente.\nEsta será sua posição inicial.\nInspire e abaixe o peso em semicírculo atrás da cabeça até o antebraço tocar o bíceps; braço parado, cotovelo para dentro e perpendicular ao chão.\nExpire e use o tríceps para levantar o halter de volta à posição inicial.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Overhead Barbell Triceps Extension':
    'Fique em pé segurando uma barra reta ou W com pegada pronada, mãos mais próximas que a largura dos ombros; pés na largura dos ombros.\nEleve a barra acima da cabeça até estender os braços, cotovelos para dentro. Esta é a posição inicial.\nInspire e abaixe a barra em semicírculo atrás da cabeça até os antebraços tocarem o bíceps; braços parados, cotovelos para dentro e perpendiculares ao chão.\nExpire e use o tríceps para levantar a barra de volta à posição inicial.\nRepita o número recomendado de repetições.',
  'Standing Palm-In One-Arm Dumbbell Press':
    'Segure um halter em uma mão com o braço estendido para o lado, pegada neutra; segure-se em um banco inclinado com o outro braço para equilíbrio.\nPés na largura dos ombros; levante lentamente o halter até formar 90 graus com o braço, antebraço perpendicular ao chão, pegada neutra sempre.\nLevante lentamente o halter até que o braço esteja totalmente estendido. Esta é a posição inicial.\nInspire e abaixe o peso até voltar a 90 graus com o braço.\nMantenha a contração por 1 segundo, depois expire e levante o peso até a posição inicial, apoiado no banco para o equilíbrio.\nRepita o número recomendado de repetições.\nTroque de braço e repita o exercício.',
  'Standing Palms-In Dumbbell Press':
    'Segure um halter em cada mão com braços estendidos para os lados, pegada neutra, pés na largura dos ombros; levante até formar 90 graus com os braços, antebraços perpendiculares ao chão. Posição inicial.\nMantendo a pegada neutra, levante lentamente os halteres até estender os braços por completo.\nInspire e abaixe os pesos até voltar a 90 graus com os braços.\nRepita o número recomendado de repetições.',
  'Standing Palms-Up Barbell Behind The Back Wrist Curl':
    'Fique em pé com as costas retas segurando a barra atrás dos glúteos, braços estendidos, pegada pronada (palmas para trás) e mãos na largura dos ombros.\nOlhe para a frente com os pés na largura dos ombros. Esta é a posição inicial.\nExpire e eleve a barra flexionando apenas os punhos, em semicírculo em direção ao teto.\nSegure a contração por 1 segundo; inspire e abaixe a barra à posição inicial.\nRepita o número recomendado de repetições.\nAo terminar, flexione os joelhos para abaixar a barra até o rack ou o chão; o mais fácil é pegá-la em um rack ou com ajuda de um parceiro.',
  'Standing Pelvic Tilt':
    'Fique com os pés na largura do quadril.\nFlexione levemente os joelhos para mantê-los soltos e elásticos.\nMova a pelve para a frente e para trás algumas vezes, depois mantenha o cóccix para a frente no alongamento.',
  'Standing Rope Crunch':
    'Prenda uma corda a uma polia alta e selecione um peso adequado.\nFique de costas para a torre de cabos e segure a corda com as duas mãos, mantendo-a junto à parte superior do peito. Esta é a posição inicial.\nFlexione a coluna em um abdominal, levando o peso para baixo o mais longe que puder.\nSegure a contração máxima por um momento antes de voltar à posição inicial.',
  'Standing Soleus And Achilles Stretch':
    'Fique em pé, pés na largura do quadril, um pé ligeiramente à frente do outro.\nFlexione os dois joelhos mantendo o calcanhar de trás no chão; troque de lado.',
  'Standing Toe Touches':
    'Fique em pé com espaço livre à frente e atrás de você.\nIncline-se pela cintura com as pernas retas, deixe o tronco e os braços pendurados por 10-20 segundos.',
  'Standing Towel Triceps Extension':
    'De pé, pés na largura dos ombros, braços estendidos acima da cabeça com uma toalha, cotovelos para dentro, palmas uma para a outra.\nParceiro segura a toalha; com os braços fixos perto da cabeça, abaixe os antebraços em semicírculo até tocar os bíceps. Inspire.\nVolte à posição inicial usando os tríceps para levantar a toalha; expire.\nRepita o número recomendado de repetições.',
  'Standing Two-Arm Overhead Throw':
    'De pé, pés na largura dos ombros com uma bola medicinal; leve-a atrás da cabeça flexionando os joelhos e inclinando o corpo atrás.\nArremesse a bola para a frente com força explosiva, flexionando o quadril e usando o corpo todo.\nArremesse a bola para um parceiro ou contra uma parede e receba-a ao quicar.',
  'Star Jump':
    'Comece em pé, pés na largura dos ombros, braços próximos ao corpo.\nAgache até a metade e salte de forma explosiva o mais alto possível, estendendo braços e pernas por completo.\nAo aterrissar, junte novamente braços e pernas e absorva o impacto com as pernas.',
  'Step Mill':
    'Suba na stepmill, escolha programa manual ou automático (pode inserir idade e peso) e mantenha as mãos nas alças para não cair.\nTem baixo impacto e alto gasto calórico: mais de 300 calorias em 30 min para uma pessoa de 150 lb, contra ~175 caminhando.',
  'Step-up with Knee Raise':
    'De pé na frente de uma caixa ou banco, pés juntos. Posição inicial.\nSuba colocando o pé esquerdo no banco, estenda quadril e joelho; em cima, flexione joelho e quadril direitos levando o joelho alto.\nDesça invertendo o movimento e repita a sequência com a perna oposta.',
  'Stiff Leg Barbell Good Morning':
    'Em um rack de agachamento, apoie a parte de trás dos ombros (abaixo do pescoço) na barra já carregada.\nSegure a barra dos dois lados e retire-a do rack empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack, pés na largura dos ombros, cabeça erguida e costas retas. Posição inicial.\nCom as pernas paradas, incline o tronco para a frente flexionando o quadril até ficar paralelo ao chão; inspire.\nSuba o tronco à posição inicial estendendo o quadril; expire.\nRepita o número recomendado de repetições.',
  'Stiff-Legged Barbell Deadlift':
    'Segure a barra com pegada pronada (palmas para baixo); use munhequeiras se o peso for alto.\nDe pé, tronco reto, pernas na largura dos ombros ou mais juntas, joelhos levemente flexionados. Posição inicial.\nCom os joelhos parados, abaixe a barra flexionando o quadril e mantendo as costas retas até sentir alongamento nos posteriores; inspire.\nSuba estendendo o quadril até a posição inicial; expire.\nRepita o número recomendado de repetições.',
  'Stiff-Legged Dumbbell Deadlift':
    'Pegue um par de halteres, braços estendidos ao lado do corpo.\nDe pé, tronco reto, pernas na largura dos ombros ou mais juntas, joelhos levemente flexionados. Posição inicial.\nCom os joelhos parados, abaixe os halteres flexionando a cintura e mantendo as costas retas até sentir alongamento nos posteriores; expire.\nSuba estendendo quadril e cintura até a posição inicial; inspire.\nRepita o número recomendado de repetições.',
  'Stomach Vacuum':
    'De pé, costas retas, pés na largura dos ombros, mãos nos quadris. Posição inicial.\nInspire todo o ar possível, expire ao máximo puxando o abdômen como se o umbigo tocasse a coluna, e segure.\nMantenha a contração isométrica por cerca de 20 segundos respirando normalmente; depois inspire e solte o abdômen.\nCom prática, estenda a contração além de 20 segundos, até 40-60 segundos.\nRepita o número recomendado de séries.',
  'Straight Bar Bench Mid Rows':
    'De pé sobre um banco, segure a barra carregada na extremidade com pegada pronada média, quadril atrás, peito erguido, coluna neutra.\nPuxe a barra até o tronco retraindo as escápulas e flexionando os cotovelos, com movimento controlado sem impulso.\nPause e volte lentamente com a barra à posição inicial, descendo por completo.',
  'Straight Raises on Incline Bench':
    'Coloque uma barra no chão atrás da parte de cima de um banco inclinado.\nDeite-se de bruços no banco, pegue a barra do chão com pegada pronada e braços retos pendurados. Posição inicial.\nEleve a barra à frente da cabeça mantendo os braços estendidos.\nVolte à posição inicial.',
  'Straight-Arm Dumbbell Pullover':
    'Coloque um halter em pé sobre um banco reto.\nDeite-se perpendicularmente ao banco em cruz, só os ombros apoiados, quadril fora do banco, pernas flexionadas e pés no chão.\nSegure o halter com as duas mãos, braços estendidos sobre o peito, palmas pressionando um lado do disco. Posição inicial.\nCuidado: use um halter bem fixado; um com anilhas soltas pode se desmontar e cair no seu rosto.\nCom braços retos, abaixe o peso em arco atrás da cabeça até sentir alongamento no peito; inspire.\nSuba o halter pelo mesmo arco até a posição inicial; expire.\nSegure um segundo na posição inicial e repita pelo número prescrito de repetições.',
  'Straight-Arm Pulldown':
    'Segure a barra larga da polia alta com pegada pronada mais aberta que os ombros; recue cerca de 60 cm.\nIncline o tronco à frente cerca de 30 graus, braços estendidos com leve flexão nos cotovelos; contraia os dorsais e prepare-se.\nCom braços retos, puxe a barra para baixo contraindo os dorsais até as mãos chegarem às coxas; expire.\nCom braços retos, volte à posição inicial; inspire.\nRepita o número recomendado de repetições.',
  'Stride Jump Crossover':
    'De pé ao lado de uma caixa, pé de dentro sobre ela, perto da borda.\nBalance os braços para cima, empurre com a perna de cima e salte o mais alto possível impulsionando o joelho oposto.\nAterrisse do lado oposto da caixa: o pé que estava em cima fica no chão e o outro sobe na caixa.\nRepita o movimento cruzando de volta para o outro lado.',
  'Sumo Deadlift':
    'Com a barra carregada no chão sobre o meio dos pés, pés bem afastados perto dos colares; flexione o quadril e segure a barra (pronada, mista ou gancho), ombros relaxados.\nRespire fundo, abaixe o quadril olhando para a frente, cabeça e peito erguidos; empurre o chão com o peso nos calcanhares e estenda quadril e joelhos.\nQuando a barra passar os joelhos, incline-se atrás levando o quadril até a barra e junte as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando a descida.',
  'Sumo Deadlift with Bands':
    'Passe as faixas curtas pela barra e pise dentro delas, sob a metade de trás do pé, onde você empurra o chão.\nCom a barra carregada no chão sobre o meio dos pés, pés bem afastados perto dos colares; flexione o quadril e segure a barra (pronada, mista ou gancho).\nRespire fundo, abaixe o quadril olhando para a frente, cabeça e peito erguidos; empurre o chão com o peso nos calcanhares e estenda quadril e joelhos.\nQuando a barra passar os joelhos, incline-se atrás levando o quadril até a barra e junte as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando a descida.',
  'Sumo Deadlift with Chains':
    'Prenda as correntes nas pontas da barra (ou apoie-as sobre ela) e mantenha as pontas longe das anilhas.\nCom a barra carregada no chão sobre o meio dos pés, pés bem afastados perto dos colares; flexione o quadril e segure a barra (pronada, mista ou gancho), ombros relaxados.\nRespire fundo, abaixe o quadril olhando para a frente, cabeça e peito erguidos; empurre o chão com o peso nos calcanhares e estenda quadril e joelhos.\nQuando a barra passar os joelhos, incline-se atrás levando o quadril até a barra e junte as escápulas.\nDevolva o peso ao chão flexionando o quadril e controlando a descida.',
  Superman:
    'Deite-se de bruços, esticado, braços totalmente estendidos à frente. Posição inicial.\nLevante ao mesmo tempo braços, pernas e peito do chão e segure 2 segundos, contraindo a lombar; expire.\nAbaixe lentamente braços, pernas e peito à posição inicial enquanto inspira.\nRepita o número recomendado de repetições do seu programa.',
  'Supine Chest Throw':
    'Deite-se de costas, joelhos flexionados (útil sem parceiro ou parede resistente).\nSegure a bola sobre o peito com as duas mãos por baixo.\nExplode para cima estendendo os cotovelos para arremessar a bola direto acima de você o mais alto possível.\nSegure a bola com as duas mãos ao descer.',
  'Supine One-Arm Overhead Throw':
    'Deite-se de costas, joelhos flexionados, segure a bola com uma mão totalmente estendida atrás da cabeça. Posição inicial.\nA partir do ombro, arremesse a bola para a frente enquanto se senta, buscando a distância máxima.\nArremesse a bola para um parceiro ou quique contra uma parede.',
  'Supine Two-Arm Overhead Throw':
    'Deite-se de costas com os joelhos flexionados.\nSegure a bola com as duas mãos, braços totalmente estendidos atrás da cabeça. Posição inicial.\nA partir do ombro, arremesse a bola para a frente enquanto se senta, buscando a distância máxima.\nArremesse a bola para um parceiro ou quique contra uma parede.',
  'Suspended Fallout':
    'Ajuste as tiras para que as alças fiquem em uma altura abaixo da cintura.\nDe pé, segure as alças e incline-se para as tiras até uma posição de flexão inclinada. Posição inicial.\nCom braços retos, incline-se mais para as tiras aproximando o corpo do chão, estendendo os ombros e elevando os braços acima da cabeça.\nMantenha a coluna neutra e o corpo reto; só os ombros se movem.\nPause na contração máxima e volte à posição inicial.',
  'Suspended Push-Up':
    'Ancore firmemente as tiras de suspensão na parte de cima de um rack ou outro objeto.\nIncline-se para as tiras, segure uma alça em cada mão e assuma a prancha de flexão, o mais paralelo ao chão possível, braços estendidos.\nCom o tronco reto e rígido, desça lentamente flexionando os cotovelos.\nPasse dos 90 graus nos cotovelos, faça uma pausa e estenda para voltar à posição inicial.',
  'Suspended Reverse Crunch':
    'Fixe as tiras de suspensão com as alças a cerca de 30 cm do chão, de costas para o rack, em prancha de flexão.\nColoque os pés nas alças mantendo postura reta, sem deixar o quadril cair. Posição inicial.\nFlexione joelhos e quadril levando os joelhos ao tronco, inclinando a pelve à frente e flexionando a coluna.\nNo topo do movimento, volte controladamente à posição inicial.',
  'Suspended Row':
    'Suspenda as tiras na altura do peito, segure uma alça em cada mão e incline-se para trás, corpo ereto, cabeça e peito erguidos, braços estendidos. Posição inicial.\nFlexione os cotovelos para iniciar o movimento, protraindo as escápulas.\nAo completar o movimento, pause e volte à posição inicial.',
  'Suspended Split Squat':
    'Suspenda as tiras com as alças a 45-75 cm do chão.\nDe costas para a estrutura, coloque o pé de trás na alça; cabeça à frente, peito erguido, joelho levemente flexionado. Posição inicial.\nDesça flexionando joelho e quadril em direção ao chão, com o peso no calcanhar, mantendo a postura.\nInverta o movimento estendendo quadril e joelho para voltar à posição inicial.',
  'Svend Press':
    'Comece em pé.\nPressione duas anilhas leves entre as mãos, perto do peito, dedos à frente, criando tensão isométrica nos peitorais. Posição inicial.\nAperte as anilhas entre as palmas e estenda os braços à frente em movimento controlado.\nPause no topo e volte lentamente à posição inicial.',
  'T-Bar Row with Handle':
    'Fixe a barra em um landmine ou canto para que não se mova e carregue o peso na ponta.\nFique sobre a barra, posicione uma pegada Double D junto ao colar e levante-se usando o quadril e as pernas.\nPostura ampla, quadril atrás, peito erguido, braços estendidos. Posição inicial.\nPuxe o peso até a parte alta do abdômen retraindo as escápulas e flexionando os cotovelos, sem impulso ou trapaça.\nPause e volte à posição inicial.',
  'Tate Press':
    'Deite-se em um banco reto com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.\nSuba os halteres um braço de cada vez até a frente, braços mais afastados que os ombros, pegada pronada, cotovelos para fora.\nCom os braços parados, desça os halteres em semicírculo até tocar o peito enquanto inspira, sem apoiá-los.\nExpire e suba os halteres com o tríceps em semicírculo inverso, juntos; trave os braços 1 segundo e desça o dobro mais devagar.\nRepita o número de repetições do seu programa de treino.',
  'The Straddle':
    'Sente-se com a coluna ereta e estenda as pernas à frente em forma de V.\nCom as mãos no chão, incline-se para a frente o máximo que puder. Segure 10 a 20 segundos.',
  'Thigh Abductor':
    'Sente-se na máquina abdutora, selecione o peso e segure as alças com as pernas bem posicionadas; mantenha o tronco parado. Posição inicial.\nExpire e pressione com as pernas para afastá-las da máquina.\nSegure a contração 1 segundo e inspire ao voltar as pernas, sem mover a parte superior do corpo.\nRepita o número recomendado de repetições.',
  'Thigh Adductor':
    'Sente-se na máquina adutora, selecione o peso e apoie as pernas nos apoios; segure as alças e mantenha o tronco parado. Posição inicial.\nExpire e pressione com as pernas para juntá-las.\nSegure a contração 1 segundo e inspire ao voltar as pernas; evite movimentos bruscos do tronco.\nRepita o número recomendado de repetições.',
  'Tire Flip':
    'Segure o pneu por baixo com os pés um pouco atrás e o peito empurrando contra ele.\nEstenda quadril, joelhos e tornozelos para levantar o pneu empurrando-o para cima.\nA 45 graus, dê um passo à frente, empurre um joelho contra o pneu, troque a pegada para o topo e empurre com força para virá-lo. Repita.',
  'Toe Touchers':
    'Deite-se de costas com os braços ao lado do corpo, palmas para baixo.\nPernas juntas, eleve-as quase perpendiculares ao chão com joelhos levemente flexionados e pés paralelos ao chão.\nEstenda os braços a 45 graus do chão. Posição inicial.\nCom a lombar no chão, expire e suba o tronco levando as mãos até tocar os dedos dos pés.\nInspire e desça lentamente o tronco e os braços à posição inicial, braços retos apontando para os pés.\nRepita o número recomendado de repetições.',
  'Torso Rotation':
    'Em pé, coluna ereta, segure uma bola suíça com as duas mãos e braços estendidos à frente. Posição inicial.\nGire o tronco para um lado olhando para a bola, depois para o lado oposto. Repita 10 a 20 vezes.',
  'Trail Running/Walking':
    'Use calçados adequados para correr ou caminhar em trilhas; dê passos curtos e joelhos flexionados na descida para reduzir o impacto e evitar quedas.\nUma pessoa de 150 lb queima mais de 200 calorias em 30 min subindo (vs. 175 no plano) e mais de 500 correndo na trilha em 30 min.',
  'Trap Bar Deadlift':
    'Carregue uma barra hexagonal (trap bar) no chão, fique em pé no centro e segure as duas alças.\nAbaixe o quadril, olhe para a frente e mantenha o peito erguido.\nEmpurre com os calcanhares e estenda quadril e joelhos sem arredondar as costas.\nAbaixe o peso ao chão de forma controlada ao terminar.',
  'Tricep Dumbbell Kickback':
    'Com um halter em cada mão, palmas para o tronco, costas retas e joelhos levemente flexionados, incline-se pela cintura quase paralelo ao chão; braços junto ao tronco, antebraços para baixo formando 90 graus. Posição inicial.\nCom a parte superior do braço parada, expire e estenda o tríceps até o braço ficar totalmente esticado.\nApós uma breve pausa na contração, inspire e abaixe lentamente à posição inicial.\nRepita o movimento pelo número prescrito de repetições.',
  'Tricep Side Stretch':
    'Leve o braço direito sobre o ombro esquerdo, segure o cotovelo com a mão esquerda até sentir o alongamento no tríceps; repita com o outro braço.',
  'Triceps Overhead Extension with Rope':
    'Prenda uma corda a uma polia baixa, selecione uma carga adequada e fique de costas para o cabo.\nPosicione as mãos atrás da cabeça, cotovelos apontando para cima; incline-se levemente para longe da máquina com postura escalonada. Posição inicial.\nEstenda os cotovelos mantendo o braço no lugar e eleve as mãos acima da cabeça.\nContraia o tríceps no topo e abaixe lentamente a carga à posição inicial.',
  'Triceps Pushdown':
    'Prenda uma barra reta ou angulada a uma polia alta com pegada pronada na largura dos ombros.\nEm pé, tronco reto com leve inclinação à frente, braços junto ao corpo e perpendiculares ao chão. Posição inicial.\nCom o tríceps, abaixe a barra até tocar as coxas com os braços estendidos, expirando; mova somente os antebraços, braços parados.\nMantenha 1 segundo a contração e inspire ao subir lentamente a barra ao ponto de partida.\nRepita pelo número recomendado de repetições.',
  'Triceps Pushdown - Rope Attachment':
    'Prenda uma corda a uma polia alta com pegada neutra (palmas uma para a outra).\nEm pé, tronco reto com leve inclinação à frente, braços junto ao corpo e perpendiculares ao chão. Posição inicial.\nCom o tríceps, abaixe a corda para a lateral das coxas até estender os braços, expirando; mova somente os antebraços.\nMantenha 1 segundo a contração e inspire ao subir lentamente a corda ao ponto de partida.\nRepita pelo número recomendado de repetições.',
  'Triceps Pushdown - V-Bar Attachment':
    'Prenda uma barra em V a uma polia alta com pegada pronada na largura dos ombros.\nEm pé, tronco reto com leve inclinação à frente, braços perpendiculares ao chão, polegares mais altos que os mínimos. Posição inicial.\nCom o tríceps, abaixe a barra até tocar as coxas com os braços estendidos, expirando; mova somente os antebraços.\nMantenha 1 segundo a contração e inspire ao subir lentamente a barra ao ponto de partida.\nRepita pelo número recomendado de repetições.',
  'Triceps Stretch':
    'Leve a mão atrás da cabeça, segure o cotovelo e puxe suavemente; mantenha 10 a 20 segundos e troque de lado.',
  'Tuck Crunch':
    'Deite-se de costas com os braços ao lado do corpo, palmas para baixo.\nCruze um tornozelo sobre o outro e eleve as pernas até as coxas ficarem perpendiculares ao chão, joelhos e pés paralelos ao chão.\nTire os braços do chão e cruze-os sobre o peito. Posição inicial.\nCom a lombar no chão, expire e eleve lentamente o tronco.\nInspire e abaixe o tronco à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Two-Arm Dumbbell Preacher Curl':
    'Segure um halter em cada mão e apoie os braços no banco Scott, halteres na altura dos ombros. Posição inicial.\nInspire e abaixe lentamente os halteres até estender o braço e alongar totalmente o bíceps.\nExpire e suba os halteres até contrair totalmente o bíceps na altura dos ombros.\nContraia os bíceps 1 segundo e repita pelo número recomendado de repetições.',
  'Two-Arm Kettlebell Clean':
    'Coloque dois kettlebells entre os pés; leve o quadril para trás e olhe para a frente. Posição inicial.\nSuba os kettlebells até os ombros estendendo pernas e quadril, girando os punhos ao subir.\nAbaixe os kettlebells à posição inicial e repita.',
  'Two-Arm Kettlebell Jerk':
    'Suba os kettlebells até os ombros girando os punhos (palmas para a frente), agache alguns centímetros, empurre-os rápido acima da cabeça, agache novamente sob eles e fique em pé com os braços travados.',
  'Two-Arm Kettlebell Military Press':
    'Suba os kettlebells até os ombros estendendo pernas e quadril, girando os punhos para as palmas ficarem para a frente.\nEmpurre os kettlebells para cima e para fora; ao passarem a cabeça, incline-se para apoiá-los atrás da cabeça, contraindo dorsais, glúteos e abdômen.',
  'Two-Arm Kettlebell Row':
    'Coloque dois kettlebells à frente dos pés, flexione levemente os joelhos e leve o quadril para trás inclinando-se à frente. Posição inicial.\nPuxe os kettlebells até o abdômen retraindo as escápulas e flexionando os cotovelos, costas retas. Abaixe e repita.',
  'Underhand Cable Pulldowns':
    'Sente-se na máquina de puxada com barra larga na polia superior; ajuste o apoio de joelhos à sua altura.\nSegure a barra com pegada supinada, mãos mais próximas que a largura dos ombros.\nCom os braços estendidos à frente, incline o tronco 30 graus para trás, curvando a lombar e projetando o peito. Posição inicial.\nExpire e puxe a barra até o peito levando ombros e braços para baixo e para trás; cotovelos perto do corpo, tronco parado, antebraços só seguram a barra.\nMantenha 1 segundo a contração e inspire ao voltar a barra à posição inicial com braços estendidos e dorsais alongados.\nRepita este movimento pelo número prescrito de repetições.',
  'Upper Back Stretch':
    'Entrelace os dedos com os polegares para baixo e arredonde os ombros enquanto estende as mãos para a frente.',
  'Upper Back-Leg Grab':
    'Sentado, incline-se à frente e abrace as coxas por baixo com os dois braços.\nJoelhos juntos e pernas estendidas, leve o peito em direção aos joelhos; ou alongue o meio das costas afastando-as dos joelhos enquanto os abraça.',
  'Upright Barbell Row':
    'Segure uma barra com pegada pronada um pouco mais estreita que os ombros, apoiada nas coxas, braços estendidos com leve flexão nos cotovelos, costas retas. Posição inicial.\nExpire e eleve a barra com os ombros laterais levando os cotovelos para cima e para os lados, perto do corpo, até quase tocar o queixo; cotovelos sempre mais altos que os antebraços; pausa de 1 segundo no topo.\nInspire e abaixe a barra lentamente à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Upright Cable Row':
    'Segure uma barra reta na polia baixa com pegada pronada um pouco mais estreita que os ombros, apoiada nas coxas, braços estendidos com leve flexão nos cotovelos, costas retas. Posição inicial.\nExpire e eleve a barra com os ombros laterais, perto do corpo, até quase tocar o queixo; cotovelos sempre mais altos que os antebraços; tronco parado, pausa de 1 segundo no topo.\nInspire e abaixe a barra lentamente à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Upright Row - With Bands':
    'Fique sobre uma faixa elástica com tensão desde os braços estendidos; segure as alças com pegada pronada um pouco mais estreita que os ombros, apoiadas nas coxas, costas retas. Posição inicial.\nExpire e eleve as alças com os ombros laterais, perto do corpo, até quase tocarem o queixo; cotovelos sempre mais altos que os antebraços; tronco parado, pausa de 1 segundo no topo.\nInspire e abaixe as alças lentamente à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Upward Stretch':
    'Estenda as duas mãos retas acima da cabeça, com as palmas unidas.\nEmpurre lentamente as mãos para cima e para trás, mantendo as costas retas.',
  'V-Bar Pulldown':
    'Sente-se na máquina de puxada com uma barra em V na polia superior.\nAjuste o apoio de joelhos à sua altura.\nSegure a barra em V com pegada neutra; projete o peito e incline-se 30 graus para trás para ativar os dorsais. Posição inicial.\nCom os dorsais, puxe a barra juntando as escápulas até quase tocar o peito, expirando; mantenha o tronco parado.\nMantenha 1 segundo a contração e inspire ao voltar lentamente à posição inicial.\nRepita pelo número prescrito de repetições.',
  'V-Bar Pullup':
    'Posicione o centro da barra em V no centro da barra fixa, com as alças voltadas para baixo.\nSegure de cada lado e pendure-se; projete o peito e incline-se levemente para trás para ativar os dorsais. Posição inicial.\nCom os dorsais, eleve o tronco inclinando a cabeça para trás para não bater o queixo, expirando, até quase tocar a barra em V com o peito.\nMantenha 1 segundo a contração e inspire ao descer lentamente à posição inicial.\nRepita pelo número prescrito de repetições.',
  'Vertical Swing':
    'Segure o halter pendurado entre as pernas com as duas mãos, costas retas e cabeça erguida.\nBalance o halter entre as pernas flexionando o quadril e dobrando levemente os joelhos.\nInverta com força estendendo quadril, joelhos e tornozelos para se impulsionar para cima, balançando o halter sobre a cabeça.\nAo aterrissar, absorva o impacto com as pernas e traga o halter ao tronco antes da próxima repetição.',
  'Walking, Treadmill':
    'Suba na esteira e escolha o modo manual ou um programa; informe idade e peso para estimar calorias, e ajuste a inclinação para variar a intensidade.\nCaminhe em ritmo moderado a rápido (não lento): 150 lb queimam cerca de 175 cal em 30 min a 4 mph, vs. 450 cal correndo ao dobro da velocidade; mantenha boa postura e use as alças só se necessário.',
  'Weighted Ball Hyperextension':
    'Deite-se sobre uma bola de exercício com o tronco paralelo ao chão, pontas dos pés no chão; segure uma anilha sob o queixo ou atrás do pescoço. Posição inicial.\nExpire e eleve lentamente o tronco flexionando na cintura e na lombar.\nMantenha a contração lombar 1 segundo e inspire ao abaixar o tronco à posição inicial.\nRepita pelo número de repetições do seu programa.',
  'Weighted Ball Side Bend':
    'Deite-se sobre uma bola de exercício com o lado esquerdo do tronco (cintura, quadril, ombro) apoiado nela.\nPés no chão, pernas cruzadas pendendo da bola; segure uma anilha com a mão direita junto à cabeça, com o lado liso contra ela.\nCruze o braço esquerdo sobre o tronco, palma sobre os oblíquos, ângulo reto entre antebraço e braço. Posição inicial.\nExpire e eleve a lateral do tronco flexionando lateralmente na cintura.\nMantenha a contração 1 segundo e inspire ao abaixar lentamente à posição inicial.\nRepita pelo número recomendado de repetições.\nTroque de lado e repita o exercício.',
  'Weighted Bench Dip':
    'Coloque um banco atrás de você e outro à frente, perpendiculares ao corpo; segure a borda de um com as mãos na largura dos ombros e braços estendidos.\nEstenda as pernas sobre o outro banco, paralelas ao chão, tronco perpendicular ao chão; peça a um parceiro que coloque o halter no seu colo (melhor com ajuda, por risco de lesão). Posição inicial.\nInspire e abaixe o corpo flexionando os cotovelos até um ângulo pouco menor que 90 graus entre braço e antebraço; cotovelos o mais juntos possível, antebraços sempre para baixo.\nExpire e use o tríceps para elevar o tronco de volta à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Weighted Crunches':
    'Deite-se de costas com os pés no chão ou em um banco, joelhos flexionados a 90 graus.\nSegure um peso junto ao peito ou estendido sobre o tronco. Posição inicial.\nExpire e descole lentamente os ombros do chão cerca de 10 cm, com a lombar sempre no chão.\nNo topo, contraia os abdominais e faça uma pausa breve.\nInspire e abaixe lentamente à posição inicial.',
  'Weighted Jump Squat':
    'Posicione uma barra com pouca carga nas costas (ou use colete com peso, saco de areia ou outra resistência).\nO peso deve ser leve para não atrapalhar o movimento; pés um pouco além da largura dos ombros, cabeça e peito erguidos. Posição inicial.\nCom contramovimento, agache parcialmente e inverta de imediato para saltar com explosão estendendo quadril, joelhos e tornozelos; mantenha boa postura.\nAo retornar ao chão, absorva o impacto com as pernas.',
  'Weighted Pull Ups':
    'Prenda um peso a um cinto de lastro na cintura; segure a barra fixa com palmas para a frente, pegada média na largura dos ombros, braços estendidos.\nIncline o tronco 30 graus para trás, curvando a lombar e projetando o peito. Posição inicial.\nExpire e puxe o tronco até a cabeça passar das mãos, contraindo as escápulas para trás e para baixo no topo.\nInspire e abaixe lentamente à posição inicial, braços estendidos e dorsais alongados.',
  'Weighted Sissy Squat':
    'Em pé, pés na largura dos ombros e calcanhares elevados, segure-se com uma mão em um rack de agachamento e sustente uma anilha sobre o peito com a outra. Posição inicial.\nApoiando-se com um braço, flexione os joelhos e inspire ao descer o tronco levando pelve e joelhos à frente até quase 90 graus entre coxa e panturrilha; mantenha 1 segundo o alongamento.\nExpire e use as coxas para elevar o tronco à posição inicial.\nRepita pelo número recomendado de vezes.',
  'Weighted Sit-Ups - With Bands':
    'Prenda as faixas na base do banco declinado, com as alças voltadas para dentro para alcançá-las ao deitar.\nEncaixe as pernas no banco declinado; segure as faixas com pegada pronada perto da clavícula e gire para pegada neutra (palmas ao tronco); mantenha os braços parados. Posição inicial.\nExpire e eleve o tronco até ficar perpendicular ao chão; mantenha 1 segundo e inspire ao abaixar à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Weighted Squat':
    'Suba em dois bancos planos separados na largura dos ombros e prenda o cinto de lastro com a carga escolhida; pés voltados para fora.\nEm pé, com o peso pendurado entre as pernas, estenda os braços ao lado do corpo. Posição inicial.\nInspire e flexione os joelhos, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar pouco menor que 90 graus; os joelhos não devem passar da ponta dos pés.\nExpire e suba empurrando o banco com a parte da frente do pé, estendendo as pernas à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Wide Stance Barbell Squat':
    'Em um rack de agachamento por segurança, ajuste a altura da barra, carregue-a e apoie-a na parte de trás dos ombros, abaixo do pescoço.\nSegure a barra dos dois lados e tire-a do rack empurrando com as pernas enquanto endireita o tronco.\nAfaste-se do rack com as pernas mais abertas que os ombros, pontas dos pés levemente para fora, cabeça erguida e costas retas. Posição inicial.\nInspire e flexione os joelhos abaixando a barra, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar pouco menor que 90 graus; os joelhos não devem passar da ponta dos pés.\nExpire e suba a barra empurrando o chão com o calcanhar, estendendo as pernas à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Wide Stance Stiff Legs':
    'Com uma barra carregada no chão, assuma uma base larga e flexione o quadril para segurá-la, quadril o mais para trás possível, pernas quase retas, costas retas, cabeça e peito erguidos. Posição inicial.\nAtive o quadril levando-o para a frente com os braços pendurados retos até ficar em pé; volte lentamente à posição inicial (o peso não precisa tocar o chão nas repetições seguintes).',
  'Wide-Grip Barbell Bench Press':
    'Deite-se em um banco reto, pés firmes no chão; com pegada pronada larga (3 polegadas além da largura dos ombros por mão), tire a barra do rack com os braços travados, perpendicular ao tronco. Posição inicial.\nInspire e desça lentamente até sentir a barra na parte média do peito.\nApós 1 segundo de pausa, expire e empurre a barra com o peito à posição inicial; trave os braços e contraia o peito, mantenha 1 segundo e desça o dobro mais devagar.\nRepita o movimento pelo número prescrito de repetições.',
  'Wide-Grip Decline Barbell Bench Press':
    'Deite-se em um banco declinado com os pés presos na frente; com pegada pronada larga (3 polegadas além da largura dos ombros por mão), tire a barra do rack com os braços travados, perpendicular ao tronco. Posição inicial.\nInspire e desça lentamente até sentir a barra na parte inferior do peito.\nApós 1 segundo de pausa, expire e empurre a barra com o peito à posição inicial; trave os braços e contraia o peito, mantenha 1 segundo e desça o dobro mais devagar.\nRepita o movimento pelo número prescrito de repetições.',
  'Wide-Grip Decline Barbell Pullover':
    'Deite-se em um banco declinado com as pernas presas; segure a barra atrás da cabeça com pegada pronada mais larga que os ombros e levante-a do chão.\nCom os braços totalmente estendidos e perpendiculares ao chão. Posição inicial.\nInspire e desça a barra para trás em semicírculo como se fosse tocar o chão, até os braços ficarem paralelos ao chão; mantenha-os sempre estendidos, o movimento é só no ombro.\nExpire e eleve a barra à posição inicial, mantendo o controle total.\nRepita o movimento pelo número prescrito de repetições do seu programa de treino.\nAo terminar a série, abaixe a barra até a altura da cabeça e solte-a.',
  'Wide-Grip Lat Pulldown':
    'Sente-se na máquina de puxada com barra larga na polia superior; ajuste o apoio de joelhos à sua altura.\nSegure a barra com palmas para a frente: pegada larga (mãos mais afastadas que os ombros), média (igual aos ombros) ou fechada (mais próxima que os ombros), conforme sua rotina.\nCom os braços estendidos à frente, incline o tronco 30 graus para trás, curvando a lombar e projetando o peito. Posição inicial.\nExpire e puxe a barra até o peito levando ombros e braços para baixo e para trás; tronco parado, antebraços só seguram a barra, sem puxar com eles.\nMantenha 1 segundo apertando as escápulas e inspire ao subir lentamente à posição inicial, braços estendidos e dorsais alongados.\nRepita este movimento pelo número prescrito de repetições.',
  'Wide-Grip Pulldown Behind The Neck':
    'Sente-se na máquina de puxada com barra larga na polia superior; ajuste o apoio de joelhos à sua altura.\nSegure a barra com palmas para a frente: pegada larga (mãos mais afastadas que os ombros), média (igual aos ombros) ou fechada (mais próxima que os ombros).\nCom os braços estendidos à frente, leve o tronco e a cabeça para a frente, imaginando uma linha da barra até a nuca. Posição inicial.\nExpire e puxe a barra até tocar a nuca levando ombros e braços para baixo e para trás; tronco parado, antebraços só seguram a barra, sem puxar com eles.\nMantenha 1 segundo apertando as escápulas e inspire ao subir lentamente à posição inicial, braços estendidos e dorsais alongados.\nRepita este movimento pelo número prescrito de repetições.',
  'Wide-Grip Rear Pull-Up':
    'Segure a barra fixa com palmas para a frente e pegada larga.\nCom os braços estendidos à frente, leve o tronco e a cabeça para a frente, linha imaginária da barra até a nuca. Posição inicial.\nExpire e puxe o tronco levando ombros e braços para baixo e para trás, inclinando a cabeça à frente, até a barra ficar perto da nuca; tronco parado, antebraços só seguram a barra.\nInspire e abaixe lentamente à posição inicial, braços estendidos e dorsais alongados.\nRepita este movimento pelo número prescrito de repetições.',
  'Wide-Grip Standing Barbell Curl':
    'Em pé, tronco ereto, segure a barra com pegada externa larga, palmas para a frente, cotovelos perto do tronco. Posição inicial.\nCom a parte superior do braço parada, expire e eleve a barra contraindo os bíceps; somente os antebraços se movem.\nContinue até contrair totalmente os bíceps com a barra na altura dos ombros; mantenha 1 segundo contraindo forte.\nInspire e abaixe lentamente a barra à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Wind Sprints':
    'Pendure-se em uma barra fixa com pegada pronada, braços e pernas estendidos. Posição inicial.\nEleve rápido um joelho o mais alto possível, sem balançar o corpo nem as pernas.\nInverta de imediato baixando essa perna enquanto eleva o joelho oposto o mais alto possível.\nContinue alternando as pernas até completar a série.',
  Windmills:
    'Deite-se de costas com os braços estendidos para os lados e as pernas retas. Posição inicial.\nLevante uma perna e cruze-a rápido sobre o corpo, tentando tocar o chão perto da mão oposta.\nVolte à posição inicial e repita com a perna oposta, alternando por 10 a 20 repetições.',
  "World's Greatest Stretch":
    'Em afundo à frente, pé da frente totalmente apoiado e pé de trás na ponta, agache até o joelho quase tocar o chão, tronco ereto; mantenha 10 a 20 segundos.\nApoie no chão o braço do lado da perna da frente, cotovelo junto ao pé; apoie a outra mão paralela à perna da frente para se sustentar.\nApós 10 a 20 segundos, coloque as mãos dos dois lados do pé da frente, levante a ponta do pé e estenda a perna (reposicione a perna de trás se precisar); mantenha 10 a 20 segundos e repita do outro lado.',
  'Wrist Circles':
    'Em pé, pés na largura dos ombros, eleve os braços para os lados formando um T, estendidos e paralelos ao chão, palmas para baixo. Posição inicial.\nCom o corpo parado, exceto os punhos, gire os dois para a frente em círculos, respirando normalmente.\nRepita pelo número recomendado de repetições.',
  'Wrist Roller':
    'Em pé, pés na largura dos ombros, segure um rolo de punho com pegada pronada (palmas para baixo).\nEleve lentamente os dois braços estendidos e paralelos ao chão à frente, corda sem enrolar; corpo parado exceto os antebraços. Posição inicial.\nGire um punho de cada vez para cima para enrolar a corda e elevar o peso até a barra.\nQuando o peso chegar à barra, abaixe-o lentamente girando o punho para baixo até a posição inicial.\nRepita pelo número prescrito de repetições do seu programa.',
  'Wrist Rotations with Straight Bar':
    'Segure uma barra com as duas mãos, palmas para baixo, separadas na largura dos ombros. Posição inicial.\nAlternando as mãos, estenda o punho como se enrolasse um jornal; continue até a falha.\nInverta flexionando o punho, enrolando na direção oposta; continue alternando até a falha.',
  'Yoke Walk':
    'O yoke é feito com um aparelho de yoke, ou às vezes com geladeiras ou outros objetos pesados.\nApoie o aparelho na parte de trás dos ombros; com o olhar à frente e as costas arqueadas, levante-o empurrando com os calcanhares.\nCaminhe o mais rápido possível com passos curtos, segurando os postes laterais para estabilizá-lo, pela distância indicada (geralmente 75 a 100 pés).',
  'Zercher Squats':
    'Em um rack de agachamento por segurança, ajuste a barra a uma altura entre a cintura e o peito; una as mãos e apoie a barra entre o antebraço e o braço.\nLevante a barra para que fique apoiada sobre os antebraços, como se estivesse com os braços cruzados atravessados pela barra.\nAfaste-se do rack com as pernas na largura dos ombros, pontas dos pés levemente para fora, cabeça erguida e costas retas. Posição inicial (pode usar qualquer uma das três bases de pés).\nInspire e flexione os joelhos abaixando a barra, costas retas e cabeça erguida, até o ângulo coxa-panturrilha ficar pouco menor que 90 graus; os joelhos não devem passar da ponta dos pés.\nExpire e suba a barra empurrando o chão com a parte da frente do pé, estendendo as pernas à posição inicial.\nRepita pelo número recomendado de repetições.',
  'Zottman Curl':
    'Em pé, tronco ereto, um halter em cada mão, braços estendidos e cotovelos perto do tronco.\nPalmas das mãos voltadas uma para a outra. Posição inicial.\nCom a parte superior do braço parada, expire e eleve os halteres contraindo os bíceps, girando o punho para pegada supinada (palmas para cima), até contrair totalmente na altura dos ombros.\nMantenha 1 segundo contraindo os bíceps.\nNa contração, gire o punho para pegada pronada (palmas para baixo), polegar mais alto que o mínimo.\nAbaixe lentamente os halteres com a pegada pronada.\nAo se aproximarem das coxas, gire o punho de volta para pegada neutra (palmas para o corpo).\nRepita pelo número recomendado de repetições.',
  'Zottman Preacher Curl':
    'Segure um halter em cada mão, apoie os braços no banco Scott, halteres na altura dos ombros, cotovelos flexionados, palmas para baixo. Posição inicial.\nInspire e abaixe lentamente os halteres com palmas para baixo até estender o braço e alongar totalmente o bíceps.\nGire os punhos embaixo para as palmas ficarem voltadas para cima.\nExpire e eleve os halteres até contrair totalmente os bíceps na altura dos ombros, dedo mínimo mais alto que o polegar para a contração total.\nContraia os bíceps 1 segundo e gire os punhos para as palmas ficarem para baixo novamente.\nRepita pelo número recomendado de repetições.',
};
